--[[
  yanamin.lua — Rejoin Engine publish loader.
  Generated by tools/bundle_loader.js; edit sources and rebuild.
  Source: https://github.com/apengjers/rejoin
  Bundled: 49 modules, entry main.lua.
  State: /sdcard/yanamin (override with YANAMIN_HOME).
]]
local __ya_sources = {}
__ya_sources["config.template"] = [[
-- Config template for Rejoin Engine
return {
    -- AutoExecute is now managed DIRECTLY in the app's autoexecute folder: scripts are
    -- added/edited/deleted from the "Script Manager" menu into `appAutoExecutePath`
    -- (e.g. /sdcard/Delta/Autoexecute). No separate staging folder, no deploy step.
    monitorInterval = 8,
    recoveryDelay = 3,
    recoveryRetries = 3,
    checkTimeout = 15,
    debug = true,
    -- Console log verbosity. Hidden below this level: "DEBUG" shows everything,
    -- "INFO" is the default (hides the monitor's per-probe/su debug spam).
    logLevel = "INFO",
    logPath = "data/rejoin.log",
    -- Optional fast filter for auto-detect clone scan (e.g. "com.apengjers."). Empty = disabled.
    clonePackagePrefix = "",
    -- Seconds an app may stay frozen/stuck before the monitor force-relaunches it.
    -- (5 minutes = 300s). Clones that are NOT logged in are never relaunched regardless
    -- (see cookiePath / Auth detection).
    freezeTimeout = 300,
    -- Seconds after launch that a running app is still considered "starting" before it
    -- is judged ingame vs stuck.
    gracePeriod = 30,
    -- Enable ANR (Application Not Responding) detection via logcat (best-effort, needs
    -- readable logcat, more reliable with root).
    anrCheckEnabled = true,
    -- RSS threshold for diagnostics only; never triggers a restart.
    minRss = 300,
    -- Timeout (seconds) for each shell command (via the `timeout` tool) so a hung
    -- su/dumpsys call can't freeze the whole tool / stop the terminal accepting input.
    shellTimeout = 10,
    -- Automatic per-cycle diagnostics: written to this file whenever the app is
    -- launched via Menu 1 (Launch + Monitor). Shows running/isActive/RSS per clone.
    launchLogPath = "launch.log",
    launchLogEnabled = true,

    -- Deprioritize the Roblox clones with renice/ionice to cut RAM/CPU contention when
    -- several floating windows run at once. Applied to every clone after launch/recovery
    -- (the process gets a new pid on each relaunch, so tuning is re-applied each time).
    optimizer = {
        enabled = true,
        renice = 19,   -- CPU scheduling priority (higher = lower). 19 = lowest.
        ionice = 3,    -- I/O class: 0=none,1=realtime,2=best-effort,3=idle.
    },

    -- Folder tujuan AutoExecute (Script Manager). Scripts dikelola LANGSUNG di sini
    -- sebagai <name>.lua (Add/Edit/Delete). Path ini shared untuk semua instance.
    -- Delta mod: /sdcard/Delta/Autoexecute (internal storage, tidak perlu root).
    appAutoExecutePath = "/sdcard/Delta/Autoexecute",

    -- Launch All waits for fresh, stable session heartbeats before advancing.
    -- launchJoinTimeout: deadline becomes Needs Check; never falls back to opening others.
    -- launchWaitTimeout/checkTimeout are legacy diagnostic settings, not launch deadlines.
    -- launchSettleDelay is used only when heartbeat is explicitly disabled.
    -- One loading slot, account/session heartbeats (Menu 12).
    -- Existing user configs get these defaults at runtime; updates do not overwrite them.
    launchSafety = {
        stableHeartbeats = 3,
        stableSeconds = 20,
        retryCooldown = 120,
        maxAttempts = 3,
    },
    launchWaitInterval = 3,
    launchWaitTimeout = 60,
    launchJoinTimeout = 240,
    launchSettleDelay = 20,
    -- launchEmptyDelay: short wait (s) after a clone with no account, so its window
    -- can appear before the next clone starts.
    launchEmptyDelay = 5,
    -- A clone without an account is left alone on its login screen, but if it CLOSED
    -- (force close: process gone or no window left) it is opened again, gently (no
    -- force-stop) and at most once per noLoginCooldown seconds.
    relaunchNoLogin = true,
    -- Status reports to a Discord webhook (one message kept up to date + event
    -- messages). Empty url = off. Set it in Main Menu 8) Discord Webhook.
    webhook = {
        url = "",
        interval = 300,
        screenshot = true,
        events = true,      -- separate message when Delta asks for a key
        hideNames = true,
        deviceName = "",    -- Label Device Name in report title/body; "" = device model
    },
    -- Delta's key entry ("license" inside the Delta folder). "" = find automatically.
    deltaLicensePath = "",
    -- Delta's Scripts folder (Menu 4 / bot store scripts here; Autoexecute only gets a
    -- copy from it). "" = Scripts / scripts next to appAutoExecutePath.
    scriptsPath = "",
    -- Game presets (Main Menu 11 / bot). Clones follow `defaultPreset` unless they have
    -- their own `preset = "B"` ("khusus"), or `preset = "-"` (use their own
    -- privateServer). Example:
    --   presets = { A = { name = "Steal an Egg", link = "https://www.roblox.com/games/..." } },
    --   defaultPreset = "A",
    presets = {},
    defaultPreset = "",
    -- Remote control through the Discord bot (docs/discord_bot_prd.md). url or secret
    -- empty = off. Commands run while the monitor / Launch All is running.
    remote = {
        url = "",       -- e.g. https://my-bot.onrender.com ("" = take it from remote_url.txt)
        -- urlManual = true is set when the URL is typed in Menu 8: remote_url.txt never replaces it
        secret = "",    -- same as the bot's DEVICE_SECRET
        interval = 30,  -- seconds between syncs
    },
    noLoginCooldown = 120,
    -- Arrange the clones' floating windows in a grid (App Cloner floating window).
    -- The window bounds are written into the clone's prefs while it is stopped,
    -- right before launch. On by default. columns = 0 picks automatically.
    -- A clone can override its spot with window = { left=, top=, right=, bottom= }.
    windowLayout = {
        enabled = true,
        columns = 0,
        gap = 0,
        offsetTop = 0,       -- extra top margin; auto grid still reserves the Android status bar
        topInset = 0,        -- 0 = detect once per session; >0 pins the status bar height in pixels
        screenWidth = 0,     -- 0 = detect once per session; set with screenHeight to pin the display size
        screenHeight = 0,
        overlap = 80,
    },
    -- In-game heartbeat: rejoin puts scripts/rejoin_heartbeat.lua into the Delta
    -- autoexecute folder. Inside the game it reports in-game / kicked, fps, memory;
    -- a kick is rejoined at once. saver = lower CPU/GPU/RAM (3D rendering off, FPS cap,
    -- low graphics, mute). Without a ready heartbeat the queue waits; RSS is diagnostic only.
    heartbeat = {
        enabled = true,
        interval = 10,
        staleAfter = 90,
        workspacePath = "",
        saver = {
            enabled = false,
            disable3d = true,
            fpsCap = 15,
            lowGraphics = true,
            mute = true,
        },
    },
    -- Login check: the .ROBLOSECURITY token on disk is verified against Roblox with curl
    -- (users.roblox.com/v1/users/authenticated). A rejected token (HTTP 401) counts as
    -- logged out, so the clone shows NoLogin and is never force-stopped/relaunched.
    -- loginVerifyInterval: seconds between checks per clone (a changed token is
    -- re-checked right away). Needs `pkg install curl`.
    loginVerifyRemote = true,
    loginVerifyInterval = 600,
    -- Run shell commands as root (su -c). Required on a rooted device Android 11+ so that
    -- ps/pidof/pgrep can actually see the app processes the Monitor depends on; Termux run
    -- as a normal user cannot see other apps' processes. Set false on a non-root device.
    useRoot = true,
    -- Start empty; the setup wizard or Instance Manager adds installed packages.
    instances = {}
}
]]

__ya_sources["core.autoexecute_cli"] = [[
local AutoExecute = require("managers.autoexecute")

-- Main Menu 4: Script Manager. Scripts are stored in Delta's Scripts folder; the
-- Autoexecute folder only gets a COPY of a script from Scripts (never written to
-- directly). The Delta folder is shared by every clone on this device.

local CLI = {}

local function prompt(msg)
    io.write(msg)
    io.flush()
    return io.read()
end

local function trim(s) return ((s or ""):gsub("^%s+", ""):gsub("%s+$", "")) end

-- Read multi-line script input from the terminal until a line that is exactly `END`
-- (the very last line). The `END` line is NOT stored / not executed.
local function readScript()
    local lines = {}
    while true do
        io.write("> ")
        io.flush()
        local line = io.read()
        if line == nil then return nil end                 -- EOF / Ctrl+D
        if line:match("^%s*END%s*$") then break end        -- terminal marker
        table.insert(lines, line)
    end
    return table.concat(lines, "\n") .. "\n"
end

local function show()
    print("\nScript Manager (berlaku untuk SEMUA clone di device ini)")
    print("Folder Scripts: " .. tostring(AutoExecute.scriptsDir() or "?"))
    local list, err = AutoExecute.scriptsList()
    if not list then
        print("  (tidak bisa dibaca: " .. tostring(err) .. ")")
    elseif #list == 0 then
        print("  (kosong — pilih 1 / 2 untuk menambah)")
    else
        for i, s in ipairs(list) do
            print(string.format("  %2d) %-32s %7d bytes %s", i, s.name, s.size, s.auto and "[AUTO]" or ""))
        end
    end
    local auto = AutoExecute.autoList() or {}
    local names = {}
    for _, s in ipairs(auto) do
        names[#names + 1] = s.name .. (s.managed and " (rejoin)" or (s.fromScripts and "" or " (tidak ada di Scripts)"))
    end
    print("Autoexecute: " .. (#names > 0 and table.concat(names, ", ") or "(kosong)"))
end

-- Pick a script of the Scripts folder by number or name.
local function pick(label)
    local list = AutoExecute.scriptsList() or {}
    local v = trim(prompt(label))
    if v == "" then return nil end
    local n = tonumber(v)
    if n and list[n] then return list[n].name end
    return v
end

local function offerRejoin()
    local v = trim(prompt("Rejoin semua clone biar langsung berlaku? (y/n) [n] "))
    if v:lower() == "y" then
        require("managers.monitor").requestRejoinFile({ "all" })
        print("Diminta. Engine yang jalan akan rejoin satu per satu.")
    else
        print("Berlaku saat clone masuk game berikutnya.")
    end
end

local function saveFlow(name, content)
    local n, replaced, autoUpdated = AutoExecute.scriptSave(name, content)
    if not n then print("Gagal: " .. tostring(replaced)); return end
    print((replaced and "Diganti: " or "Disimpan: ") .. n
        .. (autoUpdated and " (copy di Autoexecute ikut diperbarui)" or ""))
end

function CLI.run()
    while true do
        show()
        print("")
        print("  1) Tambah / ganti script (ketik, akhiri baris END)")
        print("  2) Tambah dari loadstring URL")
        print("  3) Hapus script dari Scripts")
        print("  4) Masukkan ke Autoexecute (copy dari Scripts)")
        print("  5) Keluarkan dari Autoexecute")
        print("  6) Edit script")
        print("  0) Kembali")
        local choice = prompt("Pilih: ")
        if choice == nil then
            print("\n(Input berakhir — kembali ke menu utama)")
            break
        end
        choice = trim(choice)
        if choice == "0" or choice == "" then
            break
        elseif choice == "1" then
            local name = trim(prompt("Nama script (mis. egg_farm): "))
            print("Tulis / paste kode script. Akhiri dengan baris `END` di paling bawah, lalu Enter:")
            local content = readScript()
            if content == nil then print("Input dibatalkan (EOF).") else saveFlow(name, content) end
        elseif choice == "2" then
            local name = trim(prompt("Nama script: "))
            local loader, err = AutoExecute.loaderFor(trim(prompt("URL script (https://...): ")))
            if not loader then print(err) else saveFlow(name, loader .. "\n") end
        elseif choice == "3" then
            local name = pick("Nomor / nama script yang dihapus: ")
            if name and trim(prompt("Hapus " .. name .. "? ketik 'yes': ")):lower() == "yes" then
                local n, stillAuto = AutoExecute.scriptRemove(name)
                if not n then print("Gagal: " .. tostring(stillAuto))
                else
                    print("Dihapus dari Scripts: " .. n)
                    if stillAuto then print("Catatan: copy-nya masih ada di Autoexecute (keluarkan lewat pilihan 5).") end
                end
            end
        elseif choice == "4" then
            local name = pick("Nomor / nama script untuk Autoexecute: ")
            if name then
                local n, err = AutoExecute.autoAdd(name)
                if n then print("Masuk Autoexecute: " .. n); offerRejoin() else print("Gagal: " .. tostring(err)) end
            end
        elseif choice == "5" then
            local name = trim(prompt("Nama script yang dikeluarkan dari Autoexecute: "))
            if name ~= "" then
                local n, err = AutoExecute.autoRemove(name)
                if n then print("Keluar dari Autoexecute: " .. n); offerRejoin() else print("Gagal: " .. tostring(err)) end
            end
        elseif choice == "6" then
            local name = pick("Nomor / nama script yang diedit: ")
            if name then
                local _, n = AutoExecute.scriptRead(name)
                if not n then print("Script tidak ada di Scripts.") else
                    print("Edit " .. n .. ". Tulis kode baru, akhiri dengan baris `END`:")
                    local content = readScript()
                    if content == nil then print("Input dibatalkan (EOF).") else saveFlow(n, content) end
                end
            end
        else
            print("Pilihan tidak dikenal.")
        end
    end
end

return CLI
]]

__ya_sources["core.boot_cli"] = [[
local Boot = require("managers.boot")

-- Submenu "Auto-boot (Termux:Boot)": install / uninstall the boot script and
-- inspect the boot log, so a single-file loader can enable auto-start on its own.

local CLI = {}

local function prompt(msg)
    io.write(msg)
    io.flush()
    return io.read()
end

local function wait()
    print("\n[Selesai] Tekan Enter untuk kembali ke menu utama")
    io.read()
end

function CLI.run()
    while true do
        local st = Boot.status()
        print("\nAuto-boot (Termux:Boot)")
        print("  script boot : " .. st.path .. (st.installed and "   [TERPASANG]" or "   [belum]"))
        print("  aplikasi    : " .. (st.app
            and "Termux:Boot terpasang"
            or "Termux:Boot BELUM terpasang (pasang dari sumber yang sama dengan Termux)"))
        print("  log boot    : " .. st.log .. (st.logExists and "" or "   [belum ada]"))

        print("\n  1) Install / update script boot")
        print("  2) Uninstall script boot")
        print("  3) Lihat 10 baris terakhir boot.log")
        print("  4) Kembali")

        local choice = (prompt("Choose: ") or ""):match("^%s*(.-)%s*$")

        if choice == "1" then
            local ok, info = Boot.install()
            if ok then
                print("\nScript boot terpasang: " .. tostring(info))
                print("Langkah lanjut: BUKA aplikasi Termux:Boot sekali, lalu reboot HP.")
                print("Saat boot engine jalan tersembunyi (headless launch + monitor).")
                print("Log: " .. tostring(Boot.logPath()))
            else
                print("\nGAGAL: " .. tostring(info))
            end
            wait()
            break
        elseif choice == "2" then
            local ok, info = Boot.uninstall()
            if ok then
                print("\nScript boot dihapus: " .. tostring(info))
                print("Auto-start di boot berikutnya tidak dijalankan lagi.")
            else
                print("\n" .. tostring(info))
            end
            wait()
            break
        elseif choice == "3" then
            local out, err = Boot.tailLog(10)
            if out then
                print("\n--- boot.log (10 baris terakhir) ---")
                io.write(out)
                if not out:match("\n$") then io.write("\n") end
            else
                print("\nBelum ada log: " .. tostring(err))
                print("Normal kalau HP belum pernah di-boot sejak script dipasang.")
            end
            wait()
            break
        elseif choice == "4" then
            break
        else
            print("Unknown choice")
        end
    end
end

return CLI]]

__ya_sources["core.config"] = [[
local Paths = require("core.paths")
local File = require("utils.file")
local Logger = require("core.logger")

local Config = {}
local configPath = Paths.config()
local templatePath = Paths.template()
local data = nil

local function loadFromFile(path)
    if not File.exists(path) then
        if path == templatePath then
            local ok, template = pcall(require, "config.template")
            if ok and type(template) == "table" then return template end
        end
        return nil
    end
    local ok, conf = pcall(dofile, path)
    if ok and type(conf) == "table" then
        return conf
    end
    return nil
end

-- Initialize config from config/config.lua, fallback to template
data = loadFromFile(configPath) or loadFromFile(templatePath) or {}

function Config.get()
    return data
end

-- Re-read config/config.lua (e.g. after another process changed it). Keeps the same
-- table object so code holding Config.get() sees the new values.
function Config.reload()
    local fresh = loadFromFile(configPath)
    if not fresh then return false end
    for k in pairs(data) do data[k] = nil end
    for k, v in pairs(fresh) do data[k] = v end
    return true
end

-- Serialize simple Lua table to a Lua file that returns the table
local function serializeTable(t, indent)
    indent = indent or ""
    local parts = {"{\n"}
    local nextIndent = indent .. "  "

    -- Traverse keys in a stable order: numeric keys first (ascending), then the rest.
    local keys = {}
    for k in pairs(t) do table.insert(keys, k) end
    table.sort(keys, function(a, b)
        local ta, tb = type(a), type(b)
        if ta == "number" and tb == "number" then return a < b end
        if ta == "number" then return true end
        if tb == "number" then return false end
        return tostring(a) < tostring(b)
    end)

    for _, k in ipairs(keys) do
        local v = t[k]
        -- Numbers (including array indices) serialize as plain integer keys so that
        -- `ipairs`/array reads still work after reload (fixes club-loading instances).
        local key
        if type(k) == "number" then
            key = "[" .. tostring(k) .. "] = "
        elseif type(k) == "string" and k:match("^[%a_][%w_]*$") then
            key = k .. " = "
        else
            key = "[" .. string.format('%q', tostring(k)) .. "] = "
        end

        local val
        local tp = type(v)
        if tp == "string" then
            val = string.format('%q', v)
        elseif tp == "number" or tp == "boolean" then
            val = tostring(v)
        elseif tp == "table" then
            val = serializeTable(v, nextIndent)
        else
            val = "nil"
        end

        table.insert(parts, nextIndent .. key .. val .. ",\n")
    end
    table.insert(parts, indent .. "}")
    return table.concat(parts)
end

function Config.save(conf)
    conf = conf or data
    local contents = "return " .. serializeTable(conf) .. "\n"
    local ok, err = File.write(configPath, contents)
    if not ok then
        Logger.error("Config.save: failed to write config: " .. tostring(err))
        return false, err
    end
    data = conf
    Logger.info("Config: saved configuration to " .. configPath)
    return true
end

function Config.resetToTemplate()
    local tpl = loadFromFile(templatePath)
    if not tpl then
        return false, "no_template"
    end
    return Config.save(tpl)
end

return Config]]

__ya_sources["core.delta_key_cli"] = [[
local DeltaKey = require("managers.delta_key")

local CLI = {}

local function prompt(msg)
    io.write(msg)
    io.flush()
    return io.read()
end

local function readKey()
    io.write("Masukkan key Delta (contoh FREE_XXXXX; input disembunyikan): ")
    io.flush()
    os.execute("stty -echo 2>/dev/null")
    local readOk, key = pcall(io.read, "*l")
    os.execute("stty sane 2>/dev/null")
    os.execute("stty echo icanon opost onlcr 2>/dev/null")
    io.write("\r\n")
    io.flush()
    if not readOk then return "" end
    return (key or ""):gsub("^%s+", ""):gsub("%s+$", "")
end

function CLI.run()
    print("\nInput Key Delta")
    print("Masukkan key yang kamu dapatkan dari Delta. Key tidak disimpan di config atau log.")
    local key = readKey()
    if key == "" then
        print("Dibatalkan.")
    else
        local called, ok, message = pcall(DeltaKey.input, key)
        key = nil
        print((called and ok and "Berhasil: " or "Gagal: ") .. tostring(called and message or "input key Delta gagal (error internal)"))
    end
    prompt("Tekan Enter untuk kembali ke menu utama")
end

return CLI
]]

__ya_sources["core.display_cli"] = [[
local Config = require("core.config")

-- Main Menu 9: floating window grid, Delta heartbeat and saver mode.
-- Pick one item at a time; every change is saved right away. Displayed values follow
-- the same defaults as the modules that use them (window_layout / heartbeat).

local CLI = {}

local function prompt(msg)
    io.write(msg)
    io.flush()
    return io.read()
end

local function onoff(v) return v and "nyala" or "mati" end

local function save(conf)
    local ok, err = Config.save(conf)
    print(ok and "Tersimpan." or ("Gagal menyimpan: " .. tostring(err)))
end

local function tables(conf)
    conf.windowLayout = type(conf.windowLayout) == "table" and conf.windowLayout or {}
    conf.heartbeat = type(conf.heartbeat) == "table" and conf.heartbeat or {}
    conf.heartbeat.saver = type(conf.heartbeat.saver) == "table" and conf.heartbeat.saver or {}
    return conf.windowLayout, conf.heartbeat, conf.heartbeat.saver
end

-- Ask for a whole number >= min; empty input keeps the old value.
local function askInt(label, current, min)
    local v = prompt(label .. ": [" .. tostring(current) .. "] ")
    if not v or v:match("^%s*$") then return nil end
    local n = tonumber(v)
    if n and n >= min then return math.floor(n) end
    print("Angka tidak valid.")
    return nil
end

function CLI.run()
    local conf = Config.get() or {}
    while true do
        local wl, hb, sv = tables(conf)
        local cols = tonumber(wl.columns) or 0
        print("\nJendela & Mode Hemat:")
        print("  1) Auto atur jendela (grid) [" .. onoff(wl.enabled == true) .. "]")
        print("  2) Kolom grid               [" .. (cols > 0 and tostring(cols) or "0 = otomatis") .. "]")
        print("  3) Jarak antar jendela      [" .. tostring(wl.gap or 0) .. " px]")
        print("  4) Heartbeat Delta          [" .. onoff(hb.enabled ~= false) .. "]")
        print("  5) Mode hemat               [" .. onoff(sv.enabled == true) .. "]")
        print("  6) Batas FPS (mode hemat)   [" .. tostring(sv.fpsCap or 15) .. "]")
        print("  7) Render 3D mati           [" .. (sv.disable3d ~= false and "ya" or "tidak") .. "]")
        print("  8) Pasang ulang script heartbeat sekarang")
        print("  9) Baris atas numpuk ke bawah [" .. tostring(wl.overlap or 80) .. " px, 0 = grid biasa]")
        print("  0) Kembali")
        local choice = (prompt("Pilih: ") or "0"):match("^%s*(.-)%s*$")

        if choice == "0" or choice == "" then
            return
        elseif choice == "1" then
            wl.enabled = not (wl.enabled == true)
            print("Auto atur jendela: " .. onoff(wl.enabled))
            save(conf)
        elseif choice == "2" then
            local n = askInt("Kolom grid (0 = otomatis)", cols, 0)
            if n then wl.columns = n; save(conf) end
        elseif choice == "3" then
            local n = askInt("Jarak antar jendela (pixel)", wl.gap or 0, 0)
            if n then wl.gap = n; save(conf) end
        elseif choice == "4" then
            hb.enabled = not (hb.enabled ~= false)
            print("Heartbeat Delta: " .. onoff(hb.enabled))
            if not hb.enabled and sv.enabled then
                print("(Mode hemat ikut tidak aktif tanpa heartbeat.)")
            end
            save(conf)
        elseif choice == "5" then
            sv.enabled = not (sv.enabled == true)
            print("Mode hemat: " .. onoff(sv.enabled))
            if sv.enabled and hb.enabled == false then
                print("(Nyalakan juga Heartbeat Delta / pilihan 4, mode hemat jalan lewat script itu.)")
            end
            save(conf)
        elseif choice == "6" then
            local n = askInt("Batas FPS (0 = tanpa batas)", sv.fpsCap or 15, 0)
            if n then sv.fpsCap = n; save(conf) end
        elseif choice == "7" then
            sv.disable3d = not (sv.disable3d ~= false)
            print("Render 3D mati: " .. (sv.disable3d and "ya" or "tidak"))
            save(conf)
        elseif choice == "8" then
            local Heartbeat = require("managers.heartbeat")
            local ok, msg = Heartbeat.install()
            print((ok and "OK: " or "Gagal: ") .. tostring(msg))
        elseif choice == "9" then
            local n = askInt("Tinggi tambahan baris atas (pixel, 0 = grid biasa)", wl.overlap or 80, 0)
            if n then
                wl.overlap = n
                save(conf)
                print("(Berlaku saat clone dibuka ulang.)")
            end
        else
            print("Pilihan tidak dikenal.")
        end
        if choice ~= "8" and (choice == "4" or choice == "5" or choice == "6" or choice == "7") then
            print("(Berlaku setelah script heartbeat dipasang ulang: pilihan 8, atau otomatis saat monitor mulai.)")
        end
    end
end

return CLI
]]

__ya_sources["core.dump_cookies_cli"] = [[
local InstanceManager = require("managers.instance")
local CookieInjector = require("managers.cookie_injector")

local CLI = {}

function CLI.run()
    print("\nDump Cookies (debug) - menampilkan baris cookie clone, value hanya panjangnya\n")
    local list = InstanceManager.getAll()
    if #list == 0 then
        print("(no instances configured)")
        return
    end
    print("Instances:")
    for _, inst in ipairs(list) do
        print(string.format("  id=%s name=%s package=%s", tostring(inst.id), tostring(inst.name or ""), tostring(inst.package or "")))
    end
    io.write("Instance id (atau kosong untuk batal): ")
    io.flush()
    local raw = io.read()
    local id = raw and tonumber((raw:gsub("^%s+", ""):gsub("%s+$", ""))) or nil
    if not id then
        print("Dibatalkan.")
        return
    end
    local inst = InstanceManager.findById(id)
    if not inst then
        print("Instance not found")
        return
    end
    print(string.format("Target: %s (%s)", tostring(inst.name or ""), tostring(inst.package or "")))

    local ok, msg = CookieInjector.dump(inst)
    if ok then
        print("\n----- cookies dump -----")
        print(msg)
        print("----- end dump -----")
    else
        print("[GAGAL] " .. tostring(msg))
    end
end

return CLI]]

__ya_sources["core.inject_cookie_cli"] = [[
local InstanceManager = require("managers.instance")
local CookieInjector = require("managers.cookie_injector")
local Logger = require("core.logger")

local CLI = {}

local function prompt(msg)
    io.write(msg)
    io.flush()
    return io.read()
end

-- Disable terminal echo while reading a long token. Use inherited stdin: some
-- cloud terminals have no usable /dev/tty even though stdin is a TTY.
local function readToken(msg)
    io.write(msg)
    io.flush()
    os.execute("stty -echo 2>/dev/null")
    local readOk, t = pcall(io.read, "*l")
    os.execute("stty sane 2>/dev/null")
    os.execute("stty echo icanon opost onlcr 2>/dev/null")
    io.write("\r\n")
    io.flush()
    if not readOk then return "" end
    t = t or ""
    return t:gsub("^%s+", ""):gsub("%s+$", "")
end

local function listInstances()
    local list = InstanceManager.getAll()
    if #list == 0 then
        print("(no instances configured)")
        return nil
    end
    print("Instances:")
    for _, inst in ipairs(list) do
        print(string.format("  id=%s name=%s package=%s", tostring(inst.id), tostring(inst.name or ""), tostring(inst.package or "")))
    end
    return list
end

local function pickInstance()
    local list = listInstances()
    if not list then return nil end
    local id = prompt("Instance id: ") or ""
    id = tonumber(id)
    local inst = id and InstanceManager.findById(id)
    if not inst then
        print("Instance not found")
        return nil
    end
    print(string.format("Target: %s (%s)", tostring(inst.name or ""), tostring(inst.package or "")))
    return inst
end

-- One-shot flow: after an action prints its result we consume any leftover stdin
-- (a big token paste can desync the Termux keyboard/buffer) then return to the main
-- menu, so the user never sits stuck in this submenu. The screen is cleared first:
-- forcing a full repaint re-syncs the Termux surface after a heavy paste.
local function backToMain()
    io.write("\27[2J\27[H") -- clear screen + cursor home
    io.flush()
    print("[Selesai] Tekan Enter untuk kembali ke menu utama")
    io.read()
end

-- Reset the terminal before returning to the menu. run.sh can also restart the
-- process; direct `lua main.lua` must remain interactive without that wrapper.
local function finish(msg)
    os.execute("stty sane 2>/dev/null")
    os.execute("stty echo icanon opost onlcr 2>/dev/null")
    io.write("\r\27[2J\27[H")
    print(tostring(msg))
    io.flush()
    if os.getenv("REJOIN_WRAPPER") == "1" then os.exit(75) end
end

function CLI.run()
    while true do
        print("\nInject Cookie:\n  1) Inject .ROBLOSECURITY ke instance\n  2) Dump cookies (debug)\n  3) Cek validitas token\n  4) Logout akun clone (cookie dihapus, app ditutup)\n  0) Kembali\n")
        local choice = prompt("Choose an option: ") or ""
        choice = choice:match("^%s*(.-)%s*$")
        if choice == "1" then
            local inst = pickInstance()
            if inst then
                print("")
                print("=============================================================")
                print(" 1 token = 1 clone = 1 akun.")
                print(" Token yang dipakai di >1 clone/device beruntun -> Roblox")
                print(" force-logout SEMUA sesi (termasuk browser sumber) + rotasi.")
                print(" Untuk tiap clone gunakan eksport token yang BEDA.")
                print("=============================================================")
                local token = readToken("Cookie .ROBLOSECURITY: ")
                if token == "" then
                    finish("[GAGAL] Token kosong, dibatalkan.")
                    return
                else
                    local confirm = prompt(string.format("Inject cookie (%d char) ke %s? Force-stop app dulu. type 'y': ", #token, tostring(inst.package or ""))) or ""
                    if confirm:lower() == "y" then
                            local called, ok, msg = pcall(CookieInjector.inject, inst, token)
                            if not called then finish("[GAGAL] Inject error. Cek log dan coba lagi.") end
                            if ok then
                                print("[OK] " .. tostring(msg))
                                -- The app was force-stopped by inject; launch it right away so
                                -- it authenticates against Roblox immediately.
                                local APK = require("managers.apk")
                                local Timer = require("utils.timer")
                                print("Membuka " .. tostring(inst.package or "") .. "...")
                                local lOk, lOut = APK.launch(inst.package)
                                if not lOk then
                                    print("[WARN] Gagal membuka app otomatis: " .. tostring(lOut or "(tanpa output)"))
                                end
                                -- IMPORTANT: DO NOT curl-verify the token while the app is
                                -- running. curl + WebView authenticating the SAME session in
                                -- succession is exactly the "session hijack" pattern Roblox
                                -- detects -> instant revoke (proven at 01:43: 200 at :28,
                                -- app launched at :30, 401 hit during the post-launch curl).
                                -- Here we only READ the DB (rotation check), no network.
                                Timer.sleep(8)
                                print("")
                                print("Periksa rotasi session (baca DB saja, TANPA panggil server —")
                                print("menghindari 2 client pakai token sama serentak yg memicu revoke):")
                                local probeOk, probeText, probeVerdict, probeInfo = pcall(CookieInjector.probeToken, inst, token)
                                if not probeOk then
                                    probeText = "Probe gagal; periksa Cookies DB setelah app ditutup."
                                    probeVerdict = "NEED_MANUAL_CHECK"
                                end
                                print(probeText)
                                print("")
                                print("[VERDICT] " .. tostring(probeVerdict))
                                Logger.info("Probe:\n" .. tostring(probeText))
                                Logger.info("VERDICT: " .. tostring(probeVerdict))
                                local hOk, hints = pcall(CookieInjector.hints, probeOk and probeInfo or nil)
                                if hOk and type(hints) == "table" and #hints > 0 then
                                    print("")
                                    print("Kemungkinan penyebab kalau clone tetep logout:")
                                    for _, h in ipairs(hints) do print(h) end
                                    Logger.info("Hints:\n" .. table.concat(hints, "\n"))
                                end
                                print("")
                                print("JANGAN verifikasi token (7>3) SELAMA app masih terbuka.")
                                finish("Inject + launch selesai.")
                                return
                            else
                                finish("[GAGAL] " .. tostring(msg))
                                return
                            end
                    else
                        finish("Dibatalkan")
                        return
                    end
                end
            else
                finish("[GAGAL] Instances dibutuhkan untuk inject.")
                return
            end
        elseif choice == "2" then
            local inst = pickInstance()
            if inst then
                local ok, msg = CookieInjector.dump(inst)
                if ok then
                    print("\n----- cookies dump -----")
                    print(msg)
                    print("----- end dump -----")
                    Logger.info("DUMP for " .. tostring(inst.package or "?") .. ":\n" .. tostring(msg))
                else
                    print("[GAGAL] " .. tostring(msg))
                end
            end
            backToMain()
            break
        elseif choice == "3" then
            print("TUTUP dulu clone / app-nya sebelum cek (2 client pakai token sama serentak = trigger revoke).")
            local token = readToken("Cookie .ROBLOSECURITY: ")
            if token == "" then
                finish("[GAGAL] Token kosong, dibatalkan.")
                return
            else
                local called, ok, msg = pcall(CookieInjector.verifyRemote, token)
                if not called then finish("[GAGAL] Verifikasi error. Cek koneksi lalu coba lagi.") end
                finish(ok and ("[VALID] " .. tostring(msg)) or ("[GAGAL] " .. tostring(msg)))
                return
            end
        elseif choice == "4" then
            local inst = pickInstance()
            if inst then
                local confirm = prompt("Logout akun di " .. tostring(inst.package or "") .. "? Perlu login / inject lagi nanti. ketik 'y': ") or ""
                if confirm:lower():match("^%s*y") then
                    local called, ok, msg = pcall(CookieInjector.logout, inst)
                    print(called and ((ok and "[OK] " or "[GAGAL] ") .. tostring(msg)) or "[GAGAL] Logout error, cek log.")
                    if called and ok then
                        print("Engine yang jalan nganggep clone ini belum login dalam ±30 detik (ga di-rejoin).")
                    end
                else
                    print("Dibatalkan")
                end
            end
            backToMain()
            break
        elseif choice == "0" or choice == "" then
            print("Exiting Inject Cookie")
            break
        else
            print("Unknown choice")
        end
    end
end

return CLI
]]

__ya_sources["core.instances_cli"] = [[
local Logger = require("core.logger")
local InstanceManager = require("managers.instance")
local Config = require("core.config")
local Shell = require("utils.shell")
local APK = require("managers.apk")

local CLI = {}

local function prompt(msg)
    io.write(msg)
    io.flush()
    return io.read()
end

local SOURCE_LABEL = { khusus = "khusus", default = "ikut default", link = "link sendiri", none = "belum ada link" }

local function gameLabel(inst)
    local key, source = InstanceManager.presetOf(inst)
    local okC, Config = pcall(require, "core.config")
    local ps = okC and type(Config.get().presets) == "table" and Config.get().presets or {}
    local game = key and ("[" .. key .. "] " .. tostring(ps[key] and ps[key].name or "")) or (source == "link" and tostring(inst.privateServer) or "-")
    return game .. " (" .. (SOURCE_LABEL[source] or source) .. ")"
end

-- Ask how a clone picks its game. Returns the fields to set, or nil to keep.
-- New clone: Enter = follow the default preset. Edit: Enter = keep, "d" = follow the
-- default. A preset key = that preset; "-" = own link.
local function askGame(inst)
    local okC, Config = pcall(require, "core.config")
    local conf = okC and Config.get() or {}
    local ps = type(conf.presets) == "table" and conf.presets or {}
    local keys = {}
    for k in pairs(ps) do keys[#keys + 1] = k end
    table.sort(keys)
    local def = conf.defaultPreset
    if #keys == 0 then
        local server = prompt("Link game / private server (kosong = nanti; atur preset di Main Menu 11): ") or ""
        server = server:match("^%s*(.-)%s*$")
        if server == "" then return nil end
        return { privateServer = server, preset = "-" }
    end
    print("Preset: " .. table.concat(keys, ", ") .. ((def and def ~= "") and ("  (default: " .. def .. ")") or ""))
    local v
    if inst then
        v = prompt("Game: Enter = tetap, 'd' = ikut default, kode preset = khusus, '-' = link sendiri: ") or ""
    else
        v = prompt("Game: Enter = ikut default, kode preset = khusus, '-' = link sendiri: ") or ""
    end
    v = v:match("^%s*(.-)%s*$")
    if v == "" then return inst and nil or {} end
    if v == "d" or v == "D" then return { preset = "" } end
    if v == "-" then
        local server = prompt("Link sendiri [" .. tostring(inst and inst.privateServer or "") .. "]: ") or ""
        server = server:match("^%s*(.-)%s*$")
        if server == "" and not (inst and inst.privateServer) then print("Link kosong, tetap ikut default."); return {} end
        return { preset = "-", privateServer = server ~= "" and server or nil }
    end
    if ps[v] then return { preset = v } end
    print("Preset '" .. v .. "' tidak ada; ikut default.")
    return {}
end

local function printInstances()
    local list = InstanceManager.getAll()
    if #list == 0 then
        print("(no instances configured)")
        return
    end
    print("Instances:")
    for _, inst in ipairs(list) do
        print(string.format("  id=%s name=%s package=%s game=%s", tostring(inst.id), tostring(inst.name or ""),
            tostring(inst.package or ""), gameLabel(inst)))
    end
end

local function detectRobloxPackages()
    local conf = Config.get() or {}
    local prefix = type(conf.clonePackagePrefix) == "string" and conf.clonePackagePrefix:lower() or ""
    local ok, out = Shell.exec("pm list packages")
    if not ok or not out or out == "(dry-run)" then
        return nil, "Tidak bisa membaca daftar package Android."
    end

    local found, seen = {}, {}
    for line in out:gmatch("[^\r\n]+") do
        local pkg = line:match("package:(%S+)")
        if pkg and not seen[pkg] then
            local lower = pkg:lower()
            local match = lower:find("roblox", 1, true) ~= nil
                or (prefix ~= "" and lower:find(prefix, 1, true) == 1)
            if not match then
                local component = APK.resolveLaunchComponent(pkg)
                match = component and component:lower():find("roblox", 1, true) ~= nil
            end
            if match then
                seen[pkg] = true
                found[#found + 1] = pkg
            end
        end
    end
    table.sort(found)
    return found
end

local function addPackage(pkg)
    local name = prompt("Instance name (Enter = " .. pkg .. "): ") or ""
    name = name:match("^%s*(.-)%s*$")
    if name == "" then name = pkg end
    local inst = { name = name, package = pkg }
    for k, v in pairs(askGame(nil) or {}) do inst[k] = v end
    if inst.preset == "" then inst.preset = nil end
    local ok, res = InstanceManager.add(inst)
    if ok then print("Added instance id=" .. tostring(res.id)) else print("Failed to add: " .. tostring(res)) end
end

local function addInstance()
    print("\nAdd Instance:\n  1) Auto Detect Roblox\n  2) Manual Input\n  0) Cancel")
    local mode = (prompt("Choose a mode: ") or ""):match("^%s*(.-)%s*$")
    if mode == "0" or mode == "" then return end
    if mode == "2" then
        local pkg = (prompt("Package name (e.g. com.roblox.client): ") or ""):match("^%s*(.-)%s*$")
        if pkg == "" then print("Package is required.") else addPackage(pkg) end
        return
    end
    if mode ~= "1" then print("Unknown mode."); return end

    local packages, err = detectRobloxPackages()
    if not packages then print(err); return end
    if #packages == 0 then print("No Roblox packages detected. Try Manual Input."); return end
    print("Detected Roblox packages:")
    for i, pkg in ipairs(packages) do print(string.format("  %d) %s", i, pkg)) end
    local selection = (prompt("Select package indices (e.g. 1,2) or 'all': ") or ""):lower()
    selection = selection:match("^%s*(.-)%s*$")
    local indices, seen = {}, {}
    if selection == "all" or selection == "a" then
        for i = 1, #packages do indices[#indices + 1] = i end
    else
        for value in selection:gmatch("%d+") do
            local i = tonumber(value)
            if i and packages[i] and not seen[i] then
                indices[#indices + 1] = i
                seen[i] = true
            end
        end
    end
    if #indices == 0 then print("No valid package selected."); return end
    for _, i in ipairs(indices) do addPackage(packages[i]) end
end

function CLI.run()
    while true do
        print("\nInstances Manager:\n  1) List instances\n  2) Add instance\n  3) Edit instance\n  4) Delete instance\n  5) Exit\n")
        local choice = prompt("Choose an option: ") or ""
        choice = choice:match("^%s*(.-)%s*$")
        if choice == "1" then
            printInstances()
        elseif choice == "2" then
            addInstance()
        elseif choice == "3" then
            local id = prompt("Instance id to edit: ") or ""
            id = tonumber(id)
            if not id then print("Invalid id") else
                local inst = InstanceManager.findById(id)
                if not inst then print("Instance not found") else
                    print("Leave blank to keep current value")
                    local name = prompt("Name [" .. tostring(inst.name or "") .. "]: ")
                    local pkg = prompt("Package [" .. tostring(inst.package or "") .. "]: ")
                    print("Game sekarang: " .. gameLabel(inst))
                    local game = askGame(inst)
                    local updates = {}
                    if name and name ~= "" then updates.name = name end
                    if pkg and pkg ~= "" then updates.package = pkg end
                    if game then
                        for k, v in pairs(game) do updates[k] = v end
                    end
                    -- An empty preset means follow default. Keep the update explicit
                    -- so changing only this field still reaches persist().
                    if next(updates) == nil then print("No changes") else
                        local ok, res = InstanceManager.update(id, updates)
                        if ok then print("Updated instance id=" .. tostring(res.id)) else print("Failed to update: " .. tostring(res)) end
                    end
                end
            end
        elseif choice == "4" then
            local id = prompt("Instance id to delete: ") or ""
            id = tonumber(id)
            if not id then print("Invalid id") else
                local confirm = prompt("Are you sure? type 'yes' to confirm: ") or ""
                if confirm:lower() == "yes" then
                    local ok, err = InstanceManager.remove(id)
                    if ok then print("Deleted") else print("Failed to delete: " .. tostring(err)) end
                else
                    print("Aborted")
                end
            end
        elseif choice == "5" then
            print("Exiting Instances Manager")
            break
        else
            print("Unknown choice")
        end
    end
end

return CLI
]]

__ya_sources["core.launch_cli"] = [=[
local Config = require("core.config")
local Queue = require("managers.launch_queue")
local CLI = {}
local fields = {
    { "stableHeartbeats", "Jumlah heartbeat baru sebelum lanjut", 2, 10 },
    { "stableSeconds", "Waktu stabil minimum (detik)", 5, 300 },
    { "retryCooldown", "Jeda retry (detik)", 30, 3600 },
    { "maxAttempts", "Batas percobaan per clone", 1, 10 },
}
function CLI.run()
    local conf = Config.get()
    conf.launchSafety = type(conf.launchSafety) == "table" and conf.launchSafety or {}
    local safety = conf.launchSafety
    while true do
        print("\nAntrean & Heartbeat:")
        for i, f in ipairs(fields) do
            local value = safety[f[1]]
            if value == nil then value = Queue.DEFAULTS[f[1]] end
            print(string.format("  %d) %s [%s]", i, f[2], tostring(value)))
        end
        print("  0) Kembali")
        print("Timeout menahan antrean (Perlu dicek). Restart clone dari bot/menu untuk coba lagi.")
        print("Mode hemat/FPS: Menu 9. RAM/RSS hanya informasi, tidak membatasi antrean.")
        io.write("Pilih: ")
        io.flush()
        local selected = tonumber(io.read() or "0")
        if selected == 0 then return end
        local f = fields[selected]
        if f then
            if f[3] == "bool" then
                safety[f[1]] = safety[f[1]] == false
            else
                io.write("Nilai baru: ")
                io.flush()
                local value = tonumber(io.read() or "")
                if value and value % 1 == 0 and value >= f[3] and value <= f[4] then safety[f[1]] = value
                else print(string.format("Isi bilangan bulat %d–%d.", f[3], f[4])) end
            end
            local ok, err = Config.save(conf)
            print(ok and "Tersimpan; engine memakai saat siklus berikutnya." or ("Gagal: " .. tostring(err)))
        end
    end
end
return CLI
]=]

__ya_sources["core.logger"] = [[
local Logger = {}

Logger.levels = {
    INFO = "INFO",
    WARN = "WARN",
    ERROR = "ERROR",
    DEBUG = "DEBUG"
}

local function getTime()
    return os.date("%H:%M:%S")
end

local FileUtil = require("utils.file")
local Paths = require("core.paths")

local defaultLogPath = Paths.data("rejoin.log")
local logFilePath = defaultLogPath

-- Try to read log path from config file without requiring core.config to avoid circular dependency.
-- This reads config/config.lua if present and extracts logPath field.
local function loadLogPathFromConfig()
    local confPath = Paths.config()
    if FileUtil.exists(confPath) then
        local ok, conf = pcall(dofile, confPath)
        if ok and type(conf) == "table" and conf.logPath then
            return Paths.resolve(tostring(conf.logPath))
        end
    end
    return nil
end

-- Minimum level that gets printed to the console. DEBUG is hidden unless the config
-- sets `logLevel = "DEBUG"` (so the monitor doesn't flood with `su -c ...` / process
-- probe lines every cycle). Read directly from the config file to avoid a circular
-- dependency on core.config.
local function loadLogLevelFromConfig()
    local confPath = Paths.config()
    if FileUtil.exists(confPath) then
        local ok, conf = pcall(dofile, confPath)
        if ok and type(conf) == "table" and conf.logLevel then
            return tostring(conf.logLevel):upper()
        end
    end
    return nil
end

local logLevel = loadLogLevelFromConfig() or "INFO"

-- When false, log lines are written to the file only (not the console). Used while a
-- full-screen monitor dashboard is being drawn, so stray log lines don't push the
-- dashboard around. Defaults to true (normal behavior outside monitoring).
local consoleVisible = true

-- Longest log line echoed to the console. A single huge line (e.g. a shell command
-- embedding a pasted token when logLevel=DEBUG) can stall Termux's rendering and
-- swallow subsequent keystrokes. The log file always keeps the full line.
local CONSOLE_MAX = 200

local levelsOrder = {
    DEBUG = 1,
    INFO = 2,
    WARN = 3,
    ERROR = 4,
}

local function ensureLogDir()
    local dir = logFilePath:match("^(.*)[/\\]")
    if dir and dir ~= "" then
        pcall(function()
            -- try to use lfs or mkdir -p
            local lfs_ok, lfs = pcall(require, "lfs")
            if lfs_ok and lfs and lfs.mkdir then
                local cur = ""
                for part in dir:gmatch("[^/\\]+") do
                    cur = (cur == "") and part or (cur .. "/" .. part)
                    if lfs.attributes(cur) == nil then
                        pcall(lfs.mkdir, cur)
                    end
                end
            else
                os.execute("mkdir -p '" .. dir .. "'")
            end
        end)
    end
end

local function appendLogToFile(line)
    ensureLogDir()
    local f, err = io.open(logFilePath, "a")
    if not f then return false, err end
    f:write(line .. "\n")
    f:close()
    return true
end

-- initialize logFilePath from config if available
local fromConfig = loadLogPathFromConfig()
if fromConfig then logFilePath = fromConfig end

local function consoleSafe(line)
    if #line <= CONSOLE_MAX then return line end
    return line:sub(1, CONSOLE_MAX) .. " ..."
end

local function log(level, message)
    local levelOrder = levelsOrder[level] or levelsOrder.INFO
    local minOrder = levelsOrder[logLevel] or levelsOrder.INFO
    -- Hide messages below the configured console level (DEBUG hidden unless requested).
    if levelOrder < minOrder then
        return
    end
    local line = string.format("[%s] [%s] %s", getTime(), level, tostring(message))
    -- Always write to the file; only echo to the console when it's not hidden behind a
    -- full-screen dashboard (consoleVisible == false while monitoring).
    if consoleVisible then
        print(consoleSafe(line))
    end
    pcall(function() appendLogToFile(line) end)
end

function Logger.info(message)
    log(Logger.levels.INFO, message)
end

function Logger.warn(message)
    log(Logger.levels.WARN, message)
end

function Logger.error(message)
    log(Logger.levels.ERROR, message)
end

function Logger.debug(message)
    log(Logger.levels.DEBUG, message)
end

function Logger.getLogPath()
    return logFilePath
end

-- Force the console verbosity from a config value ("DEBUG".."ERROR"), so a save via
-- the Settings menu takes effect without a restart.
function Logger.setLevel(level)
    if level and type(level) == "string" then
        local lvl = level:upper()
        if levelsOrder[lvl] then
            logLevel = lvl
        end
    end
end

function Logger.setLogPath(path)
    if path and type(path) == "string" and path ~= "" then
        logFilePath = Paths.resolve(path)
    end
end

function Logger.setConsoleVisible(visible)
    consoleVisible = visible == true
end

return Logger
]]

__ya_sources["core.logs_cli"] = [[
local Logger = require("core.logger")
local File = require("utils.file")

local CLI = {}

local function prompt(msg)
    io.write(msg)
    io.flush()
    return io.read()
end

function CLI.run()
    local logPath = Logger.getLogPath()
    if not File.exists(logPath) then
        print("Log file not found: " .. tostring(logPath))
        return
    end

    local defaultLines = 200
    local input = prompt("How many lines to show (default " .. tostring(defaultLines) .. "): ") or ""
    local n = tonumber(input) or defaultLines

    local content, err = File.read(logPath)
    if not content then
        print("Failed to read log: " .. tostring(err))
        return
    end

    local lines = {}
    for l in content:gmatch("[^\r\n]+") do table.insert(lines, l) end
    local start = #lines - n + 1
    if start < 1 then start = 1 end
    for i = start, #lines do
        print(lines[i])
    end
end

return CLI
]]

__ya_sources["core.paths"] = [[
local File = require("utils.file")

-- Single source of truth for where the engine keeps its state.
--
-- Everything the tool owns lives under one root so a user can back it up, read
-- it or wipe it from one folder:
--
--   /sdcard/yanamin/config/config.lua      configuration
--   /sdcard/yanamin/data/rejoin.log        engine log
--   /sdcard/yanamin/data/launch.log        per-cycle launch/monitor diagnostics
--   /sdcard/yanamin/data/monitor.pid       monitor lock
--   /sdcard/yanamin/data/username_scan.log username resolution log
--   /sdcard/yanamin/data/boot.log          Termux:Boot log
--   /sdcard/yanamin/data/yanamin_wrapper.sh  embedded terminal supervisor
--
-- Nothing outside this root is ever written (clone app data, AutoExecute
-- scripts and the Termux:Boot script live elsewhere on purpose).
--
-- Override the root with the YANAMIN_HOME environment variable (debugging).
--
-- IMPORTANT: directories are created with a plain `mkdir -p` (os.execute), NOT
-- through utils.shell — that one runs commands as root via `su -c`, which would
-- leave root-owned files that Termux can no longer write.

local Paths = {}

local DEFAULT_ROOT = "/sdcard/yanamin"
local STORAGE_HINT = "Jalankan:  termux-setup-storage  (beri izin storage), lalu ulangi."

local root = nil
local migrated = false

local function shellQuote(s)
    return "'" .. tostring(s or ""):gsub("'", "'\\''") .. "'"
end

local function mkdirp(path)
    if not path or path == "" then return end
    pcall(function() os.execute("mkdir -p " .. shellQuote(path)) end)
end

-- Can we actually create files here? Used to hard-stop early with a clear
-- message instead of failing later in a dozen places.
local function writable(path)
    local probe = path .. "/.yanamin_write_test"
    local f = io.open(probe, "w")
    if not f then return false end
    f:write("ok")
    f:close()
    os.remove(probe)
    return true
end

local function stripTrailingSlash(p)
    local out = tostring(p or ""):gsub("/+$", "")
    if out == "" then return "/" end
    return out
end

local function hardStop(candidate)
    io.stdout:write("\n[yanamin] Folder data " .. candidate .. " tidak bisa ditulis.\n")
    io.stdout:write("[yanamin] " .. STORAGE_HINT .. "\n\n")
    io.stdout:flush()
    os.exit(1)
end

-- Move anything the engine owned in the old working directory (before the data
-- root existed) into the new root, so upgrading does not look like a wipe.
local function migrateLegacy(cwd)
    if migrated then return false end
    migrated = true

    if not cwd or cwd == "" or cwd == root then return false end
    -- Skip when the two paths are related (cwd is the root, sits inside it, or
    -- contains it) — those config/data folders are not ours to move.
    if cwd:sub(1, #root + 1) == root .. "/" or root:sub(1, #cwd + 1) == cwd .. "/" then
        return false
    end

    local moved = {}
    local function mv(src, dst)
        os.execute("mv -f " .. shellQuote(src) .. " " .. shellQuote(dst) .. " 2>/dev/null")
        if not File.exists(src) then
            table.insert(moved, src .. " -> " .. dst)
        end
    end

    local configPath = root .. "/config/config.lua"
    local templatePath = root .. "/config/template.lua"
    local dataDir = root .. "/data"

    if not File.exists(configPath) then
        local legacyConf = cwd .. "/config/config.lua"
        local legacyTpl = cwd .. "/config/template.lua"
        if File.exists(legacyConf) then mv(legacyConf, configPath) end
        if File.exists(legacyTpl) then mv(legacyTpl, templatePath) end
    end

    local legacyData = cwd .. "/data"
    local names = File.listDir(legacyData)
    if names then
        for _, name in ipairs(names) do
            local dst = dataDir .. "/" .. name
            if not File.exists(dst) then mv(legacyData .. "/" .. name, dst) end
        end
    end

    if #moved > 0 then
        print("[yanamin] Data lama dipindahkan ke " .. root .. ":")
        for _, line in ipairs(moved) do print("           " .. line) end
    end
    return #moved > 0
end

-- Resolved root, created on first use. Hard-stops when it is not writable.
function Paths.base()
    if root then return root end
    local candidate = os.getenv("YANAMIN_HOME")
    if not candidate or candidate == "" then candidate = DEFAULT_ROOT end
    candidate = stripTrailingSlash(candidate)

    mkdirp(candidate .. "/config")
    mkdirp(candidate .. "/data")
    if not writable(candidate) then hardStop(candidate) end

    root = candidate
    migrateLegacy(os.getenv("PWD") or ".")
    return root
end

function Paths.config()
    return Paths.base() .. "/config/config.lua"
end

function Paths.template()
    return Paths.base() .. "/config/template.lua"
end

function Paths.dataDir()
    return Paths.base() .. "/data"
end

function Paths.data(name)
    return Paths.dataDir() .. "/" .. tostring(name)
end

-- Relative paths (the ones stored in config) belong to the data root; absolute
-- paths are respected as-is so users can point logs somewhere else.
function Paths.resolve(path)
    path = tostring(path or "")
    if path == "" then return Paths.data("rejoin.log") end
    if path:match("^/") then return path end
    return Paths.base() .. "/" .. path
end

-- Make sure both subfolders exist (cheap, idempotent).
function Paths.ensure()
    local base = Paths.base()
    mkdirp(base .. "/config")
    mkdirp(base .. "/data")
    return base
end

local announced = false

-- One-line "where does my stuff live" hint, shown once at startup.
function Paths.announce()
    if announced then return end
    announced = true
    local base = Paths.base()
    local custom = (os.getenv("YANAMIN_HOME") or "") ~= ""
    print("[yanamin] Data root: " .. base .. (custom and "  (YANAMIN_HOME)" or ""))
    if not custom and base ~= DEFAULT_ROOT then
        print("[yanamin] Bukan " .. DEFAULT_ROOT .. " — cek YANAMIN_HOME.")
    end
end

return Paths]]

__ya_sources["core.preset_cli"] = [[
local Config = require("core.config")
local InstanceManager = require("managers.instance")

-- Main Menu 11: game presets. A preset is a named game link (e.g. A = Steal an Egg,
-- B = Fisch). Clones follow the DEFAULT preset unless they are given their own preset
-- ("khusus") or told to use their own link. Switching every clone to another game is
-- one change of the default. Every change is saved right away.

local CLI = {}

local function prompt(msg)
    io.write(msg)
    io.flush()
    return io.read()
end

local function trim(s) return ((s or ""):gsub("^%s+", ""):gsub("%s+$", "")) end

local function presets(conf)
    conf.presets = type(conf.presets) == "table" and conf.presets or {}
    return conf.presets
end

local function sortedKeys(t)
    local keys = {}
    for k in pairs(t) do keys[#keys + 1] = tostring(k) end
    table.sort(keys)
    return keys
end

local function validLink(l)
    return (l:match("^https://[%w%.%-]*roblox%.com/") or l:match("^roblox://")) ~= nil
end

local function save(conf)
    conf.instances = InstanceManager.getAll()
    local ok, err = Config.save(conf)
    print(ok and "Tersimpan." or ("Gagal menyimpan: " .. tostring(err)))
    return ok
end

-- Clones (ids) that currently follow the default preset.
local function followersOfDefault()
    local ids = {}
    for _, inst in ipairs(InstanceManager.getAll()) do
        local _, source = InstanceManager.presetOf(inst)
        if source == "default" or ((inst.preset == nil or inst.preset == "") and source ~= "khusus") then
            ids[#ids + 1] = inst.id
        end
    end
    return ids
end

-- Ask whether to rejoin now. The running engine (Menu 1 / 13 / boot) picks the request up
-- through data/rejoin_request.txt; without an engine the new link is used next launch.
local function offerRejoin(ids)
    if #ids == 0 then return end
    local v = trim(prompt(#ids .. " clone kena perubahan. Rejoin sekarang? (y/n) [y] "))
    if v == "" or v:lower() == "y" then
        local Monitor = require("managers.monitor")
        if Monitor.requestRejoinFile(ids) then
            print("Diminta. Engine yang jalan akan rejoin satu per satu; kalau engine tidak jalan, link baru dipakai di Launch All berikutnya.")
        end
    end
end

local SOURCE_LABEL = { khusus = "khusus", default = "ikut default", link = "link sendiri", none = "belum ada link" }

local function show(conf)
    local ps = presets(conf)
    local def = conf.defaultPreset
    print("\nPreset Game:")
    local keys = sortedKeys(ps)
    if #keys == 0 then print("  (belum ada preset)") end
    for _, k in ipairs(keys) do
        local p = ps[k]
        print(string.format("  [%s] %s%s\n      %s", k, tostring(p.name or ""),
            k == def and "  <- DEFAULT" or "", tostring(p.link or "")))
    end
    print("Clone:")
    for _, inst in ipairs(InstanceManager.getAll()) do
        local key, source = InstanceManager.presetOf(inst)
        local game = key and ("[" .. key .. "] " .. tostring(ps[key].name or "")) or (source == "link" and "link sendiri" or "-")
        print(string.format("  %s) %-14s -> %s (%s)", tostring(inst.id), tostring(inst.name or inst.package),
            game, SOURCE_LABEL[source] or source))
    end
end

local function pickPreset(conf, label)
    local key = trim(prompt(label))
    if key == "" then return nil end
    if not presets(conf)[key] then print("Preset '" .. key .. "' tidak ada."); return nil end
    return key
end

function CLI.run()
    local conf = Config.get() or {}
    while true do
        show(conf)
        print("\n  1) Tambah / ubah preset")
        print("  2) Hapus preset")
        print("  3) Set preset DEFAULT (semua clone yang ikut default pindah)")
        print("  4) Atur satu clone (preset khusus / ikut default / link sendiri)")
        print("  5) Semua clone ikut default")
        print("  0) Kembali")
        local choice = trim(prompt("Pilih: ") or "0")

        if choice == "0" or choice == "" then
            return
        elseif choice == "1" then
            local key = trim(prompt("Kode preset (mis. A, B, egg): "))
            if not key:match("^[%w_]+$") or #key > 16 or key == "default" then
                print("Kode harus huruf/angka (maks 16), bukan 'default'.")
            else
                local ps = presets(conf)
                local old = ps[key] or {}
                local name = trim(prompt("Nama game [" .. tostring(old.name or "") .. "]: "))
                local link = trim(prompt("Link game / private server [" .. tostring(old.link or "") .. "]: "))
                if name == "" then name = old.name or key end
                if link == "" then link = old.link or "" end
                if not validLink(link) then
                    print("Link harus link roblox.com (games/... atau share?code=...) atau roblox://")
                else
                    ps[key] = { name = name, link = link }
                    local firstOne = (conf.defaultPreset == nil or conf.defaultPreset == "")
                    if firstOne then
                        conf.defaultPreset = key
                        print("Preset pertama: otomatis jadi DEFAULT.")
                    end
                    if save(conf) and old.link and old.link ~= link then
                        local used = {}
                        for _, inst in ipairs(InstanceManager.getAll()) do
                            if InstanceManager.presetOf(inst) == key then used[#used + 1] = inst.id end
                        end
                        offerRejoin(used)
                    end
                end
            end
        elseif choice == "2" then
            local key = pickPreset(conf, "Kode preset yang dihapus: ")
            if key then
                if conf.defaultPreset == key then
                    print("Ini preset DEFAULT. Set default lain dulu (pilihan 3).")
                else
                    presets(conf)[key] = nil
                    local n = 0
                    for _, inst in ipairs(InstanceManager.getAll()) do
                        if inst.preset == key then inst.preset = nil; n = n + 1 end
                    end
                    save(conf)
                    if n > 0 then print(n .. " clone sekarang ikut default.") end
                end
            end
        elseif choice == "3" then
            local key = pickPreset(conf, "Kode preset untuk DEFAULT: ")
            if key and key ~= conf.defaultPreset then
                conf.defaultPreset = key
                if save(conf) then offerRejoin(followersOfDefault()) end
            elseif key then
                print("Itu sudah default.")
            end
        elseif choice == "4" then
            local inst = InstanceManager.find(trim(prompt("Id / nama clone: ")))
            if not inst then
                print("Clone tidak ditemukan.")
            else
                local v = trim(prompt("Kode preset khusus, 'd' = ikut default, '-' = pakai link sendiri: "))
                local ok = true
                if v == "d" or v == "D" then
                    inst.preset = nil
                elseif v == "-" then
                    if not inst.privateServer or inst.privateServer == "" then
                        local l = trim(prompt("Link sendiri untuk clone ini: "))
                        if validLink(l) then inst.privateServer = l else print("Link tidak valid."); ok = false end
                    end
                    if ok then inst.preset = "-" end
                elseif presets(conf)[v] then
                    inst.preset = v
                else
                    print("Pilihan tidak valid."); ok = false
                end
                if ok and save(conf) then offerRejoin({ inst.id }) end
            end
        elseif choice == "5" then
            local changed = {}
            for _, inst in ipairs(InstanceManager.getAll()) do
                if inst.preset ~= nil and inst.preset ~= "" then
                    inst.preset = nil
                    changed[#changed + 1] = inst.id
                end
            end
            if #changed == 0 then
                print("Semua clone sudah ikut default.")
            elseif save(conf) then
                offerRejoin(changed)
            end
        else
            print("Pilihan tidak dikenal.")
        end
    end
end

return CLI
]]

__ya_sources["core.root_check"] = [[
-- Is root granted to Termux? Rejoin needs it for nearly everything (force-stop,
-- cookies, window layout, device settings), so main.lua stops early without it.

local RootCheck = {}

function RootCheck.ok()
    -- stdin /dev/null: su must never take the terminal (keeps Ctrl+C working).
    -- timeout: a root manager waiting on its prompt must not hang the start.
    local cmd = "if command -v timeout >/dev/null 2>&1; then timeout 15 su -c id; else su -c id; fi"
    local p = io.popen("sh -c '" .. cmd .. "' </dev/null 2>/dev/null")
    if not p then return false end
    local out = p:read("*a") or ""
    p:close()
    return out:find("uid=0", 1, true) ~= nil
end

RootCheck.MESSAGE = table.concat({
    "[XX] Root belum aktif. Rejoin butuh root (Magisk / KernelSU).",
    "     Buka Magisk -> Superuser -> izinkan Termux (Grant), lalu jalankan lagi.",
    "     Cek: su -c id  (harus muncul uid=0)",
}, "\n")

return RootCheck
]]

