__ya_sources["core.settings_cli"] = [[
local Logger = require("core.logger")
local Config = require("core.config")

local CLI = {}

local function prompt(msg)
    io.write(msg)
    io.flush()
    return io.read()
end

local function printSettings(conf)
    print("Current Settings:")
    print("Antrean baru: Menu 12. recoveryDelay/recoveryRetries/checkTimeout/freezeTimeout/gracePeriod/anrCheckEnabled/launchWaitTimeout adalah legacy.")
    print("  monitorInterval = " .. tostring(conf.monitorInterval))
    print("  recoveryDelay = " .. tostring(conf.recoveryDelay))
    print("  recoveryRetries = " .. tostring(conf.recoveryRetries))
    print("  checkTimeout = " .. tostring(conf.checkTimeout))
    print("  debug = " .. tostring(conf.debug))
    print("  logLevel = " .. tostring(conf.logLevel or "INFO"))
    print("  appAutoExecutePath = " .. tostring(conf.appAutoExecutePath or ""))
    print("  logPath = " .. tostring(conf.logPath))
    print("  clonePackagePrefix = " .. tostring(conf.clonePackagePrefix or ""))
    print("  freezeTimeout = " .. tostring(conf.freezeTimeout))
    print("  gracePeriod = " .. tostring(conf.gracePeriod))
    print("  anrCheckEnabled = " .. tostring(conf.anrCheckEnabled and true or false))
    print("  launchWaitInterval = " .. tostring(conf.launchWaitInterval))
    print("  launchWaitTimeout = " .. tostring(conf.launchWaitTimeout))
    print("  launchJoinTimeout = " .. tostring(conf.launchJoinTimeout))
    print("  launchSettleDelay = " .. tostring(conf.launchSettleDelay))
    print("  launchEmptyDelay = " .. tostring(conf.launchEmptyDelay))
    local wl = type(conf.windowLayout) == "table" and conf.windowLayout or {}
    print("  windowLayout.enabled (auto atur jendela) = " .. tostring(wl.enabled == true)
        .. ", columns = " .. tostring(wl.columns or 0) .. ", gap = " .. tostring(wl.gap or 0))
    local wh = type(conf.webhook) == "table" and conf.webhook or {}
    print("  webhook = " .. ((type(wh.url) == "string" and wh.url ~= "") and "diset" or "kosong")
        .. ", interval = " .. tostring(wh.interval or 300) .. ", screenshot = " .. tostring(wh.screenshot ~= false))
    local hb = type(conf.heartbeat) == "table" and conf.heartbeat or {}
    local sv = type(hb.saver) == "table" and hb.saver or {}
    print("  heartbeat.enabled = " .. tostring(hb.enabled ~= false)
        .. ", mode hemat = " .. tostring(sv.enabled == true)
        .. ", fpsCap = " .. tostring(sv.fpsCap or 15) .. ", render3D mati = " .. tostring(sv.disable3d ~= false))
    print("  useRoot = " .. tostring(conf.useRoot == nil and true or conf.useRoot))
end

function CLI.run()
    local conf = Config.get() or {}
    conf.monitorInterval = conf.monitorInterval or 5
    conf.recoveryDelay = conf.recoveryDelay or 3
    conf.recoveryRetries = conf.recoveryRetries or 3
    conf.checkTimeout = conf.checkTimeout or 15
    conf.debug = conf.debug == nil and true or conf.debug
    conf.logLevel = conf.logLevel or "INFO"
    conf.appAutoExecutePath = conf.appAutoExecutePath or ""
    conf.autoExecuteDeployPath = nil
    conf.logPath = conf.logPath or "data/rejoin.log"
    conf.clonePackagePrefix = conf.clonePackagePrefix or ""
    conf.freezeTimeout = conf.freezeTimeout or 300
    conf.gracePeriod = conf.gracePeriod or 30
    conf.anrCheckEnabled = conf.anrCheckEnabled ~= false
    conf.launchWaitInterval = conf.launchWaitInterval or 3
    conf.launchWaitTimeout = conf.launchWaitTimeout or 60
    conf.launchJoinTimeout = conf.launchJoinTimeout or 240
    conf.launchSettleDelay = conf.launchSettleDelay or 5
    conf.launchEmptyDelay = conf.launchEmptyDelay or 5
    if conf.useRoot == nil then conf.useRoot = true end

    while true do
        print('\nSettings Menu:\n  1) View settings\n  2) Edit monitorInterval\n  3) Edit recoveryDelay\n  4) Edit recoveryRetries\n  5) Edit checkTimeout\n  6) Toggle debug\n  7) Edit appAutoExecutePath\n  8) Edit logPath\n  9) Edit clonePackagePrefix\n 10) Edit freezeTimeout\n 11) Edit gracePeriod\n 12) Toggle anrCheckEnabled\n 13) Edit launch settings (jeda antar clone)\n 14) Edit logLevel\n 15) Save and Exit\n 16) Exit without saving\n')
        local choice = prompt("Choose: ") or ""
        choice = choice:match("^%s*(.-)%s*$")
        if choice == "1" then
            printSettings(conf)
        elseif choice == "2" then
            local v = prompt("monitorInterval (seconds): [" .. tostring(conf.monitorInterval) .. "] ")
            local n = tonumber(v)
            if n then conf.monitorInterval = n else print("Invalid number") end
        elseif choice == "3" then
            local v = prompt("recoveryDelay (seconds): [" .. tostring(conf.recoveryDelay) .. "] ")
            local n = tonumber(v)
            if n then conf.recoveryDelay = n else print("Invalid number") end
        elseif choice == "4" then
            local v = prompt("recoveryRetries: [" .. tostring(conf.recoveryRetries) .. "] ")
            local n = tonumber(v)
            if n then conf.recoveryRetries = n else print("Invalid number") end
        elseif choice == "5" then
            local v = prompt("checkTimeout (seconds): [" .. tostring(conf.checkTimeout) .. "] ")
            local n = tonumber(v)
            if n then conf.checkTimeout = n else print("Invalid number") end
        elseif choice == "6" then
            conf.debug = not conf.debug
            print("debug = " .. tostring(conf.debug))
        elseif choice == "7" then
            local v = prompt("appAutoExecutePath (folder AutoExecute, contoh: /sdcard/Delta/Autoexecute): [" .. tostring(conf.appAutoExecutePath or "") .. "] ")
            if v and v ~= "" then conf.appAutoExecutePath = v end
        elseif choice == "8" then
            local v = prompt("logPath: [" .. tostring(conf.logPath) .. "] ")
            if v and v ~= "" then conf.logPath = v end
        elseif choice == "9" then
            local v = prompt("clonePackagePrefix (empty to disable): [" .. tostring(conf.clonePackagePrefix) .. "] ")
            if v and v ~= "" then conf.clonePackagePrefix = v end
        elseif choice == "10" then
            local v = prompt("freezeTimeout (seconds before relaunch): [" .. tostring(conf.freezeTimeout) .. "] ")
            local n = tonumber(v)
            if n and n > 0 then conf.freezeTimeout = n else print("Invalid number") end
        elseif choice == "11" then
            local v = prompt("gracePeriod (seconds after launch): [" .. tostring(conf.gracePeriod) .. "] ")
            local n = tonumber(v)
            if n and n > 0 then conf.gracePeriod = n else print("Invalid number") end
        elseif choice == "12" then
            conf.anrCheckEnabled = not (conf.anrCheckEnabled and true or false)
            print("anrCheckEnabled = " .. tostring(conf.anrCheckEnabled and true or false))
        elseif choice == "13" then
            -- Launch All opens clones one by one: wait until the clone is running, then
            -- until it is in game (heartbeat, launchJoinTimeout) or launchSettleDelay.
            print("Launch All membuka clone satu per satu. Kosongkan untuk tetap pakai nilai lama.")
            local function askNumber(key, label, allowZero)
                local v = prompt(label .. ": [" .. tostring(conf[key]) .. "] ")
                if not v or v:match("^%s*$") then return end
                local n = tonumber(v)
                if n and (n > 0 or (allowZero and n == 0)) then conf[key] = n else print("Invalid number") end
            end
            askNumber("launchJoinTimeout", "Deadline loading (detik, minimum 30; habis = Perlu dicek, antrean ditahan)", false)
            askNumber("launchSettleDelay", "Jeda jika heartbeat sengaja dimatikan (detik)", true)
            askNumber("launchEmptyDelay", "Jeda setelah clone KOSONG (belum login) dibuka (detik)", true)
            askNumber("launchWaitTimeout", "Legacy: batas tunggu proses lama (detik)", false)
            askNumber("launchWaitInterval", "Interval cek saat menunggu (detik)", false)
            print("(Jendela, heartbeat & mode hemat: Main Menu 9. Discord webhook: Main Menu 8.)")
            local v = prompt("useRoot (run commands as root / su -c, true/false): [" .. tostring(conf.useRoot == nil and true or conf.useRoot) .. "] ")
            if v and v ~= "" then
                if v == "true" or v == "1" or v:lower() == "y" or v:lower() == "yes" then
                    conf.useRoot = true
                elseif v == "false" or v == "0" or v:lower() == "n" or v:lower() == "no" then
                    conf.useRoot = false
                else
                    print("Invalid value (use true/false)")
                end
            end
        elseif choice == "14" then
            local v = prompt("logLevel (DEBUG/INFO/WARN/ERROR): [" .. tostring(conf.logLevel or "INFO") .. "] ")
            if v and v ~= "" then
                local lvl = v:upper()
                if lvl == "DEBUG" or lvl == "INFO" or lvl == "WARN" or lvl == "ERROR" then
                    conf.logLevel = lvl
                else
                    print("Invalid level (use DEBUG/INFO/WARN/ERROR)")
                end
            end
        elseif choice == "15" then
            local ok, err = Config.save(conf)
            if ok then
                print("Settings saved")
                -- update logger path if changed
                local Logger = require("core.logger")
                if conf.logPath then Logger.setLogPath(conf.logPath) end
                if conf.logLevel then Logger.setLevel(conf.logLevel) end
            else
                print("Failed to save: " .. tostring(err))
            end
            break
        elseif choice == "16" then
            print("Aborting without saving")
            break
        else
            print("Unknown choice")
        end
    end
end

return CLI
]]

__ya_sources["core.setup"] = [[
local Paths = require("core.paths")
local File = require("utils.file")
local Logger = require("core.logger")

local Setup = {}
local configPath = Paths.config()
local templatePath = Paths.template()

-- Ensure a usable config exists. If config/config.lua is missing, copy template to config/config.lua
-- Optionally, pass a sourcePath to copy from instead of the packaged template
-- Returns: ok, created(boolean)/err
function Setup.ensureConfig(sourcePath)
    if File.exists(configPath) then
        Logger.info("Setup: config exists: " .. configPath)
        return true, false
    end

    local tplPath = sourcePath or templatePath

    local content, err = File.read(tplPath)
    if not content and not sourcePath then
        if type(__ya_source) == "function" then content = __ya_source("config.template") end
        if not content then
            local here = (debug.getinfo(1, "S").source or ""):match("^@(.*)/core/[^/]+$") or "."
            content, err = File.read(here .. "/config/template.lua")
        end
    end
    if not content then
        Logger.error("Setup: failed to read template: " .. tostring(err))
        return false, err
    end

    local ok, writeErr = File.write(configPath, content)
    if not ok then
        Logger.error("Setup: failed to write config: " .. tostring(writeErr))
        return false, writeErr
    end

    Logger.info("Setup: created config from template: " .. configPath)
    return true, true
end

return Setup
]]

__ya_sources["core.setup_wizard"] = [[
local Logger = require("core.logger")
local Shell = require("utils.shell")
local File = require("utils.file")
local Config = require("core.config")

local Wizard = {}

local function prompt(msg)
    io.write(msg)
    io.flush()
    return io.read()
end

-- Decide whether a package looks like a Roblox app / clone.
-- Priority:
--   1) resolve-activity: the launchable component point to a Roblox-class app
--      (component/activity containing "roblox", or a com.roblox.* package).
--   2) optional fast prefix filter (clonePackagePrefix) from settings.
local function isRobloxApp(pkg, prefix)
    local lower = pkg:lower()

    -- Optional prefix filter (fast, exact string at start), e.g. "com.apengjers."
    if prefix and prefix ~= "" and lower:find(prefix:lower(), 1, true) == 1 then
        return true
    end

    -- Package name itself mentions roblox
    if lower:find("roblox", 1, true) then
        return true
    end

    -- Resolve the launchable activity; a Roblox clone usually inherits a Roblox
    -- component like "com.roblox.client/.Activity" even when the package is renamed.
    local APK = require("managers.apk")
    local component = APK.resolveLaunchComponent(pkg)
    if component then
        local cl = component:lower()
        if cl:find("roblox", 1, true) then
            return true
        end
    end

    return false
end

local function detectRobloxPackages()
    Logger.info("SetupWizard: detecting installed packages (pm list packages)")
    local conf = Config.get() or {}
    local prefix = conf.clonePackagePrefix or ""

    local ok, out = Shell.exec("pm list packages")
    if not ok or not out then
        return nil, "detection_failed"
    end

    local pkgs = {}
    for line in out:gmatch("[^\n]+") do
        -- lines usually like: "package:com.roblox.client"
        local pkg = line:match("package:(%S+)")
        if pkg and isRobloxApp(pkg, prefix) then
            table.insert(pkgs, pkg)
        end
    end

    return pkgs
end

function Wizard.run()
    print("\n=== Rejoin Engine Setup Wizard ===\n")
    print("This wizard will help you create instances and initial configuration.")
    print("Choose mode:")
    print("  1) Auto Detect Roblox apps/clones on device (Termux/Android)")
    print("  2) Manual input (enter package names by hand)")

    local choice = prompt("Select 1 or 2: ") or ""
    choice = choice:match("^%s*(.-)%s*$")

    local conf = Config.get() or {}
    -- Start from an EMPTY list. The packaged template ships one example instance
    -- (com.roblox.client) that is almost never a real clone on this device, and
    -- keeping it leaves a phantom instance in the monitor that can never run.
    -- The wizard is a first-run "build my instance list" flow, so old entries go.
    local previous = 0
    for _ in pairs(conf.instances or {}) do previous = previous + 1 end
    conf.instances = {}
    if previous > 0 then
        print(("Menghapus %d instance lama dari config (termasuk contoh dari template)."):format(previous))
    end

    -- find next available id (pairs + normalization, so string keys don't break it)
    local function nextId()
        local maxid = 0
        for _,v in pairs(conf.instances) do
            if type(v) == "table" and type(v.id) == "number" and v.id > maxid then maxid = v.id end
        end
        return maxid + 1
    end

    if choice == "1" then
        local pkgs, err = detectRobloxPackages()
        if not pkgs or #pkgs == 0 then
            print("No Roblox packages detected or detection failed. Try Manual mode.")
            return false, "no_packages"
        end

        print("Found the following Roblox-related packages:")
        for i,p in ipairs(pkgs) do
            print(string.format("  %d) %s", i, p))
        end

        local sel = prompt("Enter indices to import (e.g. 1,2) or 'all': ") or ""
        sel = sel:lower():match("^%s*(.-)%s*$")
        local indices = {}
        if sel == "all" or sel == "a" then
            for i=1,#pkgs do table.insert(indices, i) end
        else
            for s in sel:gmatch("%d+") do table.insert(indices, tonumber(s)) end
        end

        if #indices == 0 then
            print("No indices selected. Aborting import.")
            return false, "no_selection"
        end

        for _,idx in ipairs(indices) do
            local pkg = pkgs[idx]
            if pkg then
                local id = nextId()
                local defaultName = pkg
                local name = prompt(string.format("Name for %s (press Enter for '%s'): ", pkg, defaultName)) or ""
                if name == "" then name = defaultName end
                local server = prompt("Private Server URL (or blank): ") or ""
                if server == "" then server = nil end
                table.insert(conf.instances, { id = id, name = name, package = pkg, privateServer = server })
                print(string.format("Added instance %s (%s)", name, pkg))
            end
        end

        local ok, serr = Config.save(conf)
        if not ok then
            print("Failed to save config: " .. tostring(serr))
            return false, serr
        end

        print("Setup complete. Instances imported and saved to " .. require("core.paths").config())
        return true

    else
        -- Manual mode
        print("Manual mode: enter instance details. Leave package name empty to finish.")
        while true do
            local pkg = prompt("Package name (e.g. com.roblox.client) [leave blank to finish]: ") or ""
            pkg = pkg:match("^%s*(.-)%s*$")
            if pkg == "" then break end
            local id = nextId()
            local name = prompt("Instance name (press Enter to use package as name): ") or ""
            if name == "" then name = pkg end
            local server = prompt("Private Server URL (optional): ") or ""
            if server == "" then server = nil end
            table.insert(conf.instances, { id = id, name = name, package = pkg, privateServer = server })
            print(string.format("Added instance %s (%s)", name, pkg))
        end

        if #conf.instances == 0 then
            print("No instances added. Aborting.")
            return false, "no_instances"
        end

        local ok, serr = Config.save(conf)
        if not ok then
            print("Failed to save config: " .. tostring(serr))
            return false, serr
        end

        print("Setup complete. Configuration saved to " .. require("core.paths").config())
        return true
    end
end

return Wizard
]]

__ya_sources["core.state"] = [[
local State = {}

State.current = "BOOT"

function State.set(state)

    State.current = state

end

function State.get()

    return State.current

end

function State.is(state)

