end

return State]]

__ya_sources["core.uninstall_cli"] = [[
local Uninstall = require("managers.uninstall")
local Paths = require("core.paths")

-- Submenu "Uninstall yanamin": one button that removes the auto-boot script,
-- the whole data root and (when it is the single-file loader) the loader file.
-- Everything is listed first and only happens after typing HAPUS.

local CLI = {}

local function prompt(msg)
    io.write(msg)
    io.flush()
    return io.read()
end

function CLI.run()
    local targets = Uninstall.targets()

    print("\nUninstall yanamin")
    print("  Data root : " .. Paths.base())
    print("")
    print("  Yang akan DIHAPUS:")
    if #targets == 0 then
        print("    (tidak ada — belum ada data root, script boot, atau file loader)")
    else
        for _, t in ipairs(targets) do
            if t.path then
                print("    - " .. t.what)
                print("      " .. t.path)
            else
                print("    - " .. t.what)
            end
        end
    end
    print("")
    print("  TIDAK disentuh: data app/clone, script AutoExecute, file lain di HP.")

    print("\n  1) Hapus semua (butuh ketik HAPUS)")
    print("  2) Batal")

    local choice = (prompt("Choose: ") or ""):match("^%s*(.-)%s*$")
    if choice ~= "1" then
        print("\nDibatalkan.")
        return
    end

    local typed = (prompt("Ketik HAPUS untuk konfirmasi: ") or ""):match("^%s*(.-)%s*$")
    if typed ~= "HAPUS" then
        print("\nDibatalkan (konfirmasi tidak cocok).")
        return
    end

    print("\nMenghapus...")
    local results = Uninstall.runAll()
    for _, line in ipairs(results) do print("  " .. line) end
    print("\nSelesai. Keluar...")
    print("Kalau file loader ikut terhapus, unduh ulang untuk dipakai lagi.")
    io.stdout:flush()
    os.exit(0)
end

return CLI]]

__ya_sources["core.webhook_cli"] = [[
local Config = require("core.config")

-- Main Menu 8: Discord webhook status reports (managers/webhook.lua) and the remote
-- bot connection (managers/remote.lua).
-- Pick one item at a time; every change is saved right away.

local CLI = {}

local function prompt(msg)
    io.write(msg)
    io.flush()
    return io.read()
end

local function section(conf)
    conf.webhook = type(conf.webhook) == "table" and conf.webhook or {}
    return conf.webhook
end

local function onoff(v) return v and "nyala" or "mati" end

local function save(conf)
    local ok, err = Config.save(conf)
    print(ok and "Tersimpan." or ("Gagal menyimpan: " .. tostring(err)))
end

function CLI.run()
    local conf = Config.get() or {}
    while true do
        local wh = section(conf)
        local hasUrl = type(wh.url) == "string" and wh.url ~= ""
        print("\nDiscord (Webhook & Bot):")
        print("  1) URL webhook          [" .. (hasUrl and "diset" or "kosong") .. "]")
        print("  2) Interval laporan     [" .. tostring(wh.interval or 300) .. " detik]")
        print("  3) Screenshot           [" .. onoff(wh.screenshot ~= false) .. "]")
        print("  4) Notif Delta minta key [" .. onoff(wh.events ~= false) .. "]")
        print("  5) Sembunyikan nama     [" .. onoff(wh.hideNames ~= false) .. "]")
        print("  6) Kirim tes sekarang")
        local dn = type(wh.deviceName) == "string" and wh.deviceName or ""
        print("  7) Label Device Name    [" .. (dn ~= "" and dn or "kosong = model device") .. "]")
        print("  8) Pakai pesan status lama (paste link pesan dari device lama)")
        local rm = type(conf.remote) == "table" and conf.remote or {}
        local okR, Remote = pcall(require, "managers.remote")
        print("  -- Bot Discord (kontrol jarak jauh) --   HWID: " .. (okR and Remote.deviceId() or "?"))
        print("  9) URL bot               [" .. ((type(rm.url) == "string" and rm.url ~= "") and rm.url or "kosong = ambil dari remote_url.txt") .. (rm.urlManual and ", manual" or "") .. "]")
        local sec = type(rm.secret) == "string" and rm.secret or ""
        print(" 10) Secret bot (opsional) [" .. (sec == "" and "kosong = pakai HWID" or "diset") .. "]")
        print(" 11) Tes koneksi bot")
        print("  0) Kembali")
        local choice = (prompt("Pilih: ") or "0"):match("^%s*(.-)%s*$")

        if choice == "0" or choice == "" then
            return
        elseif choice == "1" then
            local v = prompt("URL webhook (Discord > Edit Channel > Integrations > Webhooks > Copy URL; '-' = hapus): ")
            v = (v or ""):gsub("%s+", "")
            if v == "-" then
                wh.url = ""
                save(conf)
            elseif v == "" then
                print("Tidak diubah.")
            elseif v:match("^https://[%w%.%-%_]+/api/webhooks/%S+$") then
                wh.url = v
                save(conf)
            else
                print("URL tidak valid (harus https://discord.com/api/webhooks/...).")
            end
        elseif choice == "2" then
            local v = prompt("Interval laporan (detik, min 60): [" .. tostring(wh.interval or 300) .. "] ")
            local n = tonumber(v)
            if n and n >= 60 then
                wh.interval = math.floor(n)
                save(conf)
            elseif v and not v:match("^%s*$") then
                print("Angka tidak valid (min 60).")
            end
        elseif choice == "3" then
            wh.screenshot = not (wh.screenshot ~= false)
            print("Screenshot: " .. onoff(wh.screenshot))
            save(conf)
        elseif choice == "4" then
            wh.events = not (wh.events ~= false)
            print("Notif Delta minta key: " .. onoff(wh.events))
            save(conf)
        elseif choice == "5" then
            wh.hideNames = not (wh.hideNames ~= false)
            print("Sembunyikan nama: " .. onoff(wh.hideNames))
            save(conf)
        elseif choice == "6" then
            if not hasUrl then
                print("Isi URL webhook dulu (pilihan 1).")
            else
                local Webhook = require("managers.webhook")
                Webhook.configure(conf)
                local okI, Instances = pcall(require, "managers.instance")
                local list = okI and Instances.getAll and Instances.getAll() or {}
                print("Mengirim laporan tes...")
                local ok, res = pcall(Webhook.report, list)
                if ok and res then
                    print("Terkirim. Cek channel Discord.")
                else
                    print("Gagal kirim (cek URL / internet; detail di data/rejoin.log).")
                end
            end
        elseif choice == "7" then
            local v = prompt("Label Device Name (mis. 01; '-' = hapus): ")
            v = (v or ""):gsub("^%s+", ""):gsub("%s+$", "")
            if v == "-" then
                wh.deviceName = ""
                save(conf)
            elseif v == "" then
                print("Tidak diubah.")
            else
                wh.deviceName = v:sub(1, 60)
                save(conf)
            end
        elseif choice == "8" then
            if not hasUrl then
                print("Isi URL webhook dulu (pilihan 1), harus sama dengan device lama.")
            else
                print("Discord: klik kanan pesan status lama > Copy Message Link (atau Copy Message ID).")
                local v = prompt("Link / ID pesan: ")
                local Webhook = require("managers.webhook")
                Webhook.configure(conf)
                local id, err = Webhook.useMessage(v)
                if not id then
                    print(err)
                else
                    print("Mengedit pesan itu sekarang...")
                    local okI, Instances = pcall(require, "managers.instance")
                    local list = okI and Instances.getAll and Instances.getAll() or {}
                    local ok, res = pcall(Webhook.report, list)
                    if not (ok and res) then
                        print("Gagal kirim (cek URL / internet; detail di data/rejoin.log).")
                    elseif Webhook.messageId() == id then
                        print("Berhasil: pesan lama sekarang di-update oleh device ini.")
                    else
                        print("Pesan itu tidak bisa diedit (sudah dihapus atau dari webhook lain); dibuat pesan baru.")
                    end
                end
            end
        elseif choice == "9" or choice == "10" then
            conf.remote = type(conf.remote) == "table" and conf.remote or {}
            if choice == "9" then
                local v = (prompt("URL bot (mis. https://nama-bot.onrender.com; '-' = hapus): ") or ""):gsub("%s+", "")
                -- A typed URL is never replaced by remote_url.txt (urlManual); '-' goes back to it.
                if v == "-" then conf.remote.url = ""; conf.remote.urlManual = nil; save(conf)
                elseif v == "" then print("Tidak diubah.")
                elseif v:match("^https://[%w%.%-]+") then
                    conf.remote.url = v:gsub("/+$", ""); conf.remote.urlManual = true; save(conf)
                else print("URL harus diawali https://") end
            else
                print("Biasanya ga perlu: cukup daftarkan HWID di atas lewat /hwid redeem di Discord.")
                print("Isi cuma kalau pakai secret lama (DEVICE_SECRET / OWNERS di bot).")
                local v = (prompt("Secret bot (opsional, '-' = hapus): ") or ""):gsub("%s+", "")
                if v == "-" then conf.remote.secret = ""; save(conf)
                elseif v == "" then print("Tidak diubah.")
                else conf.remote.secret = v; save(conf) end
            end
        elseif choice == "11" then
            local ok, msg = require("managers.remote").test()
            print((ok and "OK: " or "Gagal: ") .. tostring(msg))
            print("(Perintah dari bot dijalankan selama monitor / Launch All jalan.)")
        else
            print("Pilihan tidak dikenal.")
        end
    end
end

return CLI
]]

__ya_sources["managers.apk"] = [[
local Logger = require("core.logger")
local Shell = require("utils.shell")

local APKManager = {}

local function validPackageName(packageName)
    return type(packageName) == "string"
        and packageName:match("^[%a_][%w_%.]*$") ~= nil
end

local function packageArg(packageName)
    return "'" .. packageName:gsub("'", "'\\''") .. "'"
end

-- Android stops processes at package scope. If config maps multiple logical clones
-- to the same package, there is no safe way to stop just one of them, so fail closed.
local function packageIsUnique(packageName)
    local ok, Instances = pcall(require, "managers.instance")
    if not ok or type(Instances.getAll) ~= "function" then return true end
    local matches = 0
    for _, inst in ipairs(Instances.getAll() or {}) do
        if type(inst) == "table" and inst.package == packageName then matches = matches + 1 end
    end
    return matches <= 1
end

-- Resolve the default launchable activity component for a package (best-effort).
-- Returns the component string like "com.roblox.client/.Activity" or nil on failure.
function APKManager.resolveLaunchComponent(packageName)
    if not validPackageName(packageName) then return nil end
    -- cmd package resolve-activity --brief returns the package/activity component on the last line
    local cmd = string.format("cmd package resolve-activity --brief %s", packageArg(packageName))
    local ok, out = Shell.exec(cmd)
    if ok and out then
        for line in out:gmatch("[^\r\n]+") do
            local comp = line:match("(%S+%/%S+)")
            if comp then
                return comp
            end
        end
    end
    return nil
end

-- Launch an APK by package name for Termux/Android.
--
-- Order of attempts:
--   1) `am start -a MAIN -c LAUNCHER -p <pkg>`  -- targets the package explicitly and
--      starts its own task/launcher activity. Works for cloned apps (each clone is a
--      distinct package) and does NOT depend on `cmd package resolve-activity`, which is
--      often unavailable in a Termux (non-adb, non-root) shell.
--   2) `monkey -p <pkg> -c LAUNCHER 1`          -- legacy fallback.
--   3) resolve-activity + `am start -n <component>` -- best-effort fallback.
--
-- Returns (success, output_or_err).
function APKManager.launch(packageName)
    if not validPackageName(packageName) then return false, "invalid_package" end
    Logger.info("APKManager: launching package: " .. tostring(packageName))
    APKManager.invalidateSnapshot()

    -- 1) Primary: am start MAIN/LAUNCHER targeting the package explicitly.
    local pkgArg = packageArg(packageName)
    local cmd = string.format("am start -a android.intent.action.MAIN -c android.intent.category.LAUNCHER -p %s", pkgArg)
    Logger.info("APKManager: exec: " .. cmd)
    local ok, out = Shell.exec(cmd)
    local failedHint = { "Error", "Failure", "Exception", "does not exist", "is not allowed", "Activity not started" }
    local failed = false
    if ok and out then
        for _, h in ipairs(failedHint) do
            if out:find(h, 1, true) then failed = true break end
        end
        if not failed then
            Logger.info("APKManager: am start accepted for " .. tostring(packageName))
            APKManager.invalidateSnapshot()
            return true, out
        end
    else
        failed = true
    end
    Logger.warn("APKManager: am start launch failed/not accepted for " .. tostring(packageName) .. ": " .. tostring(out))

    -- 2) Fallback: monkey launches the main activity of a package by name (no component needed)
    cmd = string.format("monkey -p %s -c android.intent.category.LAUNCHER 1", pkgArg)
    Logger.info("APKManager: fallback exec: " .. cmd)
    ok, out = Shell.exec(cmd)
    if ok and out then
        -- monkey exits 0 even on some errors; only treat as success on injected events
        if out:find("Events injected", 1, true) then
            Logger.info("APKManager: monkey launch injected events for " .. tostring(packageName))
            APKManager.invalidateSnapshot()
            return true, out
        end
        Logger.warn("APKManager: monkey reported an error for " .. tostring(packageName) .. ": " .. tostring(out))
    else
        Logger.warn("APKManager: monkey launch failed/empty for " .. tostring(packageName))
    end

    -- 3) Fallback: resolve the launchable activity then `am start` (best-effort)
    local component = APKManager.resolveLaunchComponent(packageName)
    if component then
        Logger.info("APKManager: fallback resolved launch component: " .. tostring(component))
        local ok2, out2 = Shell.exec(string.format("am start -n %s", component))
        if ok2 and out2 and out2:find("Error", 1, true) == nil then
            APKManager.invalidateSnapshot()
            return true, out2
        end
        Logger.warn("APKManager: fallback am start failed for " .. tostring(packageName) .. ": " .. tostring(out2))
    end

    return false, out
end

function APKManager.forceStop(packageName)
    if not validPackageName(packageName) then return false, "invalid_package" end
    if not packageIsUnique(packageName) then
        return false, "package dipakai lebih dari satu instance; force-stop dibatalkan agar clone lain tidak ikut tertutup"
    end
    Logger.info("APKManager: force stopping: " .. tostring(packageName))
    -- Limit the stop to the current Android user and one validated package name.
    local cmd = string.format("am force-stop --user current %s", packageArg(packageName))
    local ok, out = Shell.exec(cmd)
    APKManager.invalidateSnapshot()
    return ok, out
end

-- Escape regex metacharacters so a package name is matched literally in a POSIX ERE
-- (as consumed by `pgrep -f`). Produces `\.` etc. (backslash-dot), NOT `%.` (percent-dot).
local function escapeRegex(s)
    return s:gsub("([%^%$%(%)%%%.%[%]%*%+%-%?])", "\\%1")
end

-- ---------------------------------------------------------------------------
-- Process snapshot: ONE `ps -A` per monitor cycle instead of one per probe.
--
-- isRunning, isActive and getRSSinKB are each called once per instance per cycle, and
-- every one of them used to shell out (pidof / pgrep / ps -A). With four clones that
-- added up to ~20 `su` spawns per cycle. The snapshot parses `ps -A` once and is then
-- reused by all probes in the same cycle.
--
-- It is invalidated explicitly after launch / force-stop / recovery (see
-- APKManager.invalidateSnapshot) and also expires after SNAPSHOT_TTL, so a stale list
-- can never outlive a process change we did not initiate.
-- ---------------------------------------------------------------------------
local SNAPSHOT_TTL = 1.5 -- seconds
local snapshot = nil

local function parseSnapshot(out)
    local byName, order = {}, {}
    for line in out:gmatch("[^\r\n]+") do
        local fields = {}
        for f in line:gmatch("%S+") do fields[#fields + 1] = f end
        if #fields >= 9 then
            local name = fields[#fields]
            if name ~= "" then
                byName[name] = { name = name, pid = fields[2], rssKb = tonumber(fields[5]) or -1 }
                order[#order + 1] = name
            end
        end
    end
    return { byName = byName, order = order, at = os.time() }
end

-- Cached process list, refreshed when older than SNAPSHOT_TTL.
-- Returns nil when `ps -A` cannot be read; callers then use their own fallback probe.
function APKManager.snapshot()
    if snapshot and (os.time() - snapshot.at) < SNAPSHOT_TTL then
        return snapshot
    end
    local ok, out = Shell.exec("ps -A")
    if not ok or not out or out == "(dry-run)" then
        snapshot = nil
        return nil
    end
    snapshot = parseSnapshot(out)
    return snapshot
end

-- Drop the cached process list. Call after anything that changes the process table so
-- the next probe in the same cycle reads fresh data.
function APKManager.invalidateSnapshot()
    snapshot = nil
end

-- Check whether a package has a running process. A clone's MAIN process runs under its
-- own exact package name (e.g. com.apengjers.v3), so we match that name EXACTLY — NOT
-- sub-processes like `com.apengjers.v3:p0` (background services that keep running after
-- the UI is swiped away, which previously left `isRunning` true -> status stuck at "ingame"
-- -> the closed app was never recovered/open again).
-- Returns true if any method finds a matching process, false otherwise.
function APKManager.isRunning(packageName)
    if not packageName or packageName == "" then return false end
    local pkg = packageName:gsub("['\" ]", "")
    if pkg == "" then return false end

    -- 1) Snapshot: one `ps -A` shared by every probe in this cycle.
    local snap = APKManager.snapshot()
    if snap and next(snap.byName) ~= nil then
        return snap.byName[pkg] ~= nil
    end

    -- 2) Snapshot unavailable (restricted shell / unreadable ps) -> probe directly.
    -- pidof: exact process-name match; busybox sometimes missing it.
    local ok, out = Shell.exec(string.format("pidof %s", pkg))
    if ok and out and out ~= "" and out ~= "(dry-run)" then
        return true
    end

    -- pgrep -f with a pattern matching this clone's exact process command
    local pattern = "^" .. escapeRegex(pkg) .. "$"
    ok, out = Shell.exec(string.format("pgrep -f '%s'", pattern))
    if ok and out and out ~= "" and out ~= "(dry-run)" then
        return true
    end

    return false
end

-- ---------------------------------------------------------------------------
-- RSS/memory-based "active" detection.
--
-- On this device `dumpsys activity`/`dumpsys window` does NOT list the floating-window
-- clones at all (even when fully running), so UI visibility can't be used. The signal
-- that actually separates a running clone from a force-close stub is resident memory:
--    * running clone    ~1 GB    (RSS from `ps -A`, kB)
--    * force-close stub ~188 MB   (observed when the floating window was closed)
--    * earliest running example seen ~235 MB (older build)
-- So we treat a clone as ACTIVE only when its process exists AND its RSS is at or above
-- a threshold (config.minRss, default 300 MB). A low-RSS stub therefore reads as
-- "not active" -> recovery relaunches it.
--
-- getRSSinKB(pkg): RSS in kilobytes from `ps -A`, or -1 if no process / not parseable.
-- isActive(pkg):  process exists AND RSS >= threshold. Returns boolean.
-- ---------------------------------------------------------------------------

local function rssThreshold()
    local ok, cfg = pcall(require, "core.config")
    if ok and cfg then
        local g = cfg.get and cfg.get() or {}
        local v = tonumber(g and g.minRss)
        if v and v > 0 then return v * 1024 end -- config stored in MB -> kB
    end
    return 300 * 1024 -- default 300 MB (in kB)
end

function APKManager.getRSSinKB(packageName)
    if not packageName or packageName == "" then return -1 end
    local pkg = packageName:gsub("['\" ]", "")
    if pkg == "" then return -1 end
    local snap = APKManager.snapshot()
    if snap and next(snap.byName) ~= nil then
        local entry = snap.byName[pkg]
        if entry then return entry.rssKb end
        return -1
    end

    -- Snapshot unavailable -> read `ps -A` directly.
    local ok, out = Shell.exec("ps -A")
    if not ok or not out or out == "(dry-run)" then return -1 end
    for line in out:gmatch("[^\r\n]+") do
        local fields = {}
        for f in line:gmatch("%S+") do fields[#fields + 1] = f end
        if #fields >= 9 and fields[#fields] == pkg then
            local rss = tonumber(fields[5])
            if rss then return rss end
            return -1
        end
    end
    return -1
end

-- Does the package have a window on screen? A force-closed clone can leave a stub
-- process alive with no window at all. Window lines in `dumpsys window windows` look
-- like "Window{a1b2c3 u0 com.pkg/com.pkg.Activity}" (or "... u0 com.pkg}" for a
-- floating window titled with the package).
-- Returns true / false, or nil when the dump could not be read (caller: don't guess).
function APKManager.hasWindow(packageName)
    if not packageName or packageName == "" then return nil end
    local pkg = packageName:gsub("['\" ]", "")
    local ok, out = Shell.exec("dumpsys window windows")
    if not ok or not out or out == "" or out == "(dry-run)" then return nil end
    if not out:find("Window{", 1, true) then return nil end
    local esc = pkg:gsub("%p", "%%%0")
    for line in out:gmatch("[^\r\n]+") do
        if line:find("Window{", 1, true) and line:match(" u%d+ " .. esc .. "[/}%s]") then
            return true
        end
    end
    return false
end

function APKManager.isActive(packageName)
    if not packageName or packageName == "" then return false end
    if not APKManager.isRunning(packageName) then return false end
    local rss = APKManager.getRSSinKB(packageName)
    if rss < 0 then return false end
    return rss >= rssThreshold()
end


-- Used by "Launch All" to detect how many clones have actually come up: every Roblox
-- clone runs a process named `com.roblox.client`, so waiting for the count to reach the
-- number of clones launched gives a reliable per-launch progress signal even when the
-- per-package process name differs from the package (App Cloner renames packages only).
-- Returns a number (>= 0). In dry-run returns 1 (as if one process is running).
function APKManager.countProcess(name)
    if not name or name == "" then return 0 end

    -- 1) Snapshot: count the exact process plus its `name:sub` services.
    local snap = APKManager.snapshot()
    if snap and next(snap.byName) ~= nil then
        local n = 0
        for _, entryName in ipairs(snap.order) do
            if entryName == name or entryName:sub(1, #name + 1) == name .. ":" then
                n = n + 1
            end
        end
        return n
    end

    -- 2) Snapshot unavailable -> probe directly.
    -- pgrep -f <name>: one PID per line; count non-empty lines (works on busybox).
    local ok, out = Shell.exec(string.format("pgrep -f %s", name))
    if ok and out and out == "(dry-run)" then
        return 1
    end
    if ok and out and out ~= "" then
        local n = 0
        for _ in (out.."\n"):gmatch("[^\r\n]+") do
            n = n + 1
        end
        return n
    end

    -- pidof <name>: a space-separated list of PIDs; count tokens.
    ok, out = Shell.exec(string.format("pidof %s", name))
    if ok and out and out ~= "" and out ~= "(dry-run)" then
        local n = 0
        for _ in (out.." "):gmatch("%S+") do
            n = n + 1
        end
        return n
    end

    return 0
end

-- Count how many of the given packages currently have a running process.
-- Used by "Launch All" to decide when each launched clone is actually up, so it can
-- move on to the next one. Unlike countProcess (which matches a single base name),
-- this matches each clone's own package name, which is more accurate because every
-- App Cloner clone keeps its own process name (e.g. com.apengjers.v3).
function APKManager.countRunning(packages)
    if not packages then return 0 end
    local n = 0
    for _, pkg in ipairs(packages) do
        if APKManager.isRunning(pkg) then
            n = n + 1
        end
    end
    return n
end

return APKManager
]]

__ya_sources["managers.auth"] = [[
local Logger = require("core.logger")
local Shell = require("utils.shell")

-- Auth / account-login detection.
--
-- Roblox (incl. Lite/Floating mod clones) stores its session cookie as a
-- `.ROBLOSECURITY` token somewhere under the app's data directory. For a stock
-- install that is the WebView cookie DB at
--   /data/data/<package>/app_webview/Default/Cookies   (a SQLite file)
-- but modded/"Lite" clones can keep it in a different place (databases, shared_prefs,
-- app_flutter, ...). Rather than pin one path, we SCAN the clone's data directory
-- recursively (root) for the token.
--
-- A clone that has NEVER been logged in has no `.ROBLOSECURITY` token anywhere, so we
-- can tell "not logged in" apart from "force-close stub". When `isLoggedIn == false`
-- the monitor/recovery must NEVER force-relaunch the clone (low RSS is expected while
-- sitting on the login screen).
--
-- Returns:
--   true  -> an account is logged in (a session token is present)
--   false -> definitely NOT logged in (no token found anywhere under the data dir)
--   nil   -> could not determine (e.g. root read failed). Callers fall back to the
--            restart-safe behavior (treat as logged in / relaunch normally).
--
-- The scan is cached per instance for a short TTL so we do not grep every monitor cycle.
-- `cookiePath`, if set on an instance, overrides the base directory to scan.

local Auth = {}

-- Cache: pkg -> { result, at }  (result one of true/false/nil)
local cache = {}
local TTL = 30 -- seconds

-- Resolved sqlite3 runner: nil = not probed yet, false = none available.
local sqliteRunner = nil

-- WebKit stores expiry as microseconds since 1601-01-01.
local WEBKIT_EPOCH_OFFSET = 11644473600

local function defaultBaseDir(pkg)
    return "/data/data/" .. pkg
end

local function baseDir(instance)
    if instance and instance.cookiePath and instance.cookiePath ~= "" then
        return instance.cookiePath
    end
    if instance and instance.package then
        return defaultBaseDir(instance.package)
    end
    return nil
end

-- Public helper: the base directory under which this instance's session data lives
-- (honours the per-instance `cookiePath` override). Shared with cookie_injector so the
-- injection targets the exact same location the login scan uses.
function Auth.getBaseDir(instance)
    return baseDir(instance)
end

-- Files that may contain the token text without being a live session: our own
-- Cookies DB backups (`Cookies.bak-<stamp>`) and SQLite rollback journals. Counting
-- them made a logged-out clone read as logged in forever, so the monitor kept
-- force-stopping and relaunching it.
local function isStaleCopy(path)
    return path:find(".bak-", 1, true) ~= nil or path:sub(-8) == "-journal"
end

-- Authoritative check: ask SQLite whether any Cookies DB under `base` holds a live,
-- non-empty .ROBLOSECURITY row. Logging out deletes the row, but its bytes can stay in
-- the DB file, so grepping the raw file is not enough. Returns true/false, or nil when
-- there is no Cookies DB or sqlite3 is unavailable (caller falls back to grep).
local function sessionInCookieDb(base)
    local okReq, CookieInjector = pcall(require, "managers.cookie_injector")
    if not okReq then return nil end
    local dbs = CookieInjector.locateCookieDbs(base)
    if not dbs or #dbs == 0 then return nil end
    if sqliteRunner == nil then
        sqliteRunner = CookieInjector.resolveSqlite3(dbs[1]) or false
    end
    if not sqliteRunner then return nil end

    local now = string.format("%.0f", (os.time() + WEBKIT_EPOCH_OFFSET) * 1000000)
    local answered = false
    for _, db in ipairs(dbs) do
        local quoted = "'" .. db:gsub("'", "'\\''") .. "'"
        local sql = "SELECT COUNT(*) FROM cookies WHERE name='.ROBLOSECURITY'"
            .. " AND length(value) > 0 AND (expires_utc = 0 OR expires_utc > " .. now .. ");"
        local called, succeeded, out = pcall(function()
            return Shell.exec(sqliteRunner .. " " .. quoted .. " \"" .. sql .. "\"")
        end)
        local n = called and succeeded and tonumber((out or ""):match("^%s*(%d+)%s*$"))
        if n then
            answered = true
            if n > 0 then return true end
        end
    end
    if answered then return false end
    return nil
end

-- Cookie DB files (main DB plus its WAL/SHM), already read row-by-row via SQLite.
local function isCookieDb(path)
    return path:match("/Cookies$") ~= nil or path:match("/Cookies%-wal$") ~= nil
        or path:match("/Cookies%-shm$") ~= nil
end

-- Grep recursively (as root) for the token under `base`. Returns the matching file
-- paths (newline separated, "" = none), or nil if the probe itself failed. Stale copies
-- are always skipped; `skipCookieDbs` also skips Cookies DBs that SQLite already
-- answered for, so only other session stores (modded clones) count.
-- ---------------------------------------------------------------------------
-- Remote check: the token found on disk is sent to Roblox
-- (users.roblox.com/v1/users/authenticated) with curl. A token Roblox rejects
-- (HTTP 401: logged out, kicked, or revoked) means the clone is NOT logged in even
-- though a cookie row still exists. Results are cached per clone for
-- `loginVerifyInterval` seconds (default 600) so Roblox is not hit every cycle.
-- Set `loginVerifyRemote = false` in config to turn it off. The token is never logged.
-- ---------------------------------------------------------------------------
local remote = {} -- pkg -> { result, at, code, name }
local curlBin = nil -- nil = not probed yet, false = none

local function confValue(key)
    local ok, conf = pcall(function() return require("core.config").get() end)
    if not ok or type(conf) ~= "table" then return nil end
    return conf[key]
end

local function shellOut(cmd)
    local called, succeeded, out = pcall(function() return Shell.exec(cmd) end)
    if not called or not succeeded or not out or out == "(dry-run)" then return nil end
    return out
end

local function resolveCurl()
    if curlBin ~= nil then return curlBin end
    curlBin = false
    for _, c in ipairs({ "/data/data/com.termux/files/usr/bin/curl", "/system/bin/curl" }) do
        local out = shellOut("[ -x '" .. c .. "' ] && echo AE_YES || echo AE_NO")
        if out and out:find("AE_YES", 1, true) then curlBin = c; break end
    end
    return curlBin
end

local function validTokenText(t)
    return t and #t >= 20 and #t <= 2048 and not t:find("[%s'\"\\]") and t or nil
end

-- Read the live token: newest non-empty cookie row first, then a grep over the data
-- dir that skips our backups.
local function readToken(base)
    if sqliteRunner then
        local okReq, CookieInjector = pcall(require, "managers.cookie_injector")
        local dbs = okReq and CookieInjector.locateCookieDbs(base) or nil
        for _, db in ipairs(dbs or {}) do
            local quoted = "'" .. db:gsub("'", "'\\''") .. "'"
            local out = shellOut(sqliteRunner .. " " .. quoted
                .. " \"SELECT value FROM cookies WHERE name='.ROBLOSECURITY' AND length(value) > 0"
                .. " ORDER BY last_access_utc DESC LIMIT 1;\"")
            local tok = validTokenText(out and out:match("^%s*(.-)%s*$"))
            if tok then return tok, "cookie_db" end
        end
    end
    local quoted = "'" .. base:gsub("'", "'\\''") .. "'"
    -- Token shape: _|WARNING:-DO-NOT-SHARE-THIS.--...-items.|_<base64-ish session>
    local out = shellOut("grep -a -r -h -o -E '_[|]WARNING:-DO-NOT-SHARE[A-Za-z.-]*[|]_[A-Za-z0-9+/=_-]{20,}' --exclude='*.bak-*' "
        .. quoted .. " 2>/dev/null | head -1")
    local tok = validTokenText(out and out:match("^%s*(.-)%s*$"))
    if tok then return tok, "grep" end
    return nil, "not_found"
end

-- Returns true (Roblox accepts the token), false (Roblox rejects it), or nil when it
-- could not be checked (no token, no curl, no network, unexpected answer).
local function remoteCheck(pkg, base)
    if confValue("loginVerifyRemote") == false then return nil end
    local ttl = tonumber(confValue("loginVerifyInterval")) or 600
    local now = os.time()
    local token, source = readToken(base)
    -- Re-check right away when the token changed (e.g. the user logged in again).
    local c = remote[pkg]
    if c and c.token == token and now - c.at < ttl then return c.result end

    local result, code, name, note = nil, nil, nil, nil
    local bin = resolveCurl()
    if not token then
        note = "token tidak ketemu (" .. source .. ")"
    elseif not bin then
        note = "curl tidak ada (pkg install curl)"
    else
        local out = shellOut(string.format(
            "%s -s --max-time 8 -w '\n%%{http_code}' -H 'Cookie: .ROBLOSECURITY=%s' https://users.roblox.com/v1/users/authenticated",
            bin, token))
        local body, codeStr = (out or ""):match("^(.-)\n?(%d%d%d)$")
        code = tonumber(codeStr)
        if code == 200 and body and body:find('"id"', 1, true) then
            result = true
            name = body:match('"name"%s*:%s*"([^"]*)"')
        elseif code == 401 then
            result = false
        end
        note = string.format("token=%s len=%d http=%s", source, #token, tostring(code or "gagal"))
    end

    remote[pkg] = { result = result, at = now, code = code, name = name, token = token }
    Logger.info(string.format("[LOGIN] %s verifikasi Roblox: %s -> %s%s", pkg, note,
        result == nil and "tidak pasti (pakai hasil lokal)" or (result and "VALID" or "DITOLAK (dianggap logout)"),
        name and (" user=" .. name) or ""))
    return result
end

-- Username from the last successful remote check (lets Username skip its own call).
function Auth.remoteName(pkg)
    local c = remote[pkg]
    if c and c.result == true then return c.name end
    return nil
end

local function countToken(base, skipCookieDbs)
    -- `grep -a -r -l` prints the file paths that contain the token; `-l` means we only
    -- get file names (one per line) so the count is the number of files with the token.
    local quoted = "'" .. base:gsub("'", "'\\''") .. "'"
    local cmd = string.format("grep -a -r -l '.ROBLOSECURITY' %s 2>/dev/null", quoted)
    -- Shell.exec returns (ok, output); pcall returns (true, ok, output) so capture the
    -- THIRD value (the actual output string), not the second (Shell's ok boolean).
    local called, succeeded, out, code = pcall(function() return Shell.exec(cmd) end)
    if not called or not out or out == "(dry-run)" then return nil end
    if not succeeded then
        if code == 1 then return "" end -- grep found no match
        return nil -- unreadable directory or other grep failure
    end
    -- Empty output = no matches found (dir exists and was scanned OK). We cannot tell a
    -- truly empty result from "grep failed" via output alone, so first verify the base
    -- dir is readable; if it is, empty means "no session".
    local live = {}
    for line in out:gmatch("[^\r\n]+") do
        if not isStaleCopy(line) and not (skipCookieDbs and isCookieDb(line)) then
            live[#live + 1] = line
        end
    end
    return table.concat(live, "\n")
end

local function baseDirExists(base)
    local quoted = "'" .. base:gsub("'", "'\\''") .. "'"
    local cmd = string.format("[ -d %s ] && echo AE_DIR || echo AE_NODIR", quoted)
    -- See countToken: capture the THIRD pcall value (the output string).
    local called, succeeded, out = pcall(function() return Shell.exec(cmd) end)
    if not called or not succeeded or not out or out == "(dry-run)" then return nil end
    if out:find("AE_DIR", 1, true) then return true end
    if out:find("AE_NODIR", 1, true) then return false end
    return nil
end

function Auth.isLoggedIn(instance)
    local pkg = instance and instance.package
    if not pkg then return nil end
    local base = baseDir(instance)
    if not base then return nil end

    -- Cache check.
    local cached = cache[pkg]
    local now = os.time()
    if cached and now - cached.at < TTL then
        return cached.result
    end

    local result, dbResult
    do
        local exists = baseDirExists(base)
        if exists == false then
            -- Data dir does not exist => the app has never stored anything => not logged in.
            result = false
        elseif exists == nil then
            -- Could not even probe the dir => indeterminate.
            result = nil
        else
            result = sessionInCookieDb(base)
            dbResult = result
        end
        -- Modded/Lite clones may keep the session outside the WebView Cookies DB, so a
        -- "no row" answer is still cross-checked against the rest of the data dir.
        if exists and result ~= true then
            local hits = countToken(base, result == false)
            if hits ~= nil then
                result = hits ~= ""
            end
        end
    end

    -- A probe that fails once (e.g. a slow grep hitting the shell timeout) must not
    -- flip a known logged-out clone back to "unknown", which callers treat as
    -- logged in and recover. Keep the last definite answer until a new one arrives.
    if result == nil and cached and cached.result ~= nil then
        result = cached.result
    end

    -- A token on disk is not proof of a session: ask Roblox whether it still accepts it.
    local remoteResult = nil
    if result == true then
        remoteResult = remoteCheck(pkg, base)
        if remoteResult == false then result = false end
    end

    if not cached or cached.result ~= result then
        Logger.info(string.format("[LOGIN] %s login = %s (cookie db = %s, roblox = %s)",
            pkg, tostring(result), tostring(dbResult), tostring(remoteResult)))
    end
    cache[pkg] = { result = result, at = now }
    Logger.debug(string.format("Auth.isLoggedIn(%s): base=%s -> %s", pkg, base, tostring(result)))
    return result
end

-- Forget one clone's cached login state (after logging it out / injecting a cookie).
function Auth.forget(pkg)
    cache[pkg] = nil
    remote[pkg] = nil
end

-- Clear the cache (e.g. after a login/logout or on monitor start).
function Auth.resetCache()
    cache = {}
    remote = {}
end

return Auth
]]

__ya_sources["managers.autoexecute"] = [[
local Logger = require("core.logger")
local File = require("utils.file")
local Config = require("core.config")

-- AutoExecute manager — manages configuration.
--
-- The user writes `.lua` scripts that Delta executes on launch. Rejoin manages them
-- DIRECTLY inside the app's autoexecute folder (`conf.appAutoExecutePath`, e.g.
-- `/sdcard/Delta/Autoexecute`). No separate staging folder, no deploy step:
-- Add / Edit / Delete write straight to that folder via absolute paths.
--
-- No shell / su is used anywhere in this module: listing is a pure read, and the
-- folder is created lazily on save (File.write ensures its parent dir exists).

local AutoExecute = {}

-- Absolute path of the app autoexecute folder managed by this module.
local function appDir()
    local conf = Config.get() or {}
    local dir = conf.appAutoExecutePath
    if not dir or dir == "" then
        return nil, "appAutoExecutePath is empty (set it in config/config.lua)"
    end
    -- Expect absolute paths. Relative paths break when commands later run through
    -- su -c (whose working dir is /, not the Lua cwd).
    if not dir:match("^/") then
        Logger.warn("AutoExecute: appAutoExecutePath should be absolute (got: " .. tostring(dir) .. ")")
    end
    return dir
end

-- List scripts (names of *.lua) in the app autoexecute folder.
function AutoExecute.list()
    local dir, err = appDir()
    if not dir then return nil, err end
    local names, lerr = File.listDir(dir, "lua")
    if not names then return nil, lerr end
    local out = {}
    for _, n in ipairs(names) do
        local p = dir .. "/" .. n
        local size = 0
        local content = File.read(p)
        if content then size = #content end
        table.insert(out, { name = n, size = size, path = p })
    end
    return out
end

-- Save (create or overwrite) a script directly into the app folder.
function AutoExecute.save(name, content)
    name = name and name:gsub("[^%w%._%-]", "_") or ""
    name = name:gsub("%.lua$", "")
    if name == "" then return false, "invalid_name" end
    local dir, err = appDir()
    if not dir then return false, err end
    local file = dir .. "/" .. name .. ".lua"
    local ok, werr = File.write(file, content)
    if not ok then return false, werr or "write_failed" end
    Logger.info(string.format("AutoExecute: saved %s", file))
    return true, file
end

-- Read a script's content back.
function AutoExecute.read(name)
    name = name and name:gsub("%.lua$", "") or ""
    if name == "" then return nil, "invalid_name" end
    local dir, err = appDir()
    if not dir then return nil, err end
    return File.read(dir .. "/" .. name .. ".lua")
end

-- Remove a script from the app folder. Returns (true) or (false, err).
function AutoExecute.remove(name)
    name = name and name:gsub("%.lua$", "") or ""
    if name == "" then return false, "invalid_name" end
    local dir, err = appDir()
    if not dir then return false, err end
    local file = dir .. "/" .. name .. ".lua"
    if not File.exists(file) then return false, "not_found" end
    local ok = os.remove(file)
    if not ok then return false, "remove_failed" end
    Logger.info(string.format("AutoExecute: removed %s", file))
    return true
end

-- Scripts folder ------------------------------------------------------------------
-- Delta keeps a "Scripts" folder (a library run by hand) next to "Autoexecute". The
-- bot and Menu 4 store scripts there; Autoexecute only ever gets a COPY of a script
-- from Scripts (autoAdd) and loses it again with autoRemove — scripts are never
-- written straight into Autoexecute. The Delta folder is shared by every clone on the
-- device, so all of this applies to all clones at once.

local MAX_SIZE = 200 * 1024
local MANAGED = { ["rejoin_heartbeat.lua"] = true }
AutoExecute.MAX_SIZE = MAX_SIZE

local function isDir(path)
    local p = io.popen("[ -d '" .. path:gsub("'", "'\\''") .. "' ] && echo Y")
    local out = p and p:read("*a") or ""
    if p then p:close() end
    return out:find("Y", 1, true) ~= nil
end

-- Absolute path of the Scripts folder (config scriptsPath, else Scripts / scripts next
-- to the Autoexecute folder; the first is used when neither exists yet).
function AutoExecute.scriptsDir()
    local conf = Config.get() or {}
    if type(conf.scriptsPath) == "string" and conf.scriptsPath ~= "" then
        return (conf.scriptsPath:gsub("/+$", ""))
    end
    local ae, err = appDir()
    if not ae then return nil, err end
    local parent = ae:gsub("/+$", ""):match("^(.*)/[^/]+$") or ae
    for _, n in ipairs({ "Scripts", "scripts" }) do
        if isDir(parent .. "/" .. n) then return parent .. "/" .. n end
    end
    return parent .. "/Scripts"
end

-- "egg farm" -> nil; "egg_farm" -> "egg_farm.lua"; "x.txt" stays. nil, err when invalid.
local function cleanName(name)
    name = tostring(name or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if name == "" or not name:match("^[%w_%-%.]+$") or name:match("^%.") or #name > 64 then
        return nil, "nama script hanya huruf/angka/_-. (maks 64)"
    end
    if not name:match("%.lua$") and not name:match("%.txt$") then name = name .. ".lua" end
    return name
end
AutoExecute.cleanName = cleanName

local function scriptFiles(dir)
    local out = {}
    local names = dir and File.listDir(dir) or nil
    for _, n in ipairs(names or {}) do
        if n:match("%.lua$") or n:match("%.txt$") then
            local c = File.read(dir .. "/" .. n)
            out[#out + 1] = { name = n, size = c and #c or 0 }
        end
    end
    return out
end

-- Scripts folder: { name, size, auto } (auto = also in Autoexecute).
function AutoExecute.scriptsList()
    local sd, err = AutoExecute.scriptsDir()
    if not sd then return nil, err end
    local ae = appDir()
    local list = scriptFiles(sd)
    for _, e in ipairs(list) do e.auto = ae and File.exists(ae .. "/" .. e.name) or false end
    return list
end

-- Autoexecute folder: { name, size, fromScripts, managed }.
function AutoExecute.autoList()
    local ae, err = appDir()
    if not ae then return nil, err end
    local sd = AutoExecute.scriptsDir()
    local list = scriptFiles(ae)
    for _, e in ipairs(list) do
        e.managed = MANAGED[e.name] or false
        e.fromScripts = sd and File.exists(sd .. "/" .. e.name) or false
    end
    return list
end

-- Save into Scripts. When the script is also in Autoexecute its copy there is
-- refreshed so both stay the same. Returns name, replaced(bool), autoUpdated(bool).
function AutoExecute.scriptSave(name, content)
    local n, err = cleanName(name)
    if not n then return nil, err end
    if MANAGED[n] then return nil, n .. " diatur rejoin (heartbeat), pakai nama lain" end
    content = tostring(content or "")
    if content:match("^%s*$") then return nil, "isi script kosong" end
    if #content > MAX_SIZE then return nil, "script terlalu besar (maks 200 KB)" end
    local sd, derr = AutoExecute.scriptsDir()
    if not sd then return nil, derr end
    local path = sd .. "/" .. n
    local replaced = File.exists(path)
    local ok, werr = File.write(path, content)
    if not ok then return nil, "gagal menulis " .. path .. ": " .. tostring(werr) end
    local autoUpdated = false
    local ae = appDir()
    if ae and File.exists(ae .. "/" .. n) then
        autoUpdated = File.write(ae .. "/" .. n, content) and true or false
    end
    Logger.info("Scripts: saved " .. path)
    return n, replaced, autoUpdated
end

function AutoExecute.scriptRead(name)
    local n, err = cleanName(name)
    if not n then return nil, err end
    local sd = AutoExecute.scriptsDir()
    local c = sd and File.read(sd .. "/" .. n)
    if not c then return nil, "script " .. n .. " tidak ada di Scripts" end
    return c, n
end

-- Remove from Scripts only. Returns name, stillInAutoexecute(bool).
function AutoExecute.scriptRemove(name)
    local n, err = cleanName(name)
    if not n then return nil, err end
    local sd = AutoExecute.scriptsDir()
    local path = sd and (sd .. "/" .. n)
    if not path or not File.exists(path) then return nil, "script " .. n .. " tidak ada di Scripts" end
    if not os.remove(path) then return nil, "gagal menghapus " .. n end
    local ae = appDir()
    Logger.info("Scripts: removed " .. path)
    return n, ae and File.exists(ae .. "/" .. n) or false
end

-- Copy a script from Scripts into Autoexecute.
function AutoExecute.autoAdd(name)
    local n, err = cleanName(name)
    if not n then return nil, err end
    if MANAGED[n] then return nil, n .. " diatur rejoin" end
    local c, rerr = AutoExecute.scriptRead(n)
    if not c then return nil, rerr end
    local ae, aerr = appDir()
    if not ae then return nil, aerr end
    local ok, werr = File.write(ae .. "/" .. n, c)
    if not ok then return nil, "gagal menyalin ke Autoexecute: " .. tostring(werr) end
    Logger.info("AutoExecute: copied " .. n .. " from Scripts")
    return n
end

-- Remove a script's copy from Autoexecute (the one in Scripts stays).
function AutoExecute.autoRemove(name)
    local n, err = cleanName(name)
    if not n then return nil, err end
    if MANAGED[n] then return nil, n .. " diatur rejoin (matikan lewat setting heartbeat)" end
    local ae, aerr = appDir()
    if not ae then return nil, aerr end
    if not File.exists(ae .. "/" .. n) then return nil, n .. " tidak ada di Autoexecute" end
    if not os.remove(ae .. "/" .. n) then return nil, "gagal menghapus " .. n .. " dari Autoexecute" end
    Logger.info("AutoExecute: removed " .. n)
    return n
end

-- One-line loader for a script hosted at an https URL.
function AutoExecute.loaderFor(url)
    url = tostring(url or "")
    if not url:match("^https://[%w%.%-]+/") or url:find('["\\%c]') then return nil, "URL harus https:// yang valid" end
    return 'loadstring(game:HttpGet("' .. url .. '"))()'
end

return AutoExecute]]

__ya_sources["managers.boot"] = [=[
local Logger = require("core.logger")
local Shell = require("utils.shell")
local File = require("utils.file")
local Paths = require("core.paths")

-- Auto-boot (Termux:Boot) installer.
--
-- Writes ~/.termux/boot/start-rejoin.sh so the engine starts on every boot with
-- no Termux window: headless Launch All + Monitor, a crash-restart loop and a
-- rotating data/boot.log.
--
-- The loader installs itself: REJOIN_HOME (the shared data root) and
-- REJOIN_ENTRY (this engine file) are baked into the generated script, so it
-- keeps working even if the engine is started from a different folder. Works
-- for the single-file loader (yanamin.lua) and the multi-file engine
-- (main.lua) alike.

local Boot = {}

local SCRIPT_NAME = "start-rejoin.sh"
local BOOT_APP_PKG = "com.termux.boot"

local function quote(s)
    return "'" .. tostring(s or ""):gsub("'", "'\\''") .. "'"
end

local function splitPath(p)
    local dir, name = tostring(p or ""):match("^(.*[/\\])([^/\\]+)$")
    if dir then dir = dir:gsub("/+$", "") end
    return dir, name
end

function Boot.home()
    local home = os.getenv("HOME")
    if not home or home == "" then
        home = "/data/data/com.termux/files/usr"
    end
    return home
end

function Boot.bootDir()
    return Boot.home() .. "/.termux/boot"
end

function Boot.scriptPath()
    return Boot.bootDir() .. "/" .. SCRIPT_NAME
end

-- Absolute path of the file that is running right now.
function Boot.selfPath()
    local self = (arg and arg[0]) or ""
    if self == "" then return nil, "unknown_entry" end
    if not self:match("^[/\\]") then
        local pwd = os.getenv("PWD") or "."
        self = pwd .. "/" .. self
    end
    return self
end

-- data/ lives in the shared data root, so the boot log is easy to find.
function Boot.logPath()
    return Paths.data("boot.log")
end

function Boot.script(entryAbsPath)
    local dir, entry = splitPath(entryAbsPath)
    if not dir or not entry then return nil, "bad_entry_path" end
    return string.format([[#!/data/data/com.termux/files/usr/bin/sh
# Rejoin auto-start on device boot (Termux:Boot plugin).
#
# Generated by Rejoin (menu: Auto-boot -> Install). Safe to delete: use
# menu "Auto-boot" -> Uninstall, or just rm this file.
#
# Runs the engine headless in the background — equivalent to menu
# 1) Launch All + Monitor, but without a Termux window. Every step is logged
# to $REJOIN_HOME/data/boot.log (rotated past ~256 KB).
#
# REJOIN_HOME is the data root (config + data); REJOIN_ENTRY is the engine file
# that installed this script. BOOT_DELAY / RESTART_DELAY / MAX_RESTARTS can be
# overridden from the env.

REJOIN_HOME=%s
REJOIN_ENTRY=%s
BOOT_DELAY=${BOOT_DELAY:-30}
RESTART_DELAY=${RESTART_DELAY:-30}
MAX_RESTARTS=${MAX_RESTARTS:-5}

# The interpreter package may be called lua, lua5.3, lua5.4 or luajit, so never
# assume the bare name "lua" exists.
LUA_BIN=$(command -v lua5.3 2>/dev/null || command -v lua 2>/dev/null || command -v lua5.4 2>/dev/null || command -v luajit 2>/dev/null || echo lua)

BOOT_LOG="$REJOIN_HOME/data/boot.log"
mkdir -p "$REJOIN_HOME/data" 2>/dev/null
if [ -f "$BOOT_LOG" ] && [ "$(wc -c < "$BOOT_LOG" 2>/dev/null || echo 0)" -gt 262144 ]; then
    mv -f "$BOOT_LOG" "$BOOT_LOG.old" 2>/dev/null
fi
log() { echo "[$(date '+%%Y-%%m-%%d %%H:%%M:%%S')] $*" >> "$BOOT_LOG"; }

log "boot script started (home=$REJOIN_HOME entry=$REJOIN_ENTRY delay=${BOOT_DELAY}s)"

# Keep the CPU awake so Android does not suspend the engine after boot.
if command -v termux-wake-lock >/dev/null 2>&1; then
    termux-wake-lock </dev/null && log "wake lock taken"
fi

[ -f "$REJOIN_ENTRY" ] || { log "ERROR: $REJOIN_ENTRY not found"; exit 1; }
cd "$REJOIN_HOME" || { log "ERROR: cannot cd to $REJOIN_HOME"; exit 1; }
[ -f config/config.lua ] || log "WARN: config/config.lua missing"

sleep "$BOOT_DELAY"
if su -c id </dev/null >/dev/null 2>&1; then log "root ok"; else log "WARN: su -c id failed (root not granted yet?)"; fi

restarts=0
while :; do
    # REJOIN_WRAPPER=1 runs the engine directly: Termux:Boot hands us no
    # terminal, so the interactive terminal supervisor is not needed here.
    log "starting engine: $REJOIN_ENTRY --headless --start-monitor --auto-launch"
    REJOIN_WRAPPER=1 "$LUA_BIN" "$REJOIN_ENTRY" --headless --start-monitor --auto-launch </dev/null >/dev/null 2>>"$BOOT_LOG"
    code=$?
    case "$code" in
        0|130|143)
            log "engine stopped (exit $code)"
            exit "$code"
            ;;
    esac
    restarts=$((restarts + 1))
    if [ "$restarts" -gt "$MAX_RESTARTS" ]; then
        log "ERROR: engine still crashing after $MAX_RESTARTS restarts (exit $code); giving up"
        exit "$code"
    fi
    log "WARN: engine crashed (exit $code); restart $restarts/$MAX_RESTARTS in ${RESTART_DELAY}s"
    sleep "$RESTART_DELAY"
done
]], quote(Paths.base()), quote(entryAbsPath))
end

-- Write (or overwrite) the boot script. Returns ok, info-or-error.
function Boot.install()
    local self, err = Boot.selfPath()
    if not self then return false, err or "tidak tahu file engine yang sedang jalan" end
    if not File.exists(self) then
        return false, "file engine tidak ditemukan: " .. tostring(self)
    end
    local content, serr = Boot.script(self)
    if not content then return false, serr or "gagal membuat script boot" end
    local path = Boot.scriptPath()
    local ok, werr = File.write(path, content)
    if not ok then
        return false, "gagal menulis " .. path .. " (" .. tostring(werr) .. ")"
    end
    Shell.exec("chmod +x " .. quote(path))
    Logger.info("Boot: script boot ditulis: " .. path)
    return true, path
end

function Boot.uninstall()
    local path = Boot.scriptPath()
    if not File.exists(path) then return false, "script boot belum ada" end
    local ok, rerr = os.remove(path)
    if not ok then return false, "gagal hapus: " .. tostring(rerr) end
    Logger.info("Boot: script boot dihapus: " .. path)
    return true, path
end

-- Is the Termux:Boot Android app installed? It must come from the same source
-- as Termux itself, otherwise Android refuses to run it.
function Boot.appInstalled()
    local _, out = Shell.exec("pm list packages " .. BOOT_APP_PKG)
    if not out then return false end
    return out:find(BOOT_APP_PKG, 1, true) ~= nil
end

function Boot.status()
    local path = Boot.scriptPath()
    local log = Boot.logPath()
    return {
        installed = File.exists(path),
        path = path,
        app = Boot.appInstalled(),
        log = log,
        logExists = File.exists(log),
    }
end

-- Last few lines of data/boot.log, or nil when there is no log yet.
function Boot.tailLog(lines)
    local path = Boot.logPath()
    if not File.exists(path) then return nil, "no_log" end
    local ShellModule = Shell
    local _, out = ShellModule.exec("tail -n " .. tostring(lines or 10) .. " " .. quote(path))
    if not out or out == "" then return nil, "no_log" end
    return out
end

return Boot
]=]

__ya_sources["managers.cookie_injector"] = [[
local Paths = require("core.paths")
local Logger = require("core.logger")
local Shell = require("utils.shell")
local Timer = require("utils.timer")
local APK = require("managers.apk")
local Auth = require("managers.auth")

-- Injects a `.ROBLOSECURITY` token into a clone's WebView cookie DB (SQLite), so the
-- chosen account becomes logged in on that clone without going through the browser.
--
-- Target DB: <Auth.getBaseDir()>/app_webview/Default/Cookies. If the default path is
-- missing (modded/"Lite" clones keep it elsewhere) we search a few levels deep under
-- the same base directory.
--
-- sqlite3 note: the `su` shell resets PATH, so a Termux-installed sqlite3 is usually
-- NOT reachable as plain `sqlite3`. We resolve it explicitly (full Termux path +
-- LD_LIBRARY_PATH) and run every command through that resolved runner.
--
-- Safety: the app is force-stopped first (a running WebView holds the DB / may rewrite
-- it), the DB is backed up before writing, and every write is verified afterwards.
-- Login/other cookies are left untouched apart from the .ROBLOSECURITY row.

local CookieInjector = {}

-- Termux default prefix (PATH + lib dir for the dynamically-linked sqlite3).
local TERMUX_PREFIX = "/data/data/com.termux/files/usr"
local TERMUX_SQLITE = TERMUX_PREFIX .. "/bin/sqlite3"

-- Non-empty printable token (trimmed, no line breaks / control chars).
local function validToken(token)
    if not token or type(token) ~= "string" then return false end
    token = token:gsub("^%s+", ""):gsub("%s+$", "")
    if token == "" or #token > 2048 then return false end
    if token:find("[\n\r\0'\" ]") then return false end
    return true
end

local function quote(path)
    path = path:gsub("'", "'\\''")
    return "'" .. path .. "'"
end

-- Run a shell command (root, timeouts applied) and return its trimmed output, or nil
-- if the exec itself failed.
local function exec(cmd)
    local called, succeeded, out = pcall(function() return Shell.exec(cmd) end)
    if not called or not succeeded or not out then return nil end
    return out:gsub("\n+$", "")
end

local function existsFile(path)
    local out = exec(string.format("[ -f %s ] && echo AE_YES || echo AE_NO", quote(path)))
    if not out then return nil end
    return out:find("AE_YES", 1, true) ~= nil
end

-- WebKit/Chrome stores UTC timestamps as microseconds since 1601-01-01 (our era means
-- we must add the 1970-1601 offset to a unix epoch before scaling to µs).
local WEBKIT_EPOCH_OFFSET = 11644473600 -- seconds between 1601-01-01 and 1970-01-01

local function webkitNow()
    return tostring((os.time() + WEBKIT_EPOCH_OFFSET) * 1000000)
end

-- Resolve a runnable `curl` (Termux install preferred; the `su` shell has no PATH).
local function resolveCurl()
    local candidates = { TERMUX_PREFIX .. "/bin/curl", "/system/bin/curl", "curl" }
    for _, c in ipairs(candidates) do
        if c == "curl" then
            local sys = exec("[ -x /system/bin/curl ] && echo AE_YES || echo AE_NO")
            if sys and sys:find("AE_YES", 1, true) then return "curl" end
        else
            local out = exec(string.format("[ -x %s ] && echo AE_YES || echo AE_NO", quote(c)))
            if out and out:find("AE_YES", 1, true) then return c end
        end
    end
    return nil
end

-- Resolve a runnable `sqlite3` prefix for this device. The `su` shell does not inherit
-- the Termux PATH, and Shell's `timeout` wrapper would treat a leading `VAR=val` as an
-- argument to timeout (not the inner command), so we probe real candidate runners with
-- a `SELECT 1;` and return the first one that answers from the target DB.
local function resolveSqlite3(db)
    local runners = {}
    -- 1) Termux via `env` (env is a real /system/bin binary, so `timeout` can exec it).
    table.insert(runners, string.format(
        "env PATH=%s/bin:/system/bin:/system/xbin LD_LIBRARY_PATH=%s/lib %s",
        TERMUX_PREFIX, TERMUX_PREFIX, TERMUX_SQLITE
    ))
    -- 2) Termux absolute path (Termux binaries carry a baked-in RUNPATH).
    table.insert(runners, TERMUX_SQLITE)
    -- 3) A ROM that ships its own sqlite3 in the su PATH.
    local sys = exec("[ -x /system/bin/sqlite3 ] && echo AE_YES || echo AE_NO")
    if sys and sys:find("AE_YES", 1, true) then
        table.insert(runners, "sqlite3")
    end

    for _, runner in ipairs(runners) do
        local out = exec(string.format("%s %s \"SELECT 1;\"", runner, quote(db)))
        if out and out:gsub("%s+", "") == "1" then
            Logger.info("CookieInjector: using sqlite runner: " .. runner)
            return runner
        end
    end
    return nil
end

-- Every file named "Cookies" under base (covers app_webview/<profile>/... plus any
-- modded layout). Returns nil when the base dir is unreachable, an (possibly empty)
-- array otherwise. Sorted so the Default profile comes first (injected first).
local function locateCookieDbs(base)
    local out = exec(string.format("find %s -maxdepth 6 -type f -name Cookies 2>/dev/null", quote(base)))
    if not out then return nil end
    local dbs, seen = {}, {}
    for line in (out .. "\n"):gmatch("(.-)\n") do
        line = line:gsub("%s+$", "")
        if line ~= "" and existsFile(line) and not seen[line] then
            seen[line] = true
            dbs[#dbs + 1] = line
        end
    end
    table.sort(dbs)
    return dbs
end

-- Shared with Auth.isLoggedIn, which reads the live cookie rows instead of grepping.
CookieInjector.locateCookieDbs = locateCookieDbs
CookieInjector.resolveSqlite3 = resolveSqlite3

-- Row shape matching the row a real in-app WebView login writes (verified against the
-- working login row dumped from a logged-in clone: host_key keeps the leading dot,
-- expires_utc is WebKit-epoch microseconds far in the future, samesite=-1 is
-- UNSPECIFIED, source_scheme=2 is HttpsOrigin, top_frame_site_key stays empty so the
-- cookie is legacy/unpartitioned and matches any top frame).
local COLUMNS = {
    { col = "creation_utc",    lit = "0" },
    { col = "host_key",        lit = "'.roblox.com'" },
    { col = "name",            lit = "'.ROBLOSECURITY'" },
    { col = "value",           lit = nil }, -- filled with the escaped token
    { col = "path",            lit = "'/'" },
    { col = "expires_utc",     lit = "14380828598000000" }, -- ~year 2056 (WebKit µs)
    { col = "is_secure",       lit = "1" },
    { col = "is_httponly",     lit = "1" },
    { col = "last_access_utc", lit = "0" },
    { col = "priority",        lit = "1" },
    { col = "has_expires",     lit = "1" },
    { col = "is_persistent",   lit = "1" },
    { col = "samesite",        lit = "-1" }, -- UNSPECIFIED
    { col = "top_frame_site_key", lit = "''" }, -- legacy/unpartitioned => matches any top frame
    { col = "source_scheme",      lit = "2" },  -- HttpsOrigin
    { col = "source_port",        lit = "443" },
}

-- Parse `PRAGMA table_info(cookies);` output (lines like `0|host_key|TEXT|1||0`) into
-- { name = {type, notnull, dflt} }. Returns nil when nothing usable was produced.
local function pragmaColumns(out)
    if not out or out == "" then return nil end
    local cols, hasValue = {}, false
    for line in (out .. "\n"):gmatch("(.-)\n") do
        local name, typ, notnull, dflt = line:match("^%d+|([^|]+)|([^|]*)|([^|]*)|([^|]*)|([^|]*)$")
        if name then
            cols[name] = { type = typ or "", notnull = (notnull == "1"), dflt = dflt or "" }
            if name == "value" then hasValue = true end
        end
    end
    if not hasValue then return nil end
    return cols
end

-- Type-sized empty literal for an obligatory column that has no default.
local function emptyLiteral(typ)
    typ = (typ or ""):upper()
    if typ:find("TEXT") or typ:find("CHAR") or typ:find("CLOB") then return "''" end
    if typ:find("BLOB") then return "X''" end
    return "0"
end

-- Build (columns, values) for an INSERT that matches the DB's real schema: known
-- cookies columns get their explicit literal, any extra NOT NULL column without a
-- default gets a type-safe empty literal, the rest are omitted (SQLite uses its own
-- defaults). Falls back to the static COLUMNS list when the schema probe fails.
local function buildInsertSpec(runner, db, token, nowLit)
    local tokenLit = "'" .. token:gsub("'", "''") .. "'"

    local schema = pragmaColumns(exec(
        string.format("%s %s \"PRAGMA table_info(cookies);\"", runner, quote(db))
    ))
    if schema then
        local overrides = {}
        for _, c in ipairs(COLUMNS) do
            overrides[c.col] = (c.col == "value") and tokenLit or c.lit
        end
        -- Realistic creation/last-access timestamps (mirrors what a real login writes).
        overrides["creation_utc"] = nowLit
        overrides["last_access_utc"] = nowLit

        local cols, vals = {}, {}
        local needHost, needName, needPath = false, false, false
        for col, info in pairs(schema) do
            if overrides[col] then
                cols[#cols + 1] = col
                vals[#vals + 1] = overrides[col]
                if col == "host_key" then needHost = true end
                if col == "name" then needName = true end
                if col == "path" then needPath = true end
            elseif info.notnull and info.dflt == "" then
                cols[#cols + 1] = col
                vals[#vals + 1] = emptyLiteral(info.type)
            end
        end
        if needHost and needName and needPath and cols[1] then
            return cols, vals
        end
    end
    Logger.warn("CookieInjector: schema cookies tidak terbaca/valid untuk " .. tostring(db) .. ", pakai daftar kolom statis")

    -- Fallback: the full static list (all columns exist on modern Android WebView).
    local cols, vals = {}, {}
    for _, c in ipairs(COLUMNS) do
        if c.col == "creation_utc" or c.col == "last_access_utc" then
            cols[#cols + 1] = c.col
            vals[#vals + 1] = nowLit
        else
            cols[#cols + 1] = c.col
            vals[#vals + 1] = (c.col == "value") and tokenLit or c.lit
        end
    end
    return cols, vals
end

-- Verify a token is still accepted by Roblox before we write anything to the app.
-- Returns (ok, message). A missing curl or failed network request rejects injection.
function CookieInjector.verifyRemote(token)
    if not validToken(token) then return false, "Token tidak valid format" end
    local curlBin = resolveCurl()
    if not curlBin then
        return false, "curl tidak ditemukan (pkg install curl) - tidak bisa verifikasi token, inject dibatalkan"
    end

    -- Single curl call: body + HTTP code both on stdout (`-w '\n%{http_code}'`), so no
    -- temp file race (a previous version wrote `-o ...$$.json` then cat it from a NEW
    -- su shell, where `$$` is a different PID -> body always "empty").
    local out = exec(string.format(
        "%s -s -w '\n%%{http_code}' -H 'Cookie: .ROBLOSECURITY=%s' https://users.roblox.com/v1/users/authenticated",
        curlBin, token
    ))
    if not out then
        return false, "Verifikasi remote gagal (curl tidak menghasilkan output - cek jaringan)."
    end

    local body, codeStr = out:match("^(.-)\n(%d+)$")
    if not body then
        body, codeStr = out, out:match("(%d+)$")
    end
    local code = tonumber(codeStr)
    local snippet = (body or ""):gsub("%s+", " "):sub(1, 160)
    if snippet == "" then snippet = "(kosong)" end

    if code == 200 and body and body:find('"name"') and not body:find('"errors"') then
        Logger.info("CookieInjector: token VALID remote (code 200)")
        return true, "Token valid"
    end
    -- Fail closed: anything else is not a valid session. Show what Roblox actually
    -- answered (a dead/rotated token is exactly the silent-login-fail trap we hit).
    return false, string.format(
        "Token DITOLAK/tidak valid di sisi Roblox (HTTP %s). Kemungkinan sesi sudah mati/di-revoke keamanan Roblox. Export ulang dari Chrome lalu verifikasi: curl -s -H \"Cookie: .ROBLOSECURITY=<tok>\" https://users.roblox.com/v1/users/authenticated (harus balas {\"sub\":...,\"name\":...}). Body server: %s",
        tostring(codeStr == "" and "(tak terbaca)" or codeStr), snippet
    )
end

-- Inject `token` into `instance`'s cookie DB. Returns (ok, message).
function CookieInjector.inject(instance, token)
    if not validToken(token) then
        return false, "Token tidak valid (kosong / mengandung karakter control / >2048 char)"
    end

    -- 0) Fail fast when the session is already dead server-side (the silent-login-fail
    --    trap from before), BEFORE force-stopping the app or touching any data. Wrapped
    --    in pcall so any unexpected verify crash can never take down the whole CLI.
    local okRemote, msgRemote = false, "verifikasi remote gagal (error internal)"
    local okP, a, b = pcall(CookieInjector.verifyRemote, token)
    if okP then
        okRemote, msgRemote = a, b
    else
        Logger.warn("CookieInjector: verifyRemote error")
    end
    if not okRemote then
        Logger.warn("CookieInjector: inject batal - " .. msgRemote)
        return false, msgRemote
    end

    local pkg = instance and instance.package
    if not pkg then return false, "Instance tidak punya package" end
    local base = Auth.getBaseDir(instance)
    if not base then return false, "Tidak bisa tentukan base dir instance" end

    -- 1) Stop the app so the cookie DB is not held open / rewritten by WebView.
    local stopped, stopErr = APK.forceStop(pkg)
    if not stopped then return false, "clone tidak ditutup dengan aman: " .. tostring(stopErr) end
    Timer.sleep(1)

    -- 2) Enumerate EVERY Cookies DB under the base dir (a Lite/mod clone can keep its
    --    live WebView profile under a non-"Default" directory; writing only the first
    --    DB found would "succeed" but touch a store the app never reads).
    local dbs = locateCookieDbs(base)
    if dbs == nil then
        return false, "Base dir '" .. base .. "' tidak bisa dibaca (periksa izin root)."
    end
    if #dbs == 0 then
        return false, "Cookies DB tidak ditemukan di '" .. base .. "'. Kalau clone mod/Lite, set per-instance 'cookiePath' di config."
    end
    Logger.info("CookieInjector: target " .. #dbs .. " Cookies DB: " .. table.concat(dbs, ", "))

    -- 3) sqlite3 must be resolvable (same runner is used for every DB found).
    local runner = resolveSqlite3(dbs[1])
    if not runner then
        return false, "sqlite3 tidak terpasang / tidak dapat dijalankan. Install: pkg install sqlite (Termux)"
    end

    local stamp = os.date("%Y%m%d-%H%M%S")
    local nowLit = webkitNow()
    local written, failures = {}, {}
    for _, db in ipairs(dbs) do
        do
        -- 4) SQLite backup includes committed WAL transactions. Copying only the main
        -- DB or deleting sidecars can lose cookies that have not been checkpointed.
        local backup = db .. ".bak-" .. stamp
        local backupOut = exec(runner .. " " .. quote(db) .. " " .. quote(".backup " .. quote(backup)))
        if not backupOut or not existsFile(backup) then
            failures[#failures + 1] = db .. " - backup gagal; DB tidak diubah"
            Logger.warn("CookieInjector: backup gagal untuk " .. db)
            goto continue_db
        end
        Logger.info("CookieInjector: backup -> " .. backup)

        -- 5) Delete and insert in one transaction. On insert failure SQLite rolls back
        -- the delete, preserving the existing session cookie.
        local cols, vals = buildInsertSpec(runner, db, token, nowLit)
        Logger.info("CookieInjector: kolom yang diisi di " .. db .. " -> " .. table.concat(cols, ","))
        local sql = string.format(
            "BEGIN IMMEDIATE; DELETE FROM cookies WHERE name='.ROBLOSECURITY' AND host_key LIKE '%%.roblox.com%%'; INSERT OR REPLACE INTO cookies (%s) VALUES (%s); COMMIT;",
            table.concat(cols, ", "), table.concat(vals, ", ")
        )
        local insertOut = exec(runner .. " " .. quote(db) .. " '" .. sql:gsub("'", "'\\''") .. "'")
        if not insertOut then
            failures[#failures + 1] = db .. " - transaksi SQLite gagal (backup: " .. backup .. ")"
            Logger.warn("CookieInjector: transaksi gagal untuk " .. db)
            goto continue_db
        elseif insertOut ~= "" then
            -- SQLite error text can include the failed SQL and session token.
            Logger.warn("CookieInjector: sqlite3 returned output; inspecting stored row")
        else
            Logger.info("CookieInjector: sqlite3 output: (none)")
        end

        -- 6) Fold any WAL data into the main DB. `0|-1|-1` = connection opened the store
        -- outside WAL mode (no files to fold) -> no-op; `1|..` = busy -> one retry.
        local function checkpointIt()
            return exec(runner .. " " .. quote(db) .. " 'PRAGMA wal_checkpoint(FULL);'")
        end
        local walOut = checkpointIt()
        local busy, logFrames = (walOut or ""):match("^(.-)|(.-)|.-$")
        if busy == "1" then
            exec("sleep 0.2")
            walOut = checkpointIt()
            busy, logFrames = (walOut or ""):match("^(.-)|(.-)|.-$")
        end
        if walOut and walOut ~= "" then
            if logFrames == "-1" then
                Logger.info("CookieInjector: wal_checkpoint: " .. walOut .. " -> tidak ada WAL (no-op)")
            elseif busy == "1" then
                Logger.warn("CookieInjector: wal_checkpoint: " .. walOut .. " -> BUSY (WAL belum dilipat)")
            else
                Logger.info("CookieInjector: wal_checkpoint: " .. walOut .. " -> WAL dilipat ke DB utama")
            end
        end

        -- 7) Verify exactly one clean `.ROBLOSECURITY` row is stored AND that its value
        --    survived the shell-roundtrip intact (a truncated/mangled value still ends
        --    up non-empty, which the old `>0` check let through).
        local verify = exec(string.format(
            "%s %s \"SELECT length(value) || '|' || COUNT(*) FROM cookies WHERE name='.ROBLOSECURITY' AND host_key LIKE '%%.roblox.com%%' GROUP BY length(value);\"",
            runner, quote(db)
        ))
        if not verify then
            failures[#failures + 1] = db .. " - verifikasi tidak terbaca (backup: " .. backup .. ")"
        else
            local len, cnt = verify:match("^(%d+)|(%d+)%s*$")
            len = tonumber(len)
            cnt = tonumber(cnt)
            if len == nil or len == 0 or cnt ~= 1 then
                failures[#failures + 1] = db .. " - value tidak tersimpan / baris bukan 1 (verify: " .. tostring(verify) .. ", backup: " .. backup .. ")"
            elseif len ~= #token then
                failures[#failures + 1] = string.format(
                    "%s - INJECT TERPOTONG/RUSAK: tersimpan %d char, asal %d (verify: %s, backup: %s)",
                    db, len, #token, tostring(verify), backup
                )
            else
                written[#written + 1] = db
                Logger.info(string.format(
                    "CookieInjector: DB OK -> %s (len=%d, count=%d)",
                    db, len, cnt
                ))
            end
        end
        end
        ::continue_db::
    end
    Auth.resetCache()

    if #written == 0 then
        return false, "Tidak ada Cookies DB yang berhasil di-inject. Detail:\n- " .. table.concat(failures, "\n- ")
    end

    Logger.info(string.format(
        "CookieInjector: injected %d-char .ROBLOSECURITY into %s across %d Cookies DB",
        #token, pkg, #written
    ))
    local detail = string.format(
        "OK: cookie di-inject ke %s (%d char) di %d Cookies DB.\nDB: %s",
        pkg, #token, #written, table.concat(written, " | ")
    )
    if #failures > 0 then
        detail = detail .. "\n[WARN] Gagal sebagian:\n- " .. table.concat(failures, "\n- ")
    end
    return true, detail
end

-- Log a clone's Roblox account out on this device: stop the app, back up each Cookies
-- DB, then delete its `.ROBLOSECURITY` rows. The session is not revoked at Roblox, so
-- the same cookie can be injected again later. Only a logged-in clone is stopped (a
-- force-stopped empty clone makes the other clones FC). Returns (ok, message).
function CookieInjector.logout(instance)
    local pkg = instance and instance.package
    if not pkg then return false, "Instance tidak punya package" end
    local base = Auth.getBaseDir(instance)
    if not base then return false, "Tidak bisa tentukan base dir instance" end
    local dbs = locateCookieDbs(base)
    if dbs == nil then return false, "Base dir tidak bisa dibaca (periksa izin root)." end
    if #dbs == 0 then return false, "Cookies DB tidak ditemukan; clone belum pernah login." end
    local runner = resolveSqlite3(dbs[1])
    if not runner then return false, "sqlite3 tidak bisa dijalankan (pkg install sqlite)" end

    local rows = 0
    for _, db in ipairs(dbs) do
        local n = tonumber((exec(string.format(
            "%s %s \"SELECT COUNT(*) FROM cookies WHERE name='.ROBLOSECURITY' AND host_key LIKE '%%.roblox.com%%';\"",
            runner, quote(db))) or ""):match("^%s*(%d+)%s*$")) or 0
        rows = rows + n
    end
    if rows == 0 then
        if Auth.forget then Auth.forget(pkg) end
        return false, "Clone ini memang sudah logout."
    end

    -- Tell a running engine (another process when called from Menu 5) to drop its
    -- cached "logged in" answer, so it does not rejoin the clone it now sees closed.
    local sig = io.open(Paths.data("auth_forget.txt"), "a")
    if sig then sig:write(pkg, "\n"); sig:close() end
    local stopped, stopErr = APK.forceStop(pkg)
    if not stopped then return false, "clone tidak ditutup dengan aman; cookie tidak diubah: " .. tostring(stopErr) end
    Timer.sleep(1)
    local stamp = os.date("%Y%m%d-%H%M%S")
    local failures = {}
    for _, db in ipairs(dbs) do
        local backup = db .. ".bak-" .. stamp
        local backupOut = exec(runner .. " " .. quote(db) .. " " .. quote(".backup " .. quote(backup)))
        if not backupOut or not existsFile(backup) then
            failures[#failures + 1] = "backup gagal, DB tidak diubah"
        else
            local out = exec(runner .. " " .. quote(db) .. " \"DELETE FROM cookies WHERE name='.ROBLOSECURITY' AND host_key LIKE '%.roblox.com%'; PRAGMA wal_checkpoint(FULL);\"")
            if not out then failures[#failures + 1] = "hapus cookie gagal" end
        end
    end
    if Auth.forget then Auth.forget(pkg) end
    if #failures > 0 then
        Logger.warn("CookieInjector: logout " .. pkg .. " sebagian gagal: " .. table.concat(failures, "; "))
        return false, "Logout gagal sebagian: " .. table.concat(failures, "; ")
    end
    Logger.info("CookieInjector: logout " .. pkg .. " (" .. rows .. " cookie dihapus, backup ." .. "bak-" .. stamp .. ")")
    return true, "logout, app ditutup. Login lagi lewat app atau Inject Cookie."
end

-- Debug: dump every cookie row of EVERY Cookies DB under the instance. The
-- `.ROBLOSECURITY` value is shown as its length only (no token leak). Returns
-- (ok, message).
function CookieInjector.dump(instance)
    local pkg = instance and instance.package
    if not pkg then return false, "Instance tidak punya package" end
    local base = Auth.getBaseDir(instance)
    if not base then return false, "Tidak bisa tentukan base dir instance" end

    local dbs = locateCookieDbs(base)
    if dbs == nil then
        return false, "Base dir '" .. base .. "' tidak bisa dibaca (periksa izin root)."
    end
    if #dbs == 0 then
        return false, "Cookies DB tidak ditemukan di '" .. base .. "'. Kalau clone mod/Lite, set per-instance 'cookiePath' di config."
    end

    local runner = resolveSqlite3(dbs[1])
    if not runner then
        return false, "sqlite3 tidak terpasang / tidak dapat dijalankan. Install: pkg install sqlite (Termux)"
    end

    -- Column order from the real schema.
    local colOrder = {}
    local schemaOut = exec(string.format("%s %s \"PRAGMA table_info(cookies);\"", runner, quote(dbs[1])))
    for line in (schemaOut or ""):gmatch("(.-)\n") do
        local name = line:match("^%d+|([^|]+)")
        if name then colOrder[#colOrder + 1] = name end
    end
    if #colOrder == 0 then
        return false, "Tidak bisa baca schema cookies. Output: " .. tostring(schemaOut or "(none)")
    end

    local selectList = {}
    for _, c in ipairs(colOrder) do
        if c == "value" then
            selectList[#selectList + 1] = "length(value) AS value_len"
        else
            selectList[#selectList + 1] = c
        end
    end
    local sql = "SELECT " .. table.concat(selectList, ", ") .. " FROM cookies;"

    local parts = {}
    for _, db in ipairs(dbs) do
        local rowsOut = exec(string.format("%s %s \".mode line\" \"%s\"", runner, quote(db), sql))
        parts[#parts + 1] = "=== " .. db .. " ==="
        if not rowsOut or rowsOut == "" then
            parts[#parts + 1] = "(kosong / tanpa baris)"
        else
            parts[#parts + 1] = rowsOut
        end
    end
    Auth.resetCache()
    Logger.info("CookieInjector: dumped " .. tostring(instance and instance.package or "?") .. " cookie DBs:")
    return true, table.concat(parts, "\n")
end

-- List every Cookies DB under the instance (modded clones may keep a live profile
-- outside app_webview/Default). Returns nil (unreadable) or an array of paths.
function CookieInjector.listDbs(instance)
    local base = Auth.getBaseDir(instance)
    if not base then return nil end
    return locateCookieDbs(base)
end

-- Post-launch probe: READ-ONLY, no network. For every Cookies DB prints the injected
-- row's `len|valuePrefix|count` and whether the stored value still equals the injected
-- token. A DIFFERENT prefix is strong evidence the app's WebView already authenticated
-- (Roblox rotated the session -> login). A SAME prefix is INCONCLUSIVE: a successful
-- device may not rotate within 8s (proven on working device). Also greps the instance
-- data dir (excluding our `.bak-*` backup copies) for any OTHER file holding the token.
-- NOTE: never call this at the same time as a live verifyRemote against the same token
-- while the app is running -- two clients authenticating one session in a row is exactly
-- what triggers Roblox's session-hijack detection (instant logout).
function CookieInjector.probeToken(instance, token)
    local base = Auth.getBaseDir(instance)
    if not base then return "(base dir tidak terbaca)", "NEED_MANUAL_CHECK" end
    local lines = {}
    local dbs = locateCookieDbs(base)
    local tokPrefix = token and token:sub(1, 6) or ""
    local seenRotated, seenSame, seenMissing = false, false, false
    if dbs and #dbs > 0 then
        local runner = resolveSqlite3(dbs[1])
        for _, db in ipairs(dbs) do
            local status = "(sqlite runner tidak ada)"
            if runner then
                local v = exec(string.format(
                    "%s %s \"SELECT length(value) || '##' || substr(value,1,6) || '##' || COUNT(*) FROM cookies WHERE name='.ROBLOSECURITY' AND host_key LIKE '%%.roblox.com%%' GROUP BY length(value), substr(value,1,6);\"",
                    runner, quote(db)
                ))
                v = v and v:gsub("%s+$", "") or ""
                local lenPart, pfx, cntPart = v:match("^(%d+)##(.-)##(%d+)$")
                if lenPart and pfx and cntPart then
                    if pfx == tokPrefix then
                        seenSame = true
                        status = "len=" .. lenPart .. ", prefix=" .. pfx .. "=token, count=" .. cntPart .. " (SAMA dgn inject -> belum rotasi 8s; TIDAK KONKLUSIF - device yg berhasil bisa tanpa rotasi cepat)"
                    else
                        seenRotated = true
                        status = "len=" .. lenPart .. ", prefix=" .. pfx .. "!=token, count=" .. cntPart .. " (BERBEDA -> WebView SUDAH authenticate, Roblox rotasi = app LOGIN terkonfirmasi)"
                    end
                else
                    seenMissing = true
                    status = "tidak ada baris / " .. tostring(v == "" and "(kosong)" or v)
                end
            end
            lines[#lines + 1] = db .. " -> " .. status
        end
    elseif dbs then
        seenMissing = true
        lines[#lines + 1] = "(tidak ada Cookies DB)"
    else
        lines[#lines + 1] = "(base dir tidak bisa dibaca)"
    end

    -- Live store-open check: a PRIMED WebView creates `<db>-wal` the moment its network
    -- / cookie service actually opens the store (Chromium runs cookies in WAL). Absent
    -- post-launch = the app never touched this cookie store -> it can't be a login issue
    -- in the DB, it is happening before the store is even read.
    lines[#lines + 1] = "Live store (apakah WebView app benar-benar membuka cookie store):"
    local walAny, walNone = false, (dbs ~= nil and #dbs > 0)
    for _, db in ipairs(dbs or {}) do
        local walPath = db .. "-wal"
        if existsFile(walPath) then walAny = true; walNone = false end
        local walSize = existsFile(walPath) and exec("wc -c < " .. quote(walPath) .. " 2>/dev/null") or "0"
        walSize = tostring(walSize or "0"):gsub("%s+", "")
        local state = existsFile(walPath)
            and ("-wal ADA, size=" .. walSize .. " -> WebView MEMBUKA store (cookie dibaca app)")
            or "-wal TIDAK ADA -> WebView BELUM menyentuh cookie store"
        lines[#lines + 1] = "  " .. db .. " " .. state
    end

    local prefix = token and token:sub(1, 30) or ""
    if prefix ~= "" then
        local g = exec(string.format("grep -a -r -l -F %s %s 2>/dev/null | head -n 20", quote(prefix), quote(base)))
        local others = {}
        if g then
            for line in (g .. "\n"):gmatch("(.-)\n") do
                line = line:gsub("%s+$", "")
                if line ~= "" and not line:find(".bak-", 1, true) then
                    others[#others + 1] = line
                end
            end
        end
        if #others > 0 then
            lines[#lines + 1] = "File lain yang berisi token:"
            for _, l in ipairs(others) do
                lines[#lines + 1] = "  " .. l
            end
        else
            lines[#lines + 1] = "File lain berisi token: (tidak ada -> HANYA Cookies DB)"
        end
    end

    -- Verdict: any rotated row wins (auth proven). Otherwise the strongest status left.
    local verdict
    if seenRotated then
        verdict = "LOGIN_CONFIRMED -> rotasi terdeteksi = WebView SUDAH authenticate; akun HARUSNYA sudah masuk."
    elseif seenSame then
        verdict = "COOKIE_OK_NO_USE -> row utuh & belum rotasi 8s (TIDAK KONKLUSIF; device yg berhasil bisa login tanpa rotasi cepat). Cek: buka app & lihat avatar/username."
    elseif seenMissing then
        verdict = "COOKIE_CLEARED -> baris .ROBLOSECURITY hilang/absen dari DB (app menghapus cookie saat boot)."
    else
        verdict = "NEED_MANUAL_CHECK -> state tak terduga; tutup app lalu cek menu 5>3."
    end
    local info = { rotated = seenRotated, same = seenSame, missing = seenMissing,
        walAny = walAny, walNone = walNone, package = instance and instance.package }
    return table.concat(lines, "\n"), verdict, info
end

-- Country of the device's public IP (2-letter code) or nil. Plain curl as the Termux
-- user (no su, no token).
local function deviceCountry()
    local p = io.popen("curl -s -m 5 https://ipinfo.io/country </dev/null 2>/dev/null")
    if not p then return nil end
    local out = p:read("*a") or ""
    p:close()
    return out:match("^%s*(%u%u)%s*$")
end

-- Human-readable likely causes when the clone still shows the login screen after an
-- inject, from probeToken's info table. Empty when the login is already confirmed.
function CookieInjector.hints(info)
    if type(info) ~= "table" or info.rotated then return {} end
    local pkg = tostring(info.package or "<package>")
    local out = {}
    if info.walNone then
        out[#out + 1] = "- App Roblox belum/ga baca cookie WebView. Kemungkinan versi Roblox di clone ini beda"
        out[#out + 1] = "  (nyimpen login di tempat lain). Bandingin versi di device yang bisa vs yang gagal:"
        out[#out + 1] = "  su -c \"dumpsys package " .. pkg .. " | grep versionName\""
        out[#out + 1] = "  Solusi: login manual sekali di clone ini."
    end
    if info.missing then
        out[#out + 1] = "- Cookie dihapus app pas kebuka = Roblox nolak sesinya. Kemungkinan besar proteksi"
        out[#out + 1] = "  lokasi / sesi dianggap dibajak. Tutup app, lalu cek token di menu 5 > 3: 401 = di-revoke."
    elseif info.same and info.walAny then
        out[#out + 1] = "- Cookie udah dibaca app. Kalau di layar tetep logout, kemungkinan besar proteksi lokasi"
        out[#out + 1] = "  Roblox (cookie diambil dari negara/jaringan lain dari device ini)."
    end
    if #out == 0 then
        out[#out + 1] = "- Status ga jelas. Tutup app, lalu cek token di menu 5 > 3 (401 = di-revoke Roblox)."
    end
    local country = deviceCountry()
    if country then out[#out + 1] = "- IP device ini: " .. country end
    out[#out + 1] = "- Tips: ambil cookie dari login di negara/jaringan yang sama kayak device ini, atau login"
    out[#out + 1] = "  manual. 1 cookie jangan dipake di banyak device/negara."
    return out
end

-- Schema/version diagnostic for one Cookies DB (used by `--doctor` to compare two devices).
function CookieInjector.dbInfo(db)
    local runner = resolveSqlite3(db)
    if not runner then return "sqlite runner tidak ada" end
    local ver = exec(runner .. " " .. quote(db) .. " 'PRAGMA user_version;'")
    local jmode = exec(runner .. " " .. quote(db) .. " 'PRAGMA journal_mode;'")
    local walSize = "0"
    if existsFile(db .. "-wal") then walSize = exec("wc -c < '" .. (db:gsub("'", "'\\''")) .. "-wal' 2>/dev/null") end
    local cols = {}
    local schemaOut = exec(string.format("%s %s \"PRAGMA table_info(cookies);\"", runner, quote(db)))
    for l in (schemaOut or ""):gmatch("(.-)\n") do
        local name, typ = l:match("^%d+|([^|]+)|([^|]*)")
        if name then cols[#cols + 1] = name .. ":" .. typ end
    end
    return string.format("user_version=%s | journal_mode=%s | wal_size=%s | cols=%d [%s]", tostring(ver or "?"), tostring(jmode or "?"), tostring(walSize or "0"), #cols, table.concat(cols, ","))
end

return CookieInjector
]]

__ya_sources["managers.delta_key"] = [[
local Paths = require("core.paths")
local Logger = require("core.logger")
local Config = require("core.config")
local File = require("utils.file")
local Shell = require("utils.shell")

-- Is Delta's key still there?
--
-- Delta keeps its key in an entry named like "license" inside its folder (the parent
-- of appAutoExecutePath, e.g. /sdcard/Delta). When the key runs out the entry is gone
-- and every clone shows the key screen again. The folder is shared by all clones, so
-- this is one status for the whole device.
--
-- Config (optional): deltaLicensePath = "" -- "" = find it automatically.
-- The path found once is remembered in data/delta_license_path.txt, so a key that is
-- already gone when the engine starts (e.g. after a reboot) is still noticed.

local DeltaKey = {}

local REMEMBER = Paths.data("delta_license_path.txt")
local DEFAULT_LICENSE = "/sdcard/delta/internal/cache/license"
local cached = nil
local warnedMissing = false

local function q(s) return "'" .. tostring(s):gsub("'", "'\\''") .. "'" end

local function deltaDir()
    local ok, c = pcall(Config.get)
    c = ok and type(c) == "table" and c or {}
    local ae = type(c.appAutoExecutePath) == "string" and c.appAutoExecutePath:gsub("/+$", "") or ""
    if ae == "" then return nil, c end
    return (ae:match("^(.*)/[^/]+$") or ae), c
end

-- Path of the license entry, or nil when it was never seen.
function DeltaKey.path()
    local dir, c = deltaDir()
    local forced = type(c.deltaLicensePath) == "string" and c.deltaLicensePath:gsub("%s+$", "") or ""
    if forced ~= "" then return forced end
    if cached then return cached end
    local remembered = (File.read(REMEMBER) or ""):gsub("%s+$", "")
    if remembered ~= "" then
        cached = remembered
        return cached
    end
    if dir then
        local ok, out = Shell.exec("ls -a " .. q(dir) .. " 2>/dev/null")
        for name in tostring(ok and out or ""):gmatch("[^\r\n]+") do
            if name:lower():find("license", 1, true) then
                cached = dir .. "/" .. name
                if File.read(REMEMBER) ~= cached then
                    File.write(REMEMBER, cached)
                    Logger.info("[KEY] file license Delta: " .. cached)
                end
                return cached
            end
        end
    end
    if not warnedMissing then
        warnedMissing = true
        Logger.info("[KEY] file license Delta belum ditemukan di " .. tostring(dir) .. " (cek key dilewati)")
    end
    return nil
end

-- true = key there (non-empty file, or folder with something in it), false = gone or
-- empty, nil = unknown (no path known / Delta folder unreadable).
function DeltaKey.present()
    local dir = deltaDir()
    local p = DeltaKey.path()
    if not p then return nil end
    local cmd = "if [ -d " .. q(p) .. " ]; then [ -n \"$(ls -A " .. q(p) .. " 2>/dev/null)\" ] && echo KEY_YES || echo KEY_NO; "
        .. "elif [ -s " .. q(p) .. " ]; then echo KEY_YES; "
        .. "elif [ -d " .. q(dir or "/") .. " ]; then echo KEY_NO; else echo KEY_UNKNOWN; fi"
    -- Shell.exec prefixes a timeout, so a compound command needs its own sh -c.
    local ok, out = Shell.exec("sh -c " .. q(cmd))
    out = ok and out or ""
    if out:find("KEY_YES", 1, true) then return true end
    if out:find("KEY_NO", 1, true) then return false end
    return nil
end

-- Store a user-supplied Delta key in Delta's own license entry. This only accepts
-- manual input; it never obtains, derives, or validates a key. Keep the key out of
-- logs and config, and write it directly so it is not exposed in a shell command.
function DeltaKey.input(key)
    if type(key) ~= "string" then return false, "key tidak valid" end
    key = key:gsub("^%s+", ""):gsub("%s+$", "")
    if #key < 1 or #key > 256 or key:find("[%c%s]") then
        return false, "format key tidak valid (1–256 karakter tanpa spasi)"
    end

    local okConfig, c = pcall(Config.get)
    c = okConfig and type(c) == "table" and c or {}
    local configured = type(c.deltaLicensePath) == "string" and c.deltaLicensePath:gsub("%s+$", "") or ""
    local path = configured ~= "" and configured or DEFAULT_LICENSE
    local dir = path:match("^(.*)/[^/]+$")
    if not dir or dir == "" or path:find("[%c]") then return false, "path license Delta tidak valid" end
    -- Create the shared-storage folder as Termux, so the following Lua file write
    -- keeps the same owner instead of leaving a root-owned cache directory.
    local made = os.execute("mkdir -p " .. q(dir) .. " 2>/dev/null")
    if made ~= true and made ~= 0 then return false, "folder cache Delta tidak bisa dibuat" end

    local f = io.open(path, "w")
    if not f then return false, "file license Delta tidak bisa ditulis" end
    local wrote = f:write(key)
    local flushed = f:flush()
    local closed = f:close()
    if not wrote or not flushed or not closed then return false, "gagal menyimpan key ke file license Delta" end

    local saved = File.read(path)
    if saved ~= key then return false, "verifikasi file license Delta gagal" end
    cached = path
    File.write(REMEMBER, path .. "\n")
    Logger.info("[KEY] input key Delta tersimpan di file license")
    return true, "key Delta tersimpan; buka ulang Delta bila layar key belum berubah"
end

return DeltaKey
]]

__ya_sources["managers.doctor"] = [[
-- Environment doctor: emit a compare-friendly KEY=value report of everything that can
-- differ BETWEEN devices and cause "inject [OK] tapi app ga login" on one device but
-- not the other (root, Android/WebView version, clone APK version+hash, Cookies DB
-- layout/schema, curl/sqlite3 availability). Run `lua main.lua --doctor` on EACH device
-- and diff the two outputs -- the mismatch line is the dependency/fingerprint culprit.

local Logger = require("core.logger")
local Shell = require("utils.shell")
local Config = require("core.config")
local InstanceManager = require("managers.instance")

local TERMUX_PREFIX = "/data/data/com.termux/files/usr"

local Doctor = {}

local function join(k, v)
    if v == nil then v = "(tidak ada)" end
    v = tostring(v):gsub("[\r\n]+", "\\n")
    return tostring(k) .. "=" .. v
end

local function outOf(cmd)
    local ok, out = Shell.exec(cmd)
    if not ok or not out then return nil end
    out = out:gsub("\n+$", "")
    if out:gsub("%s+", "") == "" then return nil end
    return out
end

local function oneOf(stmts)
    for _, c in ipairs(stmts) do
        local v = outOf(c)
        if v and v ~= "" then return v end
    end
    return nil
end

local function hashApk(pkg)
    local p = outOf("pm path " .. pkg .. " 2>/dev/null | head -n1")
    if not p then return nil end
    local apk = p:match("^package:(.+)$")
    if not apk or apk == "" then return nil end
    return outOf("sha1sum '" .. apk:gsub("'", "'\\''") .. "' 2>/dev/null | cut -d' ' -f1")
end

function Doctor.gather()
    local rows = {}
    local function add(k, v) rows[#rows + 1] = join(k, v) end

    add("LUA_VERSION", _VERSION)
    -- `command -v` is BROKEN under Shell.exec: toybox `timeout` execs the first word as a
    -- real binary, but `command` is a shell builtin -> "exec command: No such file".
    -- Use `ls <absolute path>` instead (real binary, safe under timeout).
    add("LUA_BIN", outOf("ls " .. TERMUX_PREFIX .. "/bin/lua 2>/dev/null"))
    add("CURL_BIN", outOf("ls " .. TERMUX_PREFIX .. "/bin/curl 2>/dev/null"))
    add("SQLITE_BIN", outOf("ls " .. TERMUX_PREFIX .. "/bin/sqlite3 2>/dev/null"))

    add("ROOT_UID", outOf("id -u"))
    add("SELINUX", outOf("getenforce"))
    add("ANDROID_SDK", outOf("getprop ro.build.version.sdk"))
    add("ANDROID_RELEASE", outOf("getprop ro.build.version.release"))
    add("MODEL", oneOf({ "getprop ro.product.model", "getprop ro.product.device" }))
    add("BUILD_FINGERPRINT", outOf("getprop ro.build.fingerprint"))

    -- Device-attestation state visible to Roblox (Play Integrity / SafetyNet input).
    add("FLASH_LOCKED", outOf("getprop ro.boot.flash.locked"))
    add("VERIFIED_BOOTSTATE", outOf("getprop ro.boot.verifiedbootstate"))
    add("VBMETA_DEVICE_STATE", outOf("getprop ro.boot.vbmeta.device_state"))
    add("SECURITY_PATCH", outOf("getprop ro.build.version.security_patch"))

    add("WEBVIEW_GOOGLE", oneOf({
        "dumpsys package com.google.android.webview | grep -m1 versionName",
        "cmd package dump com.google.android.webview | grep -m1 versionName",
        "pm path com.google.android.webview",
    }))
    add("WEBVIEW_AOSP", oneOf({
        "dumpsys package com.android.webview | grep -m1 versionName",
        "cmd package dump com.android.webview | grep -m1 versionName",
    }))
    add("PLAY_SERVICES", oneOf({
        "dumpsys package com.google.android.gms | grep -m1 versionName",
        "cmd package dump com.google.android.gms | grep -m1 versionName",
    }))

    -- Actual WebView provider loaded by the runtime (device can differ despite the
    -- same android.webview versionName; a mis-selected provider = different store behavior).
    add("WEBVIEW_PROVIDER", oneOf({
        "cmd webviewupdate get-current-webview-package 2>/dev/null",
        "settings get global webview_provider",
        "dumpsys webviewupdate | grep -i -m1 'current webview'",
    }))

    -- Root hiding state: if Magisk deny-list is inactive on one device, GMS Play
    -- Integrity fails there -> Roblox may reject/revoke logins for that device only.
    add("MAGISK", oneOf({
        "magisk -V 2>/dev/null",
        "/data/adb/magisk/magisk -V 2>/dev/null",
        "ls /data/adb/magisk 2>/dev/null | head -1",
    }))

    -- Network identity seen by Roblox (IP/ASN/geo). Same token on two different
    -- networks can authenticate on one and get flagged on the other.
    add("NETWORK_IP", outOf("env PATH=" .. TERMUX_PREFIX .. "/bin:/system/bin LD_LIBRARY_PATH=" .. TERMUX_PREFIX .. "/lib " .. TERMUX_PREFIX .. "/bin/curl -s -m 6 https://ipinfo.io/json 2>/dev/null | head -c 220"))

    local instances = InstanceManager.getAll() or {}
    add("INSTANCE_COUNT", #instances)
    local CookieInjector = require("managers.cookie_injector")
    for i, inst in ipairs(instances) do
        local pkg = inst and inst.package or ""
        local tag = string.format("INST%d", i)
        add(tag .. "_PKG", pkg)
        add(tag .. "_VER", oneOf({
            "dumpsys package " .. pkg .. " | grep -m1 versionName",
            "cmd package dump " .. pkg .. " | grep -m1 versionName",
        }))
        add(tag .. "_CODE", oneOf({
            "dumpsys package " .. pkg .. " | grep -m1 versionCode",
            "cmd package dump " .. pkg .. " | grep -m1 versionCode",
        }))
        add(tag .. "_SHA1", hashApk(pkg))
        add(tag .. "_INSTALLED", oneOf({
            "dumpsys package " .. pkg .. " | grep -m1 firstInstallTime",
            "cmd package dump " .. pkg .. " | grep -m1 firstInstallTime",
        }))

        local dbs = CookieInjector.listDbs(inst)
        if dbs then
            add(tag .. "_COOKIE_DBS", #dbs)
            for j, db in ipairs(dbs) do
                add(tag .. "_DB" .. j, db)
                add(tag .. "_DB" .. j .. "_SIZE", outOf("wc -c < '" .. (db:gsub("'", "'\\''")) .. "' 2>/dev/null"))
                add(tag .. "_DB" .. j .. "_INFO", CookieInjector.dbInfo(db))
            end
        else
            add(tag .. "_COOKIE_DBS", "none/reject")
        end
    end
    return table.concat(rows, "\n")
end

function Doctor.run()
    local report = Doctor.gather()
    Logger.info("DOCTOR REPORT begin")
    for line in (report .. "\n"):gmatch("(.-)\n") do
        if line ~= "" then Logger.info("DOCTOR| " .. line) end
    end
    Logger.info("DOCTOR REPORT end")
    return report
end

return Doctor]]

__ya_sources["managers.heartbeat"] = [=[
local Logger = require("core.logger")
local Config = require("core.config")
local File = require("utils.file")
local Shell = require("utils.shell")

-- In-game status from inside Roblox.
--
-- rejoin installs scripts/rejoin_heartbeat.lua into the executor's autoexecute folder
-- (appAutoExecutePath). Inside the game that script writes
--   <workspace>/rejoin/hb_<username>.txt
-- every `interval` seconds: state (ingame / kicked), fps, ping, memory, time.
-- The workspace folder is found next to the autoexecute folder (Workspace/workspace)
-- unless heartbeat.workspacePath is set.
--
-- Only a heartbeat written AFTER the clone's latest launch counts, so an old file
-- (e.g. the "kicked" one from before a relaunch) never triggers anything.
--
-- Config (all optional):
--   heartbeat = {
--       enabled = true,      -- install the script and use its status
--       interval = 10,       -- seconds between writes inside the game
--       staleAfter = 90,     -- seconds without a write before the game counts as gone
--       workspacePath = "",  -- "" = auto
--       saver = { enabled = false, disable3d = true, fpsCap = 15,
--                 lowGraphics = true, mute = true },
--   }

local Heartbeat = {}

local SCRIPT_NAME = "rejoin_heartbeat.lua"
local MARKER = "REJOIN_HEARTBEAT"
local FOLDER = "rejoin"

local launchedAt = {} -- pkg -> os.time() of the latest launch
-- Files older than this engine run never count (e.g. yesterday's stale heartbeat).
local startedAt = os.time()
local wsCache = nil
local readCache = {} -- pkg -> { at, hb } ; the monitor asks several times per cycle
local expected = {} -- pkg -> session request written before opening the app
local serial = 0
local readFile

function Heartbeat.identity(instance)
    local Username = require("managers.username")
    local name = Username.get(instance)
    if type(name) ~= "string" or not name:match("^[%w_]+$") then
        return nil, "username belum teridentifikasi"
    end
    local conf = Config.get() or {}
    for _, other in pairs(conf.instances or {}) do
        if type(other) == "table" and other.package ~= instance.package then
            local otherName = Username.get(other)
            if type(otherName) == "string" and otherName:lower() == name:lower() then
                return nil, "username dipakai dua clone; periksa mapping akun"
            end
        end
    end
    return name:lower()
end

local function fields(content)
    local out = {}
    for line in tostring(content or ""):gmatch("[^\r\n]+") do
        local k, v = line:match("^(%w+)=(.*)$")
        if k then out[k] = v end
    end
    return out
end

local function quote(s) return "'" .. tostring(s):gsub("'", "'\\''") .. "'" end

local function conf()
    local ok, c = pcall(Config.get)
    c = ok and type(c) == "table" and c or {}
    local hb = type(c.heartbeat) == "table" and c.heartbeat or {}
    local sv = type(hb.saver) == "table" and hb.saver or {}
    return {
        enabled = hb.enabled ~= false,
        interval = math.max(3, math.floor(tonumber(hb.interval) or 10)),
        staleAfter = math.max(20, math.floor(tonumber(hb.staleAfter) or 90)),
        workspacePath = type(hb.workspacePath) == "string" and hb.workspacePath or "",
        saver = {
            enabled = sv.enabled == true,
            disable3d = sv.disable3d ~= false,
            fpsCap = math.max(0, math.floor(tonumber(sv.fpsCap) or 15)),
            lowGraphics = sv.lowGraphics ~= false,
            mute = sv.mute ~= false,
        },
    }, c
end

function Heartbeat.isEnabled() return conf().enabled end
function Heartbeat.saverEnabled()
    local c = conf()
    return c.enabled and c.saver.enabled
end

local function autoexecDir()
    local _, c = conf()
    local dir = c.appAutoExecutePath
    if type(dir) ~= "string" or dir == "" then return nil end
    return (dir:gsub("/+$", ""))
end

local function dirExists(path)
    local ok, out = Shell.exec("[ -d '" .. path:gsub("'", "'\\''") .. "' ] && echo AE_YES || echo AE_NO")
    return ok and out and out:find("AE_YES", 1, true) ~= nil
end

-- The executor's workspace folder (where writefile() lands).
function Heartbeat.workspaceDir()
    local c = conf()
    if c.workspacePath ~= "" then return (c.workspacePath:gsub("/+$", "")) end
    if wsCache then return wsCache end
    local ae = autoexecDir()
    if not ae then return nil end
    local parent = ae:match("^(.*)/[^/]+$") or ae
    for _, name in ipairs({ "Workspace", "workspace" }) do
        local p = parent .. "/" .. name
        if dirExists(p) then
            wsCache = p
            return p
        end
    end
    return parent .. "/Workspace"
end

local function scriptSource()
    local here = (debug.getinfo(1, "S").source or ""):match("^@(.*)/managers/[^/]+$") or "."
    if type(__ya_source) == "function" then
        local embedded = __ya_source("scripts.rejoin_heartbeat")
        if embedded then return embedded end
    end
    return File.read(here .. "/scripts/rejoin_heartbeat.lua") or File.read("scripts/rejoin_heartbeat.lua")
end

local function luaValue(v)
    if type(v) == "boolean" or type(v) == "number" then return tostring(v) end
    return string.format("%q", tostring(v))
end

-- Install (or refresh) the script in the autoexecute folder; remove it when disabled.
-- Returns ok, message.
function Heartbeat.install()
    local c = conf()
    local dir = autoexecDir()
    if not dir then return false, "appAutoExecutePath kosong" end
    local target = dir .. "/" .. SCRIPT_NAME

    if not c.enabled then
        local existing = File.read(target)
        if existing and existing:find(MARKER, 1, true) then
            os.remove(target)
            Logger.info("Heartbeat: script dilepas dari " .. target)
        end
        return true, "disabled"
    end

    local src = scriptSource()
    if not src then return false, "scripts/rejoin_heartbeat.lua tidak ditemukan" end
    local cfg = string.format(
        "{\n    interval = %d,\n    folder = %s,\n    saver = %s,\n    disable3d = %s,\n"
        .. "    fpsCap = %d,\n    lowGraphics = %s,\n    mute = %s,\n}",
        c.interval, luaValue(FOLDER), luaValue(c.saver.enabled), luaValue(c.saver.disable3d),
        c.saver.fpsCap, luaValue(c.saver.lowGraphics), luaValue(c.saver.mute))
    local s, e = src:find("--[[REJOIN_CFG]]", 1, true)
    local s2, e2 = src:find("--[[/REJOIN_CFG]]", 1, true)
    if not s or not s2 then return false, "template rusak" end
    local out = src:sub(1, e) .. cfg .. src:sub(s2)

    if File.read(target) == out then return true, "up to date" end
    local ok, err = File.write(target, out)
    if not ok then
        Logger.warn("Heartbeat: gagal menulis " .. target .. ": " .. tostring(err))
        return false, tostring(err)
    end
    Logger.info("Heartbeat: script terpasang di " .. target .. (c.saver.enabled and " (mode hemat)" or ""))
    return true, target
end

-- os.time() of this clone's latest launch by this engine, or nil.
function Heartbeat.launchedAt(instance)
    return instance and instance.package and launchedAt[instance.package] or nil
end

function Heartbeat.markLaunched(instance)
    local pkg = instance and instance.package
    if pkg then
        launchedAt[pkg] = os.time()
        readCache[pkg] = nil
        if not Heartbeat.isEnabled() then return true end
        local name, err = Heartbeat.identity(instance)
        if not name then return false, err end
        local ws = Heartbeat.workspaceDir()
        if not ws then return false, "folder Workspace belum ditemukan" end
        serial = serial + 1
        local random = io.open("/dev/urandom", "rb")
        local bytes = random and random:read(8) or nil
        if random then random:close() end
        local suffix = bytes and bytes:gsub(".", function(b) return string.format("%02x", b:byte()) end)
            or string.format("%d_%d", math.random(100000, 999999), math.floor(os.clock() * 1000000))
        local token = string.format("%d_%s_%d", os.time(), suffix, serial)
        local request = { name = name, package = pkg, session = token, started = os.time() }
        local dir = ws .. "/" .. FOLDER
        local path = dir .. "/start_" .. name .. ".txt"
        local content = string.format("name=%s\npackage=%s\nsession=%s\nstarted=%d\n", name, pkg, token, request.started)
        local ok = File.write(path, content)
        if not ok then
            ok = Shell.exec("sh -c " .. quote("mkdir -p " .. quote(dir) .. " && printf %s " .. quote(content) .. " > " .. quote(path)))
        end
        if not ok then return false, "gagal menulis penanda sesi heartbeat" end
        expected[pkg] = request
        return true
    end
    return false, "package kosong"
end

readFile = function(path)
    local content = File.read(path)
    if content then return content end
    -- Files written by the app may not be readable by Termux directly.
    local ok, out = Shell.exec("cat '" .. path:gsub("'", "'\\''") .. "' 2>/dev/null")
    if ok and out and out ~= "" and out ~= "(dry-run)" then return out end
    return nil
end

-- Latest heartbeat for this clone, or nil. Fields: state, fps, ping, mem, time,
-- fresh (written within staleAfter), current (written after the latest launch).
function Heartbeat.read(instance)
    local c = conf()
    if not c.enabled or not instance or not instance.package then return nil end
    local cached = readCache[instance.package]
    if cached and os.time() - cached.at < 2 then return cached.hb end
    local hb = Heartbeat.readNow(instance, c)
    readCache[instance.package] = { at = os.time(), hb = hb }
    return hb
end

function Heartbeat.readNow(instance, c)
    c = c or conf()
    local name = Heartbeat.identity(instance)
    if not name or name == "" then return nil end
    local ws = Heartbeat.workspaceDir()
    if not ws then return nil end
    local content = readFile(ws .. "/" .. FOLDER .. "/hb_" .. name:lower() .. ".txt")
    if not content then return nil end

    local hb = fields(content)
    hb.time = tonumber(hb.time)
    if not hb.time or tostring(hb.name):lower() ~= name then return nil end
    if type(hb.session) ~= "string" or not hb.session:match("^[%w_%-]+$") then return nil end
    hb.seq = tonumber(hb.seq)
    if not hb.seq or hb.seq < 1 then return nil end
    hb.fps, hb.ping, hb.mem = tonumber(hb.fps), tonumber(hb.ping), tonumber(hb.mem)
    local now = os.time()
    hb.age = now - hb.time
    if hb.age < -5 then return nil end
    hb.fresh = hb.age >= -5 and hb.age <= c.staleAfter
    local since = launchedAt[instance.package] or startedAt
    local request = expected[instance.package]
    if not request then
        local saved = fields(readFile(ws .. "/" .. FOLDER .. "/start_" .. name .. ".txt"))
        if saved.package == instance.package and saved.name == name and saved.session then
            request = saved
            expected[instance.package] = saved
        end
    end
    -- Manual app starts can report a self-generated session; an engine launch must
    -- echo its exact request. A previous run cannot satisfy a new launch in the same second.
    local matches = request and hb.session == request.session and hb.package == instance.package
        or (not request and not launchedAt[instance.package] and (hb.package == "" or hb.package == instance.package))
    hb.current = matches and hb.time >= since
    return hb
end

-- Is the game up, judged from inside it?
--   true  = fresh heartbeat from this session, in game
--   false = kicked/disconnected, or this session's heartbeat stopped
--   nil   = no heartbeat from this session yet: caller decides another way
function Heartbeat.alive(instance)
    local ok, hb = pcall(Heartbeat.read, instance)
    if not ok or not hb or not hb.current then return nil end
    if hb.state == "kicked" then
        if hb.fresh then return false, "kicked: " .. tostring(hb.reason or "") end
        return nil
    end
    if hb.fresh then
        if hb.state == "ingame" then return true end
        return nil -- a loading report is progress, never proof that the game is ready
    end
    if hb.state == "ingame" then return false, string.format("heartbeat berhenti %ds", hb.age) end
    return nil
end

-- Short dashboard suffix like "12fps 380MB", or nil.
function Heartbeat.summary(instance)
    local ok, hb = pcall(Heartbeat.read, instance)
    if not ok or not hb or not hb.fresh or not hb.current or hb.state ~= "ingame" then return nil end
    local parts = {}
    if hb.fps then parts[#parts + 1] = hb.fps .. "fps" end
    if hb.mem and hb.mem > 0 then parts[#parts + 1] = hb.mem .. "MB" end
    if #parts == 0 then return nil end
    return table.concat(parts, " ")
end

-- RSS is diagnostic only. A live process without HB is unknown, not unhealthy.
function Heartbeat.isUp(instance, apk)
    local alive = Heartbeat.alive(instance)
    if alive ~= nil then return alive end
    local pkg = instance and instance.package
    if not pkg then return false end
    apk = apk or require("managers.apk")
    local ok, res = pcall(apk.isRunning, pkg)
    if ok and res == false then return false end
    if not Heartbeat.isEnabled() and ok then return res end
    return nil
end

return Heartbeat
]=]

__ya_sources["managers.instance"] = [[
local InstanceManager = {}

local instances = {}

-- Load instances from provided config table.
-- Iterates with pairs() (not ipairs) and normalizes both integer and string keys, so
-- instances survive a reload even if a previous save wrote string keys like "1".
function InstanceManager.load(config)
    instances = {}
    if config and type(config.instances) == "table" then
        -- The saved config writes explicit keys ([1] = ..), which Lua keeps in the hash
        -- part, so pairs() order is arbitrary: sort by key to keep the Menu 2 order
        -- (launch order and window slots depend on it).
        local keys = {}
        for k in pairs(config.instances) do keys[#keys + 1] = k end
        table.sort(keys, function(a, b)
            local na, nb = tonumber(a), tonumber(b)
            if na and nb then return na < nb end
            if na then return true end
            if nb then return false end
            return tostring(a) < tostring(b)
        end)
        local seen = {}
        for _, k in ipairs(keys) do
            local v = config.instances[k]
            -- key may be an integer (1) or a string ("1"); v is the instance table
            if type(v) == "table" and not seen[v] then
                seen[v] = true
                table.insert(instances, v)
            end
        end
    end
end

-- Which game a clone joins:
--   inst.preset = "<key>"  -> that preset ("khusus")
--   inst.preset = "-"      -> its own privateServer ("link sendiri")
--   inst.preset = nil / "" -> the default preset (config defaultPreset), else its own
--                             privateServer
-- Returns key or nil, source ("khusus" / "default" / "link" / "none"), link or nil.
function InstanceManager.missingPackages()
    local missing = {}
    if #instances == 0 then return missing end
    local ok, out = require("utils.shell").exec("pm list packages")
    if not ok or not out or out == "(dry-run)" then return missing end
    local installed = {}
    for line in out:gmatch("[^\r\n]+") do
        local pkg = line:match("package:(%S+)")
        if pkg then installed[pkg] = true end
    end
    for _, inst in ipairs(instances) do
        if inst.package and inst.package ~= "" and not installed[inst.package] then
            missing[#missing + 1] = { id = inst.id, name = inst.name or inst.package, package = inst.package }
        end
    end
    return missing
end

function InstanceManager.presetOf(inst)
    if type(inst) ~= "table" then return nil, "none", nil end
    local okC, Config = pcall(require, "core.config")
    local conf = okC and Config.get() or {}
    local ps = type(conf.presets) == "table" and conf.presets or {}
    local own = (type(inst.privateServer) == "string" and inst.privateServer ~= "") and inst.privateServer or nil
    local function link(key)
        local p = ps[key]
        return (type(p) == "table" and type(p.link) == "string" and p.link ~= "") and p.link or nil
    end
    local key = inst.preset
    if key == "-" then return nil, own and "link" or "none", own end
    if type(key) == "string" and key ~= "" and link(key) then return key, "khusus", link(key) end
    local def = conf.defaultPreset
    if type(def) == "string" and def ~= "" and link(def) then return def, "default", link(def) end
    if own then return nil, "link", own end
    return nil, "none", nil
end

-- Game link of an instance (see presetOf). nil = no link (launch the app only).
function InstanceManager.gameLink(inst)
    local _, _, link = InstanceManager.presetOf(inst)
    return link
end

-- Readable game name for a link: ".../games/123/Steal-an-Egg" -> "Steal an Egg".
local function nameFromLink(link, fallback)
    local slug = tostring(link or ""):match("/games/%d+/([^/?#]+)")
    if slug and slug ~= "" then return (slug:gsub("[-_]+", " ")) end
    return fallback
end

-- One-time move to presets (update.sh migration): the clones' own links become presets
-- (one per distinct link); the most used one becomes the default, clones on another
-- link get that preset as their own. Own links stay as a fallback. Returns a message,
-- or nil when there is nothing to do.
function InstanceManager.migrateToPresets(conf)
    if type(conf.presets) == "table" and next(conf.presets) ~= nil then return nil end
    local order, count, keyOf = {}, {}, {}
    for _, inst in ipairs(instances) do
        local l = inst.privateServer
        if type(l) == "string" and l ~= "" and (inst.preset == nil or inst.preset == "") then
            if not count[l] then order[#order + 1] = l; count[l] = 0 end
            count[l] = count[l] + 1
        end
    end
    if #order == 0 then return nil end
    local best = order[1]
    for _, l in ipairs(order) do if count[l] > count[best] then best = l end end
    conf.presets = {}
    local letters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    for i, l in ipairs(order) do
        local key = letters:sub(i, i)
        if key == "" then key = "P" .. i end
        keyOf[l] = key
        conf.presets[key] = { name = nameFromLink(l, "Game " .. key), link = l }
    end
    conf.defaultPreset = keyOf[best]
    for _, inst in ipairs(instances) do
        local l = inst.privateServer
        if keyOf[l] and keyOf[l] ~= conf.defaultPreset and (inst.preset == nil or inst.preset == "") then
            inst.preset = keyOf[l]
        end
    end
    conf.instances = instances
    return string.format("%d preset dibuat dari link clone, default %s (%s)", #order,
        conf.defaultPreset, conf.presets[conf.defaultPreset].name)
end

-- Find an instance by id (number or "3"), name, package or username-free label.
function InstanceManager.find(ref)
    if ref == nil then return nil end
    local n = tonumber(ref)
    for _, v in ipairs(instances) do
        if (n and v.id == n) or v.name == ref or v.package == ref then return v end
    end
    local low = tostring(ref):lower()
    for _, v in ipairs(instances) do
        if tostring(v.name or ""):lower() == low then return v end
    end
    return nil
end

-- Save the current instance list to config/config.lua.
function InstanceManager.save()
    local Config = require("core.config")
    local conf = Config.get() or {}
    conf.instances = instances
    return Config.save(conf)
end

function InstanceManager.getAll()
    return instances
end

function InstanceManager.count()
    return #instances
end

function InstanceManager.findById(id)
    for _, v in ipairs(instances) do
        if v.id == id then return v end
    end
    return nil
end

local function persist()
    local Config = require("core.config")
    local conf = Config.get() or {}
    conf.instances = instances
    return Config.save(conf)
end

function InstanceManager.add(instance)
    instance = instance or {}
    -- compute next id
    local maxid = 0
    for _, v in ipairs(instances) do
        if type(v.id) == "number" and v.id > maxid then maxid = v.id end
    end
    instance.id = (instance.id and tonumber(instance.id)) or (maxid + 1)

    table.insert(instances, instance)
    local ok, err = persist()
    if not ok then return false, err end
    return true, instance
end

function InstanceManager.update(id, updates)
    id = tonumber(id)
    local inst = InstanceManager.findById(id)
    if not inst then return false, "not_found" end
    for k, v in pairs(updates) do inst[k] = v end
    local ok, err = persist()
    if not ok then return false, err end
    return true, inst
end

function InstanceManager.remove(id)
    id = tonumber(id)
    for i, v in ipairs(instances) do
        if v.id == id then
            table.remove(instances, i)
            local ok, err = persist()
            if not ok then return false, err end
            return true
        end
    end
    return false, "not_found"
end

return InstanceManager
]]

__ya_sources["managers.launch_queue"] = [[
-- One loading slot shared by Launch All, automatic recovery and remote requests.
-- tick() never waits for a game: the monitor remains responsive while work is held.
local Queue = {}
Queue.__index = Queue

Queue.DEFAULTS = {
    stableHeartbeats = 3, stableSeconds = 20, retryCooldown = 120, maxAttempts = 3,
}

function Queue.new(conf, deps)
    deps = deps or {}
    local self = setmetatable({ conf = conf or {}, pending = {}, active = nil,
        states = {}, attempts = {}, healthySince = {}, seenAt = {}, lastEmpty = {} }, Queue)
    for key, mod in pairs({ hb = "heartbeat", apk = "apk", auth = "auth", recovery = "recovery",
        key = "delta_key", optimizer = "optimizer" }) do
        self[key] = deps[key] or require("managers." .. mod)
    end
    self.log = deps.log or require("core.logger")
    self.now = deps.now or os.time
    self.onRecovery = deps.onRecovery
    return self
end

function Queue:setting(key)
    local s = type(self.conf.launchSafety) == "table" and self.conf.launchSafety or {}
    local minimum = ({ stableHeartbeats = 2, stableSeconds = 5, retryCooldown = 30, maxAttempts = 1 })[key] or 0
    return math.max(minimum, math.floor(tonumber(s[key]) or Queue.DEFAULTS[key]))
end

function Queue:keyStatus()
    local now = self.now()
    if not self.keyAt or now - self.keyAt >= 5 then
        local ok, value = pcall(self.key.present)
        self.keyValue, self.keyAt = ok and value or nil, now
        -- Lua's `and/or` idiom loses false; missing is different from unknown.
        if ok and value == false then self.keyValue = false end
    end
    return self.keyValue
end

function Queue:set(job, state, detail)
    self.states[job.inst.package] = state
    if job.state ~= state then
        job.state = state
        self.log.info(string.format("[QUEUE] %s: %s%s", tostring(job.inst.name or job.inst.package), state,
            detail and (" (" .. detail .. ")") or ""))
    end
end

function Queue:contains(pkg)
    if self.active and self.active.inst.package == pkg then return true end
    for _, job in ipairs(self.pending) do if job.inst.package == pkg then return true end end
    return false
end

function Queue:request(instances, manual)
    local ordered, later = {}, {}
    for _, inst in ipairs(instances or {}) do
        local target = self.auth.isLoggedIn(inst) == false and later or ordered
        target[#target + 1] = inst
    end
    for _, inst in ipairs(later) do ordered[#ordered + 1] = inst end
    for _, inst in ipairs(ordered) do
        local pkg = inst.package
        if pkg then
            if manual and self.active and self.active.inst.package == pkg and self.active.state == "needs_check" then
                -- Retry the held clone in place: moving it behind others would open a
                -- second game while this one may still be loading.
                self.attempts[pkg] = nil
                self.active = { inst = inst, manual = true }
                self.states[pkg] = "queued"
            end
            if not self:contains(pkg) then
                if manual then self.attempts[pkg] = nil end
                self.pending[#self.pending + 1] = { inst = inst, manual = manual == true, recovering = manual ~= true }
                self.states[pkg] = "queued"
            end
        end
    end
end

function Queue:finish(job, state)
    self:set(job, state)
    self.active = nil
end

function Queue:retry(job, reason)
    job.started, job.firstBeatTime, job.lastSeq, job.samples = nil, nil, nil, 0
    job.retryAt = self.now() + math.max(1, self:setting("retryCooldown"))
    self:set(job, "cooldown", reason)
end

function Queue:process(inst)
    local ok, value = pcall(self.apk.isRunning, inst.package)
    if ok and type(value) == "boolean" then return value end
    return nil
end

function Queue:advance(job)
    local inst, now = job.inst, self.now()
    local process = self:process(inst)
    if self.auth.isLoggedIn(inst) == false then
        -- Logging out during a wait must never lead to a force-stop/rejoin.
        if process == nil then self:set(job, "needs_check", "proses tidak terbaca"); return end
        local closed = process == false
        if process and self.apk.hasWindow then
            local ok, window = pcall(self.apk.hasWindow, inst.package)
            closed = ok and window == false
        end
        if closed and self.conf.relaunchNoLogin ~= false then
            if now - (self.lastEmpty[inst.package] or -math.huge) < (tonumber(self.conf.noLoginCooldown) or 120) then
                self:set(job, "cooldown"); return
            end
            self.lastEmpty[inst.package] = now
            self.recovery.reopenNoLogin(inst)
            job.emptyAt = now
        end
        job.emptyAt = job.emptyAt or now
        self:set(job, "nologin")
        if now - job.emptyAt >= (tonumber(self.conf.launchEmptyDelay) or 5) then self:finish(job, "nologin") end
        return
    end

    local alive, why = self.hb.alive(inst)
    if self.hb.isEnabled() and self:keyStatus() == false and (alive ~= true or process ~= true) then
        job.keyWait = true
        job.samples, job.firstBeatTime, job.lastSeq = 0, nil, nil
        self:set(job, "wait_key", "license tidak tersedia; perlu dicek/diisi manual")
        return
    end
    if job.keyWait then
        job.keyWait = nil
        if job.started then job.started = now end -- key entry time is not loading time
    end
    if self.hb.isEnabled() then
        local name, err = self.hb.identity(inst)
        if not name then
            job.identityWait = true
            self:set(job, "wait_identity", err)
            return
        end
        if job.identityWait then
            job.identityWait = nil
            if job.started then job.started = now end
        end
    end
    if not job.started then
        if job.state == "needs_check" then return end
        if job.retryAt and now < job.retryAt then self:set(job, "cooldown"); return end
        local attempt = self.attempts[inst.package] or { count = 0, last = -math.huge }
        if attempt.count >= math.max(1, self:setting("maxAttempts")) then
            self:set(job, "needs_check", "batas percobaan tercapai; restart manual untuk coba lagi"); return
        end
        if not job.manual and now - attempt.last < self:setting("retryCooldown") then
            self:set(job, "cooldown"); return
        end
        attempt.count, attempt.last = attempt.count + 1, now
        self.attempts[inst.package] = attempt
        local ok, launched, err = pcall(self.recovery.launchAndJoin, inst)
        if not ok or not launched then self:retry(job, tostring(ok and err or launched)); return end
        if (attempt.count > 1 or job.recovering) and self.onRecovery then
            pcall(self.onRecovery, inst.id)
        end
        job.started, job.samples = self.now(), 0
        job.manual, job.retryAt = false, nil
        self.healthySince[inst.package] = nil
        pcall(self.optimizer.applyForInstance, inst)
        self:set(job, "starting")
        return
    end

    if process == nil then self:set(job, "needs_check", "proses tidak terbaca"); return end
    if process == false then self:retry(job, "proses mati"); return end
    if not self.hb.isEnabled() then
        self:set(job, "starting", "heartbeat dimatikan; hanya menunggu proses")
        if now - job.started >= math.max(20, tonumber(self.conf.launchSettleDelay) or 20) then
            self:finish(job, "running")
        end
        return
    end
    if alive == false then self:retry(job, why); return end
    local hb = self.hb.read(inst)
    if alive == true and hb and hb.current and hb.fresh then
        if job.session ~= hb.session then
            job.samples, job.lastSeq, job.firstBeatTime = 0, nil, nil
            job.session = hb.session
        end
        if job.lastSeq and (hb.seq < job.lastSeq or hb.time < job.lastBeatTime) then
            job.samples, job.firstBeatTime = 0, nil
        end
        if not job.lastSeq or hb.seq ~= job.lastSeq then
            job.samples = (job.samples or 0) + 1
            job.lastSeq, job.lastBeatTime = hb.seq, hb.time
            job.firstBeatTime = job.firstBeatTime or hb.time
        end
        self:set(job, "stabilizing")
        if job.samples >= math.max(1, self:setting("stableHeartbeats"))
            and hb.time - job.firstBeatTime >= self:setting("stableSeconds") then
            self.healthySince[inst.package] = now
            self:finish(job, "ingame")
        end
        return
    end
    job.samples, job.lastSeq, job.firstBeatTime = 0, nil, nil
    if job.state ~= "needs_check" then self:set(job, "starting") end
    local timeout = math.max(30, tonumber(self.conf.launchJoinTimeout) or 240)
    if now - job.started >= timeout then
        self:set(job, "needs_check", "heartbeat belum siap; antrean ditahan, tanpa restart otomatis")
    end
end

function Queue:tick(instances)
    local byPackage = {}
    for _, inst in ipairs(instances) do byPackage[inst.package] = inst end
    -- Reconcile edits/removal from the menu or bot, even while a job is held.
    if self.active then
        local fresh = byPackage[self.active.inst.package]
        if fresh then self.active.inst = fresh else self.active = nil end
    end
    for i = #self.pending, 1, -1 do
        local fresh = byPackage[self.pending[i].inst.package]
        if fresh then self.pending[i].inst = fresh else table.remove(self.pending, i) end
    end
    for _, inst in ipairs(instances) do
        local pkg, now = inst.package, self.now()
        if not self:contains(pkg) then
            local loggedIn = self.auth.isLoggedIn(inst)
            -- A clone that was gently opened at its login screen has no queued job
            -- after the nologin settle period. Once the owner logs in, queue a fresh
            -- cold launch so the configured game link is actually opened.
            if loggedIn == true and self.states[pkg] == "nologin" then
                self:request({ inst }, true)
            else
                local process = self:process(inst)
                local alive = self.hb.alive(inst)
                if loggedIn == false then
                    self.states[pkg] = "nologin"
                    local closed = process == false
                    if process and self.apk.hasWindow then
                        local ok, window = pcall(self.apk.hasWindow, pkg)
                        closed = ok and window == false
                    end
                    if closed and self.conf.relaunchNoLogin ~= false then self:request({ inst }, false) end
                elseif process == nil then
                    self.states[pkg] = "needs_check"
                elseif process == false or alive == false then
                    self.healthySince[pkg] = nil
                    self:request({ inst }, false)
                elseif alive == true then
                    self.states[pkg] = "ingame"
                    self.healthySince[pkg] = self.healthySince[pkg] or now
                    if now - self.healthySince[pkg] >= 60 then self.attempts[pkg] = nil end
                elseif not self.hb.isEnabled() then
                    self.states[pkg] = "running"
                else
                    self.seenAt[pkg] = self.seenAt[pkg] or now
                    self.states[pkg] = self:keyStatus() == false and "wait_key" or "starting"
                    -- Adopt a running clone without restarting it just because HB is absent.
                    if not self.active then self.active = { inst = inst, started = self.seenAt[pkg], samples = 0 } end
                end
            end
        end
    end
    if not self.active then self.active = table.remove(self.pending, 1) end
    if self.active then self:advance(self.active) end
end

return Queue
]]

__ya_sources["managers.logout_alarm"] = [[
local Logger = require("core.logger")

local Alarm = {}
local WIB_OFFSET = 7 * 60 * 60

local function leapYear(year)
    return year % 4 == 0 and (year % 100 ~= 0 or year % 400 == 0)
end

local function daysInMonth(year, month)
    local days = { 31, leapYear(year) and 29 or 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 }
    return days[month]
end

-- Days since 1970-01-01, independent of the Android device's local timezone.
local function daysFromCivil(year, month, day)
    local y = year
    if month <= 2 then y = y - 1 end
    local era = math.floor(y / 400)
    local yoe = y - era * 400
    local adjustedMonth = month + (month > 2 and -3 or 9)
    local doy = math.floor((153 * adjustedMonth + 2) / 5) + day - 1
    local doe = yoe * 365 + math.floor(yoe / 4) - math.floor(yoe / 100) + doy
    return era * 146097 + doe - 719468
end

local function validTime(value)
    if type(value) ~= "string" then return nil end
    local hour, minute = value:match("^(%d%d):(%d%d)$")
    hour, minute = tonumber(hour), tonumber(minute)
    if not hour or not minute or hour > 23 or minute > 59 then return nil end
    return string.format("%02d:%02d", hour, minute), hour * 60 + minute
end

local function parseDate(value)
    if type(value) ~= "string" then return nil end
    local day, month, year = value:match("^(%d%d)/(%d%d)/(%d%d%d%d)$")
    if not day then day, month = value:match("^(%d%d)/(%d%d)$") end
    day, month, year = tonumber(day), tonumber(month), tonumber(year)
    if not day or not month or month < 1 or month > 12 then return nil end
    return day, month, year
end

local function epochAtWib(year, month, day, time)
    local _, minuteOfDay = validTime(time)
    if not minuteOfDay then return nil end
    return daysFromCivil(year, month, day) * 86400 + minuteOfDay * 60 - WIB_OFFSET
end

local function resolveDate(date, time, now)
    local day, month, year = parseDate(date)
    if not day then return nil, "tanggal harus format DD/MM atau DD/MM/YYYY" end
    now = now or os.time()
    local current = os.date("!*t", now + WIB_OFFSET)
    local lastYear = year or (current.year + 8)
    local firstYear = year or current.year
    for candidateYear = firstYear, lastYear do
        if candidateYear >= 1970 and candidateYear <= 9999
            and day <= daysInMonth(candidateYear, month) then
            local due = epochAtWib(candidateYear, month, day, time)
            if due and due > now then
                return string.format("%02d/%02d/%04d", day, month, candidateYear), due
            end
        end
    end
    if year then return nil, "tanggal dan jam harus di masa depan dan merupakan tanggal kalender yang valid" end
    return nil, "tidak menemukan tanggal berikutnya yang valid"
end

local function nextDailyAt(time, now)
    now = now or os.time()
    local today = os.date("!*t", now + WIB_OFFSET)
    local due = epochAtWib(today.year, today.month, today.day, time)
    if due <= now then due = due + 86400 end
    return due
end

local function findInstance(id)
    for _, inst in ipairs(require("managers.instance").getAll()) do
        if tonumber(inst.id) == tonumber(id) then return inst end
    end
end

function Alarm.set(id, date, time, daily)
    local inst = findInstance(id)
    if not inst then return false, "clone tidak ditemukan" end
    local normalizedTime = validTime(time)
    if not normalizedTime then return false, "waktu harus format HH:MM WIB (00:00–23:59)" end
    local scheduledDate, scheduledAt = resolveDate(date, normalizedTime)
    if not scheduledDate then return false, scheduledAt end
    local previous = inst.logoutAlarm
    inst.logoutAlarm = {
        date = scheduledDate,
        time = normalizedTime,
        daily = daily == true,
        nextAt = scheduledAt,
        timezone = "Asia/Jakarta",
    }
    local ok, err = require("managers.instance").save()
    if not ok then inst.logoutAlarm = previous; return false, "gagal menyimpan alarm: " .. tostring(err) end
    return true, string.format("alarm logout %s %s WIB untuk %s%s", scheduledDate, normalizedTime,
        inst.name or inst.package or tostring(inst.id), daily and " (berulang setiap hari)" or " (sekali)")
end

function Alarm.remove(id)
    local inst = findInstance(id)
    if not inst then return false, "clone tidak ditemukan" end
    if type(inst.logoutAlarm) ~= "table" then return false, "clone ini belum punya alarm logout" end
    local previous = inst.logoutAlarm
    inst.logoutAlarm = nil
    local ok, err = require("managers.instance").save()
    if not ok then inst.logoutAlarm = previous; return false, "gagal menghapus alarm: " .. tostring(err) end
    return true, "alarm logout dihapus untuk " .. tostring(inst.name or inst.package or inst.id)
end

function Alarm.tick(instances, launchBusy)
    local now = os.time()
    for _, inst in ipairs(instances or {}) do
        local alarm = inst.logoutAlarm
        local dueAt = type(alarm) == "table" and tonumber(alarm.nextAt) or nil
        if dueAt and now >= math.max(dueAt, tonumber(alarm.retryAt) or 0) then
            if launchBusy then return end
            local wib = os.date("!*t", now + WIB_OFFSET)
            local today = string.format("%04d-%02d-%02d", wib.year, wib.month, wib.day)
            if alarm.daily and alarm.lastRunDate == today then
                alarm.nextAt = nextDailyAt(alarm.time, now + 1)
            else
                local okCall, ok, message = pcall(require("managers.cookie_injector").logout, inst)
                local completed = okCall and (ok or tostring(message):find("memang sudah logout", 1, true))
                if completed then
                    Logger.info("Logout alarm: " .. tostring(inst.name or inst.package) .. " -> " .. tostring(message))
                    if alarm.daily then
                        alarm.lastRunDate = today
                        alarm.nextAt = nextDailyAt(alarm.time, now + 1)
                        alarm.retryAt = nil
                    else
                        inst.logoutAlarm = nil
                    end
                else
                    alarm.retryAt = now + 60
                    Logger.warn("Logout alarm gagal untuk " .. tostring(inst.name or inst.package)
                        .. "; dicoba lagi sekitar 60 detik: " .. tostring(okCall and message or ok))
                end
            end
            local saved, err = require("managers.instance").save()
            if not saved then Logger.error("Logout alarm: gagal menyimpan status alarm: " .. tostring(err)) end
        end
    end
end

Alarm.validTime = validTime
Alarm.parseDate = parseDate
Alarm.resolveDate = resolveDate
Alarm.nextDailyAt = nextDailyAt
return Alarm
]]

__ya_sources["managers.monitor"] = [[
local Paths = require("core.paths")
local Logger = require("core.logger")
local Timer = require("utils.timer")
local Status = require("managers.status")
local Auth = require("managers.auth")
local Username = require("managers.username")
local ProbeLog = require("utils.probe_log")
local Heartbeat = require("managers.heartbeat")
local WindowLayout = require("managers.window_layout")
local Webhook = require("managers.webhook")
local Remote = require("managers.remote")

local Monitor = {}
local running = false
local interrupted = false
local instanceManager = nil
local apkManager = nil

-- Install a SIGINT handler via lua-posix so Ctrl+C stops monitoring and exits the
-- program immediately. This is the ONLY reliable way to catch Ctrl+C in Termux: the
-- default SIGINT action does NOT kill the program here, and without a handler the
-- signal is effectively swallowed. Requires `pkg install lua-posix` (Lua PUC-Rio).
local function installSignalHandler()
    local ok, posix = pcall(require, "posix.signal")
    if not ok or not posix then
        -- lua-posix is not available in Termux's repos for this setup. Without it there
        -- is no pure-Lua way to catch SIGINT, and the default action is unreliable here
        -- (the monitor is almost always inside os.execute, which blocks SIGINT). Advise
        -- the run.sh wrapper, which catches Ctrl+C in the shell and kill(1)s us, instead.
        Logger.warn("Monitor: lua-posix not available; run via `sh run.sh` so Ctrl+C can stop the engine")
        return false
    end
    local sigint = posix.SIGINT or 2
    pcall(function()
        posix.signal(sigint, function()
            -- Flip flags so the monitor loop unwinds, then exit hard. os.exit from a
            -- signal handler is not strictly async-signal-safe, but works on PUC-Rio
            -- / LuaJIT in practice and makes Ctrl+C stop the program decisively.
            running = false
            interrupted = true
            os.exit(0)
        end)
    end)
    Logger.info("Monitor: SIGINT handler installed (Ctrl+C will exit)")
    return true
end

-- Only one engine may drive the clones: the boot engine runs hidden in the
-- background, and a second one started from the menu would force-stop and relaunch
-- the same clones. The running engine's pid is kept in data/monitor.pid.
local PID_FILE = Paths.data("monitor.pid")

local function selfPid()
    -- The shell spawned by popen is our child, so its $PPID is this Lua process.
    local f = io.popen("echo $PPID")
    if not f then return nil end
    local pid = tonumber(f:read("*l") or "")
    f:close()
    return pid
end

-- pid of another live engine, or nil.
local function otherEngine(myPid)
    local f = io.open(PID_FILE, "r")
    if not f then return nil end
    local pid = tonumber(f:read("*l") or "")
    f:close()
    if not pid or pid == myPid then return nil end
    local c = io.open("/proc/" .. pid .. "/cmdline", "r")
    if not c then return nil end
    local cmdline = c:read("*a") or ""
    c:close()
    if cmdline:find("main.lua", 1, true) or cmdline:find("yanamin.lua", 1, true) then return pid end
    return nil
end

local function writePid(pid)
    if not pid then return end
    Paths.ensure()
    local f = io.open(PID_FILE, "w")
    if f then f:write(tostring(pid), "\n"); f:close() end
end

local function clearPid(pid)
    local f = io.open(PID_FILE, "r")
    if not f then return end
    local stored = tonumber(f:read("*l") or "")
    f:close()
    if stored == pid then os.remove(PID_FILE) end
end

-- All starts/recoveries share one queue; no RSS-based recovery in this module.
local LaunchQueue = require("managers.launch_queue")
local queue = nil
local windowState = {}
local monitorConf = {}
local keyState = nil

local function checkKey()
    local present = queue:keyStatus()
    if present == nil or present == keyState then return end
    keyState = present
    if present then Logger.info("[KEY] license Delta tersedia lagi; tetap tunggu heartbeat"); return end
    Logger.warn("[KEY] license Delta tidak tersedia; dugaan perlu key, antrean ditahan")
    Webhook.event("key", "🔑 Delta perlu dicek",
        "License tidak tersedia. Clone tanpa heartbeat menunggu key; tidak direstart berulang. Isi key secara manual.", 16705372)
end

local function checkWindow(inst)
    if not WindowLayout.isEnabled() then return end
    local pkg = inst and inst.package
    if not pkg then return end
    local okR, runningNow = pcall(function() return apkManager.isRunning(pkg) end)
    if not okR or not runningNow then return end
    local okV, res, actual, target = pcall(WindowLayout.verify, inst)
    if not okV or res == nil then return end
    if windowState[pkg] == res then return end
    windowState[pkg] = res
    local name = tostring(inst.name or pkg)
    if res then
        Logger.info(string.format("[WINDOW] %s posisi OK", name))
    else
        Logger.warn(string.format("[WINDOW] %s meleset (sekarang %s; target %s) -> dibetulkan saat relaunch berikutnya",
            name, WindowLayout.formatBounds(actual), WindowLayout.formatBounds(target)))
    end
end

local REQUEST_FILE = Paths.data("rejoin_request.txt")
local AUTH_FORGET_FILE = Paths.data("auth_forget.txt") -- written by CookieInjector.logout

-- Packages just logged out (maybe from Menu 5 in another process): forget their cached
-- login state before deciding whether a closed clone gets rejoined.
local function takeAuthForget()
    local f = io.open(AUTH_FORGET_FILE, "r")
    if not f then return end
    local text = f:read("*a") or ""
    f:close()
    os.remove(AUTH_FORGET_FILE)
    for pkg in text:gmatch("[^\r\n]+") do Auth.forget(pkg) end
end
local rejoinQueue = {}

function Monitor.requestRejoin(ids)
    for _, id in ipairs(ids or {}) do rejoinQueue[#rejoinQueue + 1] = id end
end

-- From another process: append ids (or "all") to the request file.
function Monitor.requestRejoinFile(ids)
    local f = io.open(REQUEST_FILE, "a")
    if not f then return false end
    for _, id in ipairs(ids or {}) do f:write(tostring(id), "\n") end
    f:close()
    return true
end

local function takeFileRequests()
    local f = io.open(REQUEST_FILE, "r")
    if not f then return end
    local text = f:read("*a") or ""
    f:close()
    os.remove(REQUEST_FILE)
    -- The menu saved new config (presets / links) before asking: pick it up.
    pcall(function()
        local Config = require("core.config")
        Config.reload()
        instanceManager.load(Config.get())
    end)
    for line in text:gmatch("[^\r\n]+") do
        rejoinQueue[#rejoinQueue + 1] = line:match("^%s*(.-)%s*$")
    end
end

local function runRejoinQueue()
    takeFileRequests()
    if #rejoinQueue == 0 then return end
    local list, seen = {}, {}
    for _, ref in ipairs(rejoinQueue) do
        local candidates = ref == "all" and instanceManager.getAll() or { instanceManager.find(ref) }
        for _, inst in ipairs(candidates) do
            if not seen[inst.package] then seen[inst.package] = true; list[#list + 1] = inst end
        end
    end
    rejoinQueue = {}
    queue:request(list, true)
end

local CONFIG_FILE = Paths.config()
local configText = nil

local function readConfigText()
    local f = io.open(CONFIG_FILE, "r")
    if not f then return nil end
    local text = f:read("*a")
    f:close()
    return text
end

local function sameFields(a, b)
    if type(a) ~= "table" or type(b) ~= "table" then return a == b end
    for k, v in pairs(a) do if b[k] ~= v then return false end end
    for k, v in pairs(b) do if a[k] ~= v then return false end end
    return true
end

local function syncMenuSettings()
    local text = readConfigText()
    if not text or text == configText then return end
    local Config = require("core.config")
    local previousWebhook = monitorConf.webhook
    if not Config.reload() then return end
    configText = text
    monitorConf = Config.get()
    queue.conf = monitorConf
    instanceManager.load(monitorConf)
    if not sameFields(previousWebhook, monitorConf.webhook) then Webhook.configure(monitorConf) end
end

function Monitor.start(conf, opts)
    if running then Logger.warn("Monitor already running"); return false end
    monitorConf, opts = conf or {}, opts or {}
    instanceManager = require("managers.instance")
    apkManager = require("managers.apk")
    local myPid = selfPid()
    local other = otherEngine(myPid)
    if other then
        Logger.error(string.format("Monitor: engine lain masih jalan (pid %d). Stop dulu: kill %d", other, other))
        return false
    end
    writePid(myPid)
    running, interrupted = true, false
    configText, windowState, keyState = readConfigText(), {}, nil
    Status.reset()
    Status.configure(monitorConf)
    Status.resetDashboard()
    ProbeLog.configure(monitorConf)
    ProbeLog.init()
    Username.reset()
    pcall(Username.prefetch, instanceManager.getAll())
    installSignalHandler()
    local installed, err = Heartbeat.install()
    if not installed then Logger.warn("Monitor: heartbeat belum terpasang: " .. tostring(err)) end
    Webhook.configure(monitorConf)
    queue = LaunchQueue.new(monitorConf, { onRecovery = Status.noteRecovery })
    if opts.autoLaunch then
        os.remove(REQUEST_FILE)
        -- Logged-in clones first; login screens are opened gently at the end.
        local first, later = {}, {}
        for _, inst in ipairs(instanceManager.getAll()) do
            local target = Auth.isLoggedIn(inst) == false and later or first
            target[#target + 1] = inst
        end
        for _, inst in ipairs(later) do first[#first + 1] = inst end
        queue:request(first, true)
    end
    Logger.setConsoleVisible(false)
    io.write("\27[2J\27[H")
    Logger.info("Monitor: antrean heartbeat aktif (satu slot loading; RSS hanya info)")
    local lastDiagnostics, lastWindow = 0, 0
    while running do
        pcall(takeAuthForget)
        pcall(syncMenuSettings)
        pcall(runRejoinQueue)
        local instances = instanceManager.getAll()
        local ok, issue = pcall(queue.tick, queue, instances)
        if not ok then
            Logger.error("[QUEUE] gagal cek: " .. tostring(issue))
            -- Hold this cycle: an error must never advance a second launch.
        end
        local statuses = {}
        for _, inst in ipairs(instances) do
            Status.setLifecycle(inst.id, queue.states[inst.package])
            statuses[inst.id] = Status.check(inst)
        end
        local activeIndex
        if queue.active then
            for i, inst in ipairs(instances) do
                if inst.package == queue.active.inst.package then activeIndex = i; break end
            end
        end
        local labels = { wait_key = "Menunggu key", wait_identity = "Identifikasi",
            needs_check = "Perlu dicek", stabilizing = "Stabil", cooldown = "Jeda retry" }
        Status.setProgress(activeIndex, activeIndex and #instances or nil,
            queue.active and (labels[queue.active.state] or "Loading") or nil)
        Status.printSummary(instances)
        pcall(checkKey)
        Webhook.tick(instances)
        pcall(Remote.tick, instances, { requestRejoin = Monitor.requestRejoin, launchBusy = queue.active ~= nil })
        pcall(require("managers.logout_alarm").tick, instances, queue.active ~= nil)
        -- Expensive probes do not run on every loading poll.
        if os.time() - lastDiagnostics >= 30 then
            pcall(ProbeLog.scan, instances, statuses)
            lastDiagnostics = os.time()
        end
        if os.time() - lastWindow >= 60 then
            for _, inst in ipairs(instances) do pcall(checkWindow, inst) end
            lastWindow = os.time()
        end
        os.execute("stty isig 2>/dev/null")
        local delay = queue.active and monitorConf.launchWaitInterval or monitorConf.monitorInterval
        Timer.sleepInterruptible(math.max(1, tonumber(delay) or 5), function() return not running end)
    end
    queue = nil
    clearPid(myPid)
    Logger.setConsoleVisible(true)
    io.write("\27[?25h\r\n")
    io.flush()
    return true
end

function Monitor.stop()
    running = false
    Logger.info("Monitor: stopped")
end

function Monitor.interrupted()
    return interrupted
end

return Monitor
]]

__ya_sources["managers.optimizer"] = [[
local Logger = require("core.logger")
local Shell = require("utils.shell")
local Config = require("core.config")

-- Reduces RAM/CPU contention between the Roblox clones by deprioritizing them.
--
-- With four floating-window clones running at once they compete for CPU time, I/O and
-- memory. Android runs each clone as its own process, so as root we can tune their
-- Linux process priorities directly:
--   * nice   -> CPU scheduling priority (higher = lower priority, 19 = lowest)
--   * ionice -> I/O class (class 3 = idle, only runs when nobody else needs the disk)
-- Every clone is deprioritized equally (chosen over keeping the focused one boosted).
--
-- IMPORTANT: the clone process is relaunched (force-stop + start) on every recovery, so
-- it gets a NEW pid every time. renice/ionice act on a pid, so Optimizer must be re-applied
-- after every launch / recovery that restarts a clone.

local Optimizer = {}

local function safeConfig()
    local ok, conf = pcall(function() return Config.get() end)
    if not ok or type(conf) ~= "table" then return {} end
    return conf or {}
end

-- Current optimizer config: { enabled, renice, ionice }.
function Optimizer.getConfig()
    local opt = safeConfig().optimizer
    if type(opt) ~= "table" then opt = {} end
    return {
        enabled = opt.enabled ~= false,
        renice = tonumber(opt.renice) or 19,
        ionice = tonumber(opt.ionice) or 3,
    }
end

-- Resolve the main process pid(s) for a package via pidof. Returns "" (false-y) when
-- the process isn't running, so callers can skip a not-yet-up clone without error.
local function getPids(pkg)
    if not pkg or pkg == "" then return "" end
    local ok, _, out = pcall(function() return Shell.exec("pidof " .. pkg) end)
    if not ok or not out then return "" end
    return (out:gsub("\n", " ")):gsub("%s+$", "")
end

-- Lower one specific pid's CPU + I/O priority. Best-effort: never throws.
local function applyToPid(pid, cfg)
    if not pid or pid == "" then return end
    local reniceCmd = string.format("renice %d -p %s", cfg.renice, pid)
    local okR, _, outR = pcall(function() return Shell.exec(reniceCmd) end)
    if not okR then
        Logger.debug("Optimizer: renice failed for pid " .. pid)
    elseif outR and outR ~= "(dry-run)" then
        Logger.debug("Optimizer: " .. tostring(outR))
    end

    -- ionice: class 3 (idle). Best-effort; some kernels/toolboxes lack ionice.
    local okI = pcall(function() return Shell.exec(string.format("ionice -c %d -p %s", cfg.ionice, pid)) end)
    if not okI then
        Logger.debug("Optimizer: ionice unavailable/unsupported, skipping I/O tuning")
    end
end

-- Apply deprioritization to a single instance (by package). No-op if disabled or when
-- the package isn't running yet. Returns true if something was applied.
function Optimizer.applyForInstance(instance)
    local cfg = Optimizer.getConfig()
    if not cfg.enabled then return false end
    local pkg = instance and instance.package
    if not pkg or pkg == "" then return false end

    local pids = getPids(pkg)
    if not pids or pids == "" then return false end
    for pid in pids:gmatch("%S+") do
        pcall(function() applyToPid(pid, cfg) end)
    end
    Logger.debug(string.format("Optimizer: deprioritized %s (nice=%d ionice=%d)", pkg, cfg.renice, cfg.ionice))
    return true
end

-- Apply deprioritization to all configured instances.
function Optimizer.applyAll()
    local ok, conf = pcall(function() return Config.get() end)
    if not ok or not conf or type(conf.instances) ~= "table" then return 0 end
    if not Optimizer.getConfig().enabled then return 0 end

    local applied = 0
    for _, inst in ipairs(conf.instances) do
        if Optimizer.applyForInstance(inst) then applied = applied + 1 end
    end
    return applied
end

return Optimizer
]]

__ya_sources["managers.recovery"] = [[
local Logger = require("core.logger")
local APK = require("managers.apk")
local UtilsAndroid = require("utils.android")
local Timer = require("utils.timer")
local Config = require("core.config")
local Auth = require("managers.auth")
local WindowLayout = require("managers.window_layout")
local Heartbeat = require("managers.heartbeat")

local Recovery = {}

local function safeNumber(v, default)
    v = tonumber(v)
    if v and v > 0 then return v end
    return default
end

-- Build the proven auto-join deep link (roblox://placeId=<id>) for any public-style
-- link, self-contained so it never depends on utils/roblox_link syncing to the device.
-- Private-server /share links must stay untouched (no placeId).
local function isShareLink(url)
    return url ~= nil and url:lower():find("roblox.com/share", 1, true) ~= nil
end

-- Extract a place id tolerantly from many Roblox link shapes:
--   https://www.roblox.com/games/<id>/<name>
--   ...?placeId=<id>  /  roblox://placeId=<id>
--   roblox://experiences/<id>
local function extractPlaceIdLenient(url)
    if not url then return nil end
    local lower = url:lower()
    if lower:find("placeid=", 1, true) then
        local id = url:lower():match("placeid=(%d+)")
        if id then return id end
    end
    local g = url:match("/games/(%d+)")
    if g then return g end
    local e = url:match("/experiences/(%d+)")
    if e then return e end
    return nil
end

-- Open the instance game/private-server link. Propagate launch failures to callers.
local function gameLink(instance)
    local okI, Instances = pcall(require, "managers.instance")
    if okI and Instances.gameLink then return Instances.gameLink(instance) end
    local l = instance and instance.privateServer
    return (type(l) == "string" and l ~= "") and l or nil
end

local function openGameLink(instance)
    local pkg = instance and instance.package
    local target = gameLink(instance)
    if not target then
        return true
    end

    local link
    if isShareLink(target) then
        -- Private server: no placeId, must keep the exact /share link.
        link = target
    else
        local placeId = extractPlaceIdLenient(target)
        if placeId then
            -- The one form proven (on-device) to auto-join a clone and reach its account.
            link = "roblox://placeId=" .. placeId
        else
            -- Unknown shape: keep as-is (letting Android/any handler decide).
            link = target
        end
    end

    Logger.info("Recovery: opening game link for " .. tostring(instance.name or pkg) .. ": " .. tostring(link))
    return UtilsAndroid.openURL(link, pkg)
end

-- Launch an instance's app and join its game (best-effort), no retry loop.
-- Returns true if the app launch succeeded.
function Recovery.launchAndJoin(instance)
    local pkg = instance and instance.package
    if not pkg then
        Logger.error("Recovery.launchAndJoin: instance has no package")
        return false
    end

    -- A logged-out clone is opened gently; never force-stop it through a game link.
    if Auth.isLoggedIn(instance) == false then return Recovery.reopenNoLogin(instance) end
    Logger.debug("Recovery.launchAndJoin: launching " .. tostring(instance.name or pkg))

    local hasLink = gameLink(instance) ~= nil

    if hasLink then
        -- On-device testing proved that OPTION-A join (`am start -a VIEW -d 'roblox://placeId=<id>'
        -- -p <clone>`) only auto-joins from a COLD (fresh) clone: the app must be force-stopped
        -- first, then the deep link launches it and joins the map. If the clone is still warm
        -- the deep link just shows the game page. Launching via the launcher activity first
        -- (APK.launch: MAIN/LAUNCHER) also left the app on its home screen, so we skip that too.
        local stopped = APK.forceStop(pkg)
        if not stopped then return false end
        Timer.sleep(1)
        -- Clone is stopped: place its floating window before it opens.
        WindowLayout.applyForInstance(instance)
        local marked, err = Heartbeat.markLaunched(instance)
        if not marked then return false, err end
        local opened = openGameLink(instance)
        if not opened then return false end
    else
        -- A new engine session needs a fresh executor run even without a saved link.
        if APK.isRunning(pkg) then
            if not APK.forceStop(pkg) then return false, "gagal menutup sesi lama" end
            Timer.sleep(1)
        end
        if WindowLayout.isEnabled() and not APK.isRunning(pkg) then
            WindowLayout.applyForInstance(instance)
        end
        local marked, err = Heartbeat.markLaunched(instance)
        if not marked then return false, err end
        local ok, err = APK.launch(pkg)
        if not ok then
            Logger.error("Recovery.launchAndJoin: launch failed for " .. tostring(instance.name or pkg) .. ": " .. tostring(err))
            return false
        end
    end

    Logger.debug("Recovery.launchAndJoin: done for " .. tostring(instance.name or pkg))
    return true
end

-- Wait until an instance's app process is observed running, with a short settle delay
-- after it is detected. Used by "Launch All" to launch clones one at a time so each
-- floating-window clone has a chance to come up before the next is started.
--
-- Each App Cloner clone runs under its OWN package process name (e.g. com.apengjers.v3),
-- so `opts.targetCount` lets the caller wait until a given number of the configured
-- instances report running (via APK.countRunning) — e.g. count >= baseline + cloneIndex
-- — which is the reliable signal that the launched clone actually came up.
--
-- Options (all optional): interval, timeout, settleDelay, targetCount, instances.
--   * targetCount:  number of configured instances (packages in `instances`) that must
--     report running before we settle and move on.
--   * instances:    list of instance tables used (together with targetCount) to compute
--     how many are running. Falls back to `{ instance }` when not provided.
-- If targetCount is given, wait until countRunning >= targetCount; otherwise fall back
-- to APK.isRunning(pkg). Returns true if detected, false on timeout.
function Recovery.waitUntilRunning(instance, opts)
    local pkg = instance and instance.package
    if not pkg then return false end

    local conf = Config.get() or {}
    opts = opts or {}
    local interval = safeNumber(opts.interval, safeNumber(conf.launchWaitInterval, 3))
    local timeout = safeNumber(opts.timeout, safeNumber(conf.launchWaitTimeout, 30))
    local settle = safeNumber(opts.settleDelay, safeNumber(conf.launchSettleDelay, 5))
    local target = tonumber(opts.targetCount)
    local instances = opts.instances or { instance }

    local packages = {}
    for _, inst in ipairs(instances) do
        if inst and inst.package then
            table.insert(packages, inst.package)
        end
    end

    local name = tostring(instance.name or pkg)
    if target then
        Logger.debug(string.format("Recovery.waitUntilRunning: waiting for %d instance(s) to be running (timeout=%ss)", target, timeout))
    else
        Logger.debug("Recovery.waitUntilRunning: waiting for " .. name .. " to open (timeout=" .. tostring(timeout) .. "s)")
    end

    local started = os.time()
    while true do
        if target then
            local c = APK.countRunning(packages)
            Logger.debug(string.format("Recovery.waitUntilRunning: running=%s target=%s", c, target))
            if c >= target then
                local elapsed = os.time() - started
                Logger.debug(string.format("Recovery.waitUntilRunning: running=%s reached target %s after %ds; settling %ds", c, target, elapsed, settle))
                Timer.sleep(settle)
                return true
            end
        else
            if APK.isRunning(pkg) then
                local elapsed = os.time() - started
                Logger.debug(string.format("Recovery.waitUntilRunning: %s opened after %ds; settling %ds", name, elapsed, settle))
                Timer.sleep(settle)
                return true
            end
        end
        if (os.time() - started) >= timeout then
            Logger.warn(string.format("Recovery.waitUntilRunning: %s not detected within %ds; continuing", name, timeout))
            return false
        end
        Timer.sleep(interval)
    end
end

-- Force-stop and relaunch an instance's app (used when an app has been frozen/stuck
-- for too long). Best-effort, no full recovery retry loop.
function Recovery.relaunch(instance)
    return Recovery.checkAndRecover(instance)
end

-- Re-open a clone that has NO logged-in account after it closed (force close / crash).
-- Gentle on purpose: never force-stops (that loop is what used to push other clones
-- out of memory), no game link (there is no account to join with), no retries; the
-- monitor rate-limits calls. A dead process gets its window slot first.
function Recovery.reopenNoLogin(instance)
    local pkg = instance and instance.package
    if not pkg then return false end
    local okR, alive = pcall(function() return APK.isRunning(pkg) end)
    if okR and not alive then
        WindowLayout.applyForInstance(instance)
    end
    Heartbeat.markLaunched(instance)
    local ok, err = APK.launch(pkg)
    if not ok then
        Logger.warn("Recovery.reopenNoLogin: launch failed for " .. tostring(instance.name or pkg) .. ": " .. tostring(err))
        return false
    end
    return true
end

-- Compatibility entrypoint: completion is reported by the shared monitor queue.
function Recovery.checkAndRecover(instance)
    if not instance or not instance.id then return false, "instance tidak valid" end
    require("managers.monitor").requestRejoin({ instance.id })
    return true, "recovery masuk antrean monitor"
end

return Recovery
]]

__ya_sources["managers.remote"] = [=[
local Paths = require("core.paths")
local Logger = require("core.logger")
local Config = require("core.config")
local JSON = require("utils.json")

-- Remote control through the user's Discord bot (see docs/discord_bot_prd.md).
--
-- The cloud phone has no public address, so the device calls the bot: every
-- remote.interval seconds the monitor loop POSTs a snapshot to <url>/api/sync and gets
-- back a list of commands, runs them, and POSTs each result to <url>/api/ack.
-- Every command is validated here; the bot is never trusted blindly. curl runs as the
-- Termux user (never su). The secret never goes to the log.
--
-- Config:
--   remote = { url = "", secret = "", interval = 30 }   -- url or secret empty = off
--   remote.urlManual = true when the URL was typed in Menu 8 (never replaced from the repo)
--
-- The bot URL can live in remote_url.txt on GitHub: a device with a secret but no
-- url takes it from there (so only the secret has to be typed per device), and after
-- 5 failed syncs in a row the device re-reads it, so moving the bot = edit that file.

local Remote = {}

local REMOTE_URL_FILE = "https://raw.githubusercontent.com/slophisticated/rejoin2/main/remote_url.txt"
local PROTOCOL = 1

local DEVICE_ID_FILE = Paths.data("device_id.txt")
local deviceIdCache = nil
local lastSync = 0
local fastUntil = 0      -- poll every FAST_INTERVAL s until then (right after a command)
local FAST_INTERVAL = 5
local FAST_WINDOW = 120
local failures = 0
local authFails = 0      -- HWID not registered yet / secret rejected: back off too
local lastFallback = 0
local warned = {}
local versionCache = nil

local function warnOnce(key, msg)
    if warned[key] then return end
    warned[key] = true
    Logger.warn("Remote: " .. msg)
end

local function section(conf)
    conf = conf or Config.get() or {}
    conf.remote = type(conf.remote) == "table" and conf.remote or {}
    return conf.remote, conf
end

-- On as soon as the bot URL is known: the device authenticates with its HWID once the
-- owner registered it (/hwid redeem); a secret (DEVICE_SECRET / OWNERS) is optional.
function Remote.enabled()
    local r = section()
    return type(r.url) == "string" and r.url:match("^https?://") ~= nil
end

local function interval()
    local r = section()
    return math.max(10, math.floor(tonumber(r.interval) or 30))
end

-- Random id generated once per device (data/ is kept on update). Lets the bot follow a
-- device renamed from Menu 8 instead of listing the old name as a second device.
local function deviceId()
    if deviceIdCache then return deviceIdCache end
    local f = io.open(DEVICE_ID_FILE, "r")
    local id = f and f:read("*l") or nil
    if f then f:close() end
    if not (id and id:match("^%x+$") and #id >= 16 and #id <= 64) then
        local r = io.open("/dev/urandom", "rb")
        local b = r and r:read(16) or nil
        if r then r:close() end
        if b and #b == 16 then
            id = b:gsub(".", function(c) return string.format("%02x", c:byte()) end)
        else
            id = string.format("%08x%08x", math.random(0, 0x7fffffff), os.time() % 0x7fffffff)
        end
        local w = io.open(DEVICE_ID_FILE, "w")
        if w then w:write(id, "\n"); w:close() end
    end
    deviceIdCache = id
    return id
end

Remote.deviceId = deviceId

local function version()
    if versionCache then return versionCache end
    local p = io.popen("git rev-parse --short HEAD 2>/dev/null")
    versionCache = p and (p:read("*l") or "") or ""
    if p then p:close() end
    if versionCache == "" then versionCache = "-" end
    return versionCache
end

local function shq(s) return "'" .. tostring(s):gsub("'", "'\\''") .. "'" end

-- HTTP ---------------------------------------------------------------------------
-- Returns status code (number, 0 = no connection) and the body. `payload` is a table
-- sent as JSON; with `rawFile` the file is sent as-is with `contentType` instead.
local function request(path, payload, rawFile, contentType)
    local r = section()
    local base = tostring(r.url or ""):gsub("/+$", "")
    local tmp = os.getenv("TMPDIR") or "/data/data/com.termux/files/usr/tmp"
    local stamp = tostring(os.time()) .. tostring(math.random(100000, 999999))
    local hdr = tmp .. "/rejoin_remote_h_" .. stamp
    local body = tmp .. "/rejoin_remote_b_" .. stamp
    -- The header file holds the secret: create it private (0600) before writing.
    os.execute("umask 077; : > " .. shq(hdr) .. " 2>/dev/null")
    local fh = io.open(hdr, "w")
    if not fh then return 0, "" end
    fh:write("Content-Type: " .. (contentType or "application/json") .. "\n")
    if type(r.secret) == "string" and r.secret ~= "" then
        fh:write("Authorization: Bearer " .. r.secret .. "\n")
    end
    -- HWID: a device registered with /hwid redeem needs nothing else.
    fh:write("X-Rejoin-Hwid: " .. deviceId() .. "\n")
    fh:close()
    local dataFile = rawFile
    if not dataFile then
        local fb = io.open(body, "w")
        if not fb then os.remove(hdr); return 0, "" end
        fb:write(JSON.encode(payload))
        fb:close()
        dataFile = body
    end
    local cmd = "curl -s -m " .. (rawFile and "60" or "20") .. " -X POST -H @" .. shq(hdr) .. " --data-binary @" .. shq(dataFile)
        .. " -w '\\n%{http_code}' " .. shq(base .. path) .. " </dev/null 2>/dev/null"
    local p = io.popen(cmd)
    local out = p and p:read("*a") or ""
    if p then p:close() end
    os.remove(hdr)
    os.remove(body)
    local text, code = out:match("^(.*)\n(%d+)%s*$")
    return tonumber(code) or 0, text or ""
end

-- Settings the bot may read and change. Anything else is refused.
local SCHEMA = {
    { key = "launchJoinTimeout", type = "int", min = 0, max = 1800, label = "Maks tunggu clone masuk game (dtk)" },
    { key = "launchSettleDelay", type = "int", min = 0, max = 600, label = "Jeda tanpa heartbeat (dtk)" },
    { key = "launchEmptyDelay", type = "int", min = 0, max = 120, label = "Jeda clone belum login (dtk)" },
    { key = "launchWaitTimeout", type = "int", min = 5, max = 600, label = "Legacy: batas tunggu proses lama (dtk)" },
    { key = "launchWaitInterval", type = "int", min = 1, max = 60, label = "Interval cek saat launch (dtk)" },
    { key = "monitorInterval", type = "int", min = 2, max = 120, label = "Interval monitor (dtk)" },
    { key = "freezeTimeout", type = "int", min = 30, max = 7200, label = "Legacy: freezeTimeout (antrean baru tidak memakai ini)" },
    { key = "minRss", type = "int", min = 0, max = 4000, label = "Ambang RSS diagnostik saja (MB; bukan recovery)" },
    { key = "launchSafety.stableHeartbeats", type = "int", min = 2, max = 10, label = "Jumlah heartbeat baru sebelum lanjut" },
    { key = "launchSafety.stableSeconds", type = "int", min = 5, max = 300, label = "Waktu stabil minimum (dtk)" },
    { key = "launchSafety.retryCooldown", type = "int", min = 30, max = 3600, label = "Jeda retry (dtk)" },
    { key = "launchSafety.maxAttempts", type = "int", min = 1, max = 10, label = "Batas percobaan per clone" },
    { key = "relaunchNoLogin", type = "bool", label = "Buka lagi clone belum login yang FC" },
    { key = "noLoginCooldown", type = "int", min = 30, max = 3600, label = "Jeda buka lagi clone belum login (dtk)" },
    { key = "windowLayout.enabled", type = "bool", label = "Auto atur jendela (grid)" },
    { key = "windowLayout.columns", type = "int", min = 0, max = 10, label = "Kolom grid (0 = otomatis)" },
    { key = "windowLayout.gap", type = "int", min = 0, max = 200, label = "Jarak antar jendela (px)" },
    { key = "windowLayout.overlap", type = "int", min = 0, max = 400, label = "Baris atas numpuk (px)" },
    { key = "heartbeat.enabled", type = "bool", label = "Heartbeat Delta" },
    { key = "heartbeat.saver.enabled", type = "bool", label = "Mode hemat" },
    { key = "heartbeat.saver.fpsCap", type = "int", min = 0, max = 240, label = "Batas FPS mode hemat" },
    { key = "heartbeat.saver.disable3d", type = "bool", label = "Render 3D mati (mode hemat)" },
    { key = "webhook.url", type = "string", secret = true, max = 300,
      pattern = "^https://[%w%.%-]+/api/webhooks/", label = "URL Discord webhook" },
    { key = "webhook.interval", type = "int", min = 60, max = 3600, label = "Interval laporan webhook (dtk)" },
    { key = "webhook.screenshot", type = "bool", label = "Screenshot di laporan" },
    { key = "webhook.events", type = "bool", label = "Notif Delta minta key" },
    { key = "webhook.hideNames", type = "bool", label = "Sembunyikan nama akun" },
    { key = "webhook.deviceName", type = "string", max = 60, label = "Nama device" },
    { key = "deltaLicensePath", type = "string", max = 300, label = "Path file license Delta (kosong = otomatis)" },
    { key = "appAutoExecutePath", type = "string", max = 300, label = "Folder Autoexecute Delta" },
    { key = "scriptsPath", type = "string", max = 300, label = "Folder Scripts Delta (kosong = otomatis)" },
    { key = "remote.interval", type = "int", min = 10, max = 600, label = "Interval sync bot (dtk)" },
}
local SCHEMA_BY_KEY = {}
for _, s in ipairs(SCHEMA) do SCHEMA_BY_KEY[s.key] = s end
Remote.SCHEMA = SCHEMA

local function getPath(t, key)
    for part in key:gmatch("[^%.]+") do
        if type(t) ~= "table" then return nil end
        t = t[part]
    end
    return t
end

local function setPath(t, key, value)
    local parts = {}
    for part in key:gmatch("[^%.]+") do parts[#parts + 1] = part end
    for i = 1, #parts - 1 do
        if type(t[parts[i]]) ~= "table" then t[parts[i]] = {} end
        t = t[parts[i]]
    end
    t[parts[#parts]] = value
end

-- Effective value (with the same defaults the modules use).
local DEFAULTS = {
    ["launchSafety.stableHeartbeats"] = 3,
    ["launchSafety.stableSeconds"] = 20, ["launchSafety.retryCooldown"] = 120, ["launchSafety.maxAttempts"] = 3,
    launchJoinTimeout = 240, launchSettleDelay = 20, launchEmptyDelay = 5, launchWaitTimeout = 60,
    launchWaitInterval = 3, monitorInterval = 5, freezeTimeout = 300, minRss = 300,
    relaunchNoLogin = true, noLoginCooldown = 120,
    ["windowLayout.enabled"] = false, ["windowLayout.columns"] = 0, ["windowLayout.gap"] = 0,
    ["windowLayout.overlap"] = 80, ["heartbeat.enabled"] = true, ["heartbeat.saver.enabled"] = false,
    ["heartbeat.saver.fpsCap"] = 15, ["heartbeat.saver.disable3d"] = true, ["webhook.url"] = "",
    ["webhook.interval"] = 300, ["webhook.screenshot"] = true, ["webhook.events"] = true,
    ["webhook.hideNames"] = true, ["webhook.deviceName"] = "", deltaLicensePath = "",
    appAutoExecutePath = "/sdcard/Delta/Autoexecute", scriptsPath = "", ["remote.interval"] = 30,
}

local function settingsSnapshot(conf)
    local out = JSON.array({})
    for _, s in ipairs(SCHEMA) do
        local v = getPath(conf, s.key)
        if v == nil then v = DEFAULTS[s.key] end
        local e = { key = s.key, type = s.type, label = s.label, min = s.min, max = s.max }
        if s.secret then
            e.value = (type(v) == "string" and v ~= "") and "set" or ""
            e.secret = true
        else
            e.value = v
        end
        out[#out + 1] = e
    end
    return out
end

local function parseValue(s, raw)
    if s.type == "bool" then
        if type(raw) == "boolean" then return raw end
        local t = tostring(raw):lower()
        if t == "true" or t == "on" or t == "ya" or t == "1" or t == "nyala" then return true end
        if t == "false" or t == "off" or t == "tidak" or t == "0" or t == "mati" then return false end
        return nil, "harus true/false"
    elseif s.type == "int" then
        local n = tonumber(raw)
        if not n then return nil, "harus angka" end
        n = math.floor(n)
        if s.min and n < s.min then return nil, "minimal " .. s.min end
        if s.max and n > s.max then return nil, "maksimal " .. s.max end
        return n
    else
        local v = tostring(raw == nil and "" or raw):gsub("^%s+", ""):gsub("%s+$", "")
        if s.max and #v > s.max then return nil, "terlalu panjang (maks " .. s.max .. ")" end
        if v ~= "" and s.pattern and not v:match(s.pattern) then return nil, "format tidak valid" end
        return v
    end
end

-- Snapshot -------------------------------------------------------------------------
local function snapshot(instances)
    local conf = Config.get() or {}
    local okW, Webhook = pcall(require, "managers.webhook")
    local okS, Status = pcall(require, "managers.status")
    local okH, Heartbeat = pcall(require, "managers.heartbeat")
    local okU, Username = pcall(require, "managers.username")
    local okI, Instances = pcall(require, "managers.instance")

    local presets = {}
    for k, p in pairs(type(conf.presets) == "table" and conf.presets or {}) do
        if type(p) == "table" then presets[tostring(k)] = { name = p.name or "", link = p.link or "" } end
    end

    local list = JSON.array({})
    for _, inst in ipairs(instances or {}) do
        local hb = okH and Heartbeat.read and select(2, pcall(Heartbeat.read, inst)) or nil
        local key, source, link = nil, "none", inst.privateServer
        if okI and Instances.presetOf then key, source, link = Instances.presetOf(inst) end
        local p = key and presets[key] or nil
        local e = {
            id = inst.id, name = inst.name or "", package = inst.package or "",
            preset = key or "",                 -- preset actually used ("" = none)
            presetSource = source,              -- khusus / default / link / none
            game = p and p.name or (source == "link" and "link sendiri" or ""),
            link = link or "",
            logoutAlarm = type(inst.logoutAlarm) == "table" and {
                date = inst.logoutAlarm.date,
                time = inst.logoutAlarm.time,
                daily = inst.logoutAlarm.daily == true,
                nextAt = inst.logoutAlarm.nextAt,
            } or nil,
            status = okS and Status.statusOf and Status.statusOf(inst.id) or "unknown",
        }
        if okU and Username.get then
            local okN, n = pcall(Username.get, inst)
            if okN and n then e.username = n end
        end
        if type(hb) == "table" and hb.fresh then
            e.fps = hb.fps
            e.mem = hb.mem
        end
        list[#list + 1] = e
    end

    local okA, AutoExecute = pcall(require, "managers.autoexecute")
    local scripts, auto = JSON.array({}), JSON.array({})
    if okA then
        for _, s in ipairs(AutoExecute.scriptsList() or {}) do
            scripts[#scripts + 1] = { name = s.name, size = s.size, auto = s.auto and true or false }
        end
        for _, s in ipairs(AutoExecute.autoList() or {}) do
            auto[#auto + 1] = { name = s.name, size = s.size, fromScripts = s.fromScripts and true or false,
                managed = s.managed and true or false }
        end
    end

    return {
        protocol = PROTOCOL,
        scripts = scripts,
        autoexecute = auto,
        device = okW and Webhook.deviceLabel and Webhook.deviceLabel() or "-",
        deviceId = deviceId(),
        version = version(),
        time = os.time(),
        presets = presets,
        defaultPreset = conf.defaultPreset or "",
        instances = list,
        settings = settingsSnapshot(conf),
    }
end

-- Commands -------------------------------------------------------------------------
local function cloneLabel(inst) return tostring(inst.name or inst.package or inst.id) end

local function findClones(refs)
    local Instances = require("managers.instance")
    local all = Instances.getAll()
    if refs == nil or refs == "all" or (type(refs) == "table" and #refs == 0) then return all end
    if type(refs) == "string" and refs:find(",", 1, true) then
        local list = {}
        for part in refs:gmatch("[^,]+") do
            part = part:gsub("^%s+", ""):gsub("%s+$", "")
            if part ~= "" then list[#list + 1] = part end
        end
        refs = list
    end
    if type(refs) ~= "table" then refs = { refs } end
    local out, missing = {}, {}
    for _, r in ipairs(refs) do
        local inst = Instances.find(r)
        if inst then out[#out + 1] = inst else missing[#missing + 1] = tostring(r) end
    end
    if #missing > 0 then return nil, "clone tidak ditemukan: " .. table.concat(missing, ", ") end
    return out
end

local function validLink(l)
    return type(l) == "string" and (l:match("^https://[%w%.%-]*roblox%.com/") or l:match("^roblox://")) ~= nil
end

local function save(conf)
    local ok, err = Config.save(conf)
    if not ok then return false, "gagal menyimpan config: " .. tostring(err) end
    return true
end

local H = {}

function H.status(args, ctx, instances)
    local snap = snapshot(instances)
    local ingame, lines = 0, {}
    for _, e in ipairs(snap.instances) do
        if e.status == "ingame" then ingame = ingame + 1 end
        lines[#lines + 1] = string.format("%s: %s%s (%s) — %s", e.name,
            e.preset ~= "" and ("[" .. e.preset .. "] ") or "", e.game, e.presetSource, e.status)
    end
    table.insert(lines, 1, string.format("%d/%d clone di dalam game", ingame, #snap.instances))
    return true, table.concat(lines, "\n"), snap
end

local function presetOrError(key)
    local conf = Config.get() or {}
    local p = type(conf.presets) == "table" and conf.presets[key] or nil
    if type(p) ~= "table" or not validLink(p.link) then return nil, "preset '" .. tostring(key) .. "' tidak ada / link kosong" end
    return p, conf
end

-- Default preset: every clone without its own preset follows it.
function H.default_set(args, ctx)
    local key = tostring(args.preset or "")
    local p, conf = presetOrError(key)
    if not p then return false, conf end
    conf.defaultPreset = key
    local Instances = require("managers.instance")
    local ids, names = {}, {}
    for _, inst in ipairs(Instances.getAll()) do
        local _, source = Instances.presetOf(inst)
        if source == "default" then ids[#ids + 1] = inst.id; names[#names + 1] = cloneLabel(inst) end
    end
    local ok, err = save(conf)
    if not ok then return false, err end
    if args.rejoin ~= false and #ids > 0 then ctx.requestRejoin(ids) end
    return true, string.format("default → %s (%s); %d clone ikut default%s", key, p.name or "", #ids,
        (args.rejoin ~= false and #ids > 0) and (", rejoin: " .. table.concat(names, ", ")) or "")
end

-- Move clones to a preset. Without `clones` (or "all"): that preset becomes the
-- default and every clone follows it. With clones: those clones get it as their own.
function H.game(args, ctx)
    local key = tostring(args.preset or "")
    local p, conf = presetOrError(key)
    if not p then return false, conf end
    local Instances = require("managers.instance")
    if args.clones == nil or args.clones == "all" or (type(args.clones) == "table" and #args.clones == 0) then
        for _, inst in ipairs(Instances.getAll()) do inst.preset = nil end
        conf.instances = Instances.getAll()
        return H.default_set({ preset = key, rejoin = args.rejoin }, ctx)
    end
    local list, err = findClones(args.clones)
    if not list then return false, err end
    local ids, names = {}, {}
    for _, inst in ipairs(list) do
        inst.preset = key
        ids[#ids + 1] = inst.id
        names[#names + 1] = cloneLabel(inst)
    end
    local ok, e = Instances.save()
    if not ok then return false, tostring(e) end
    if args.rejoin ~= false then ctx.requestRejoin(ids) end
    return true, string.format("%s → %s (%s, khusus)%s", table.concat(names, ", "), key, p.name or "",
        args.rejoin ~= false and ", rejoin berurutan" or "")
end
H.set_preset = H.game

function H.restart(args, ctx)
    local list, err = findClones(args.clone or args.clones)
    if not list then return false, err end
    if args.clone == nil and args.clones == nil then return false, "clone wajib diisi" end
    local ids, names = {}, {}
    for _, inst in ipairs(list) do ids[#ids + 1] = inst.id; names[#names + 1] = cloneLabel(inst) end
    ctx.requestRejoin(ids)
    return true, "rejoin: " .. table.concat(names, ", ")
end

-- Log the Roblox account of the chosen clones out (cookie removed, app closed). A
-- logged-out clone is never rejoined; it only gets reopened at the login screen when
-- relaunchNoLogin is on.
function H.logout(args)
    local refs = args.clones or args.clone
    if refs == nil or refs == "all" then return false, "pilih clone yang mau di-logout (all tidak boleh)" end
    local list, err = findClones(refs)
    if not list then return false, err end
    local CookieInjector = require("managers.cookie_injector")
    local done, lines = 0, {}
    for _, inst in ipairs(list) do
        local okCall, ok, msg = pcall(CookieInjector.logout, inst)
        if okCall and ok then done = done + 1 end
        lines[#lines + 1] = cloneLabel(inst) .. ": " .. tostring(okCall and msg or "error")
    end
    return done > 0, table.concat(lines, "; ")
end

function H.cookie_inject(args, ctx)
    if ctx and ctx.launchBusy then return false, "antrean launch masih aktif; coba lagi setelah clone stabil" end
    local list, err = findClones(args.clone)
    if not list then return false, err end
    if #list ~= 1 then return false, "pilih tepat satu clone" end
    if type(args.token) ~= "string" or #args.token > 2048 or args.token:find("[%c'\" ]") then
        return false, "format cookie tidak valid"
    end
    local okCall, ok, message = pcall(require("managers.cookie_injector").inject, list[1], args.token)
    if not okCall then return false, "inject cookie gagal (error internal)" end
    return ok, tostring(message or (ok and "cookie berhasil diinjeksi" or "inject cookie gagal"))
end

-- The user supplies a key obtained from Delta. Never fetch or derive keys here.
function H.delta_key_input(args)
    if type(args.key) ~= "string" then return false, "key tidak valid" end
    local okCall, ok, message = pcall(require("managers.delta_key").input, args.key)
    if not okCall then return false, "input key Delta gagal (error internal)" end
    return ok, tostring(message or (ok and "key Delta tersimpan" or "gagal menyimpan key Delta"))
end

function H.logout_alarm_set(args)
    local list, err = findClones(args.clone)
    if not list then return false, err end
    if #list ~= 1 then return false, "pilih tepat satu clone" end
    return require("managers.logout_alarm").set(list[1].id, args.date, args.time, args.daily)
end

function H.logout_alarm_remove(args)
    local list, err = findClones(args.clone)
    if not list then return false, err end
    if #list ~= 1 then return false, "pilih tepat satu clone" end
    return require("managers.logout_alarm").remove(list[1].id)
end

function H.launch_all(args, ctx)
    ctx.requestRejoin({ "all" })
    return true, "Launch All dimulai (login duluan, satu per satu)"
end

function H.preset_set(args, ctx)
    local key = tostring(args.key or "")
    if not key:match("^[%w_]+$") or #key > 16 or key == "default" then return false, "kode preset harus huruf/angka (maks 16)" end
    if not validLink(args.link) then return false, "link harus link roblox.com atau roblox://" end
    local conf = Config.get() or {}
    conf.presets = type(conf.presets) == "table" and conf.presets or {}
    local existed = conf.presets[key] ~= nil
    conf.presets[key] = { name = tostring(args.name or key):sub(1, 60), link = args.link }
    local becameDefault = false
    if conf.defaultPreset == nil or conf.defaultPreset == "" then
        conf.defaultPreset = key
        becameDefault = true
    end
    local ok, err = save(conf)
    if not ok then return false, err end
    local Instances = require("managers.instance")
    local used = {}
    for _, inst in ipairs(Instances.getAll()) do
        if Instances.presetOf(inst) == key then used[#used + 1] = inst.id end
    end
    if args.rejoin and #used > 0 then ctx.requestRejoin(used) end
    return true, string.format("preset %s %s%s (%d clone pakai preset ini%s)", key,
        existed and "diubah" or "ditambah", becameDefault and ", jadi DEFAULT" or "", #used,
        (args.rejoin and #used > 0) and ", rejoin" or "")
end

function H.preset_remove(args)
    local key = tostring(args.key or "")
    local conf = Config.get() or {}
    if type(conf.presets) ~= "table" or conf.presets[key] == nil then return false, "preset '" .. key .. "' tidak ada" end
    if conf.defaultPreset == key then return false, "preset " .. key .. " adalah DEFAULT; set default lain dulu" end
    conf.presets[key] = nil
    local n = 0
    for _, inst in ipairs(require("managers.instance").getAll()) do
        if inst.preset == key then inst.preset = nil; n = n + 1 end
    end
    local ok, err = save(conf)
    if not ok then return false, err end
    return true, string.format("preset %s dihapus (%d clone sekarang ikut default)", key, n)
end

local function validPackage(p) return type(p) == "string" and p:match("^[%w_]+%.[%w_%.]+$") ~= nil end

function H.instance_add(args)
    if not validPackage(args.package) then return false, "package tidak valid (mis. com.apengjers.v7)" end
    local Instances = require("managers.instance")
    for _, inst in ipairs(Instances.getAll()) do
        if inst.package == args.package then return false, "package sudah ada: " .. cloneLabel(inst) end
    end
    local conf = Config.get() or {}
    local inst = { name = tostring(args.name or args.package):sub(1, 40), package = args.package }
    if args.link and args.link ~= "" then
        if not validLink(args.link) then return false, "link tidak valid" end
        inst.privateServer = args.link
    end
    if args.preset and args.preset ~= "" and args.preset ~= "default" then
        if args.preset == "-" then
            if not inst.privateServer then return false, "preset '-' butuh link" end
            inst.preset = "-"
        elseif type(conf.presets) ~= "table" or not conf.presets[args.preset] then
            return false, "preset tidak ada"
        else
            inst.preset = args.preset
        end
    end
    local ok, res = Instances.add(inst)
    if not ok then return false, tostring(res) end
    return true, "clone ditambah: " .. cloneLabel(inst) .. " (id " .. tostring(inst.id) .. ")"
end

function H.instance_edit(args)
    local Instances = require("managers.instance")
    local inst = Instances.find(args.clone)
    if not inst then return false, "clone tidak ditemukan" end
    local conf = Config.get() or {}
    if args.name ~= nil and args.name ~= "" then inst.name = tostring(args.name):sub(1, 40) end
    if args.package ~= nil and args.package ~= "" then
        if not validPackage(args.package) then return false, "package tidak valid" end
        inst.package = args.package
    end
    if args.link ~= nil and args.link ~= "" and args.link ~= "-" and not validLink(args.link) then
        return false, "link tidak valid"
    end
    if args.preset ~= nil then
        if args.preset == "" or args.preset == "default" then
            inst.preset = nil
        elseif args.preset == "-" then
            if not (inst.privateServer or (args.link and args.link ~= "" and args.link ~= "-")) then
                return false, "preset '-' (link sendiri) butuh link"
            end
            inst.preset = "-"
        elseif type(conf.presets) == "table" and conf.presets[args.preset] then
            inst.preset = args.preset
        else
            return false, "preset tidak ada"
        end
    end
    if args.link ~= nil then
        if args.link == "" or args.link == "-" then
            inst.privateServer = nil
        elseif validLink(args.link) then
            inst.privateServer = args.link
        else
            return false, "link tidak valid"
        end
    end
    local ok, err = Instances.save()
    if not ok then return false, tostring(err) end
    return true, "clone diubah: " .. cloneLabel(inst)
end

function H.instance_remove(args)
    local Instances = require("managers.instance")
    local inst = Instances.find(args.clone)
    if not inst then return false, "clone tidak ditemukan" end
    local label = cloneLabel(inst)
    local ok, err = Instances.remove(inst.id)
    if not ok then return false, tostring(err) end
    return true, "clone dihapus dari daftar: " .. label .. " (app-nya tidak di-uninstall)"
end

local function applySideEffects(key, conf)
    if key:match("^webhook%.") then
        pcall(function() require("managers.webhook").configure(conf) end)
    elseif key:match("^heartbeat%.") or key == "appAutoExecutePath" then
        pcall(function() require("managers.heartbeat").install() end)
    end
end

function H.config_set(args)
    local s = SCHEMA_BY_KEY[tostring(args.key or "")]
    if not s then return false, "setting '" .. tostring(args.key) .. "' tidak boleh diubah dari bot" end
    local v, err = parseValue(s, args.value)
    if v == nil then return false, s.key .. ": " .. tostring(err) end
    local conf = Config.get() or {}
    setPath(conf, s.key, v)
    local ok, e = save(conf)
    if not ok then return false, e end
    applySideEffects(s.key, conf)
    local shown = s.secret and (v ~= "" and "diset" or "dikosongkan") or tostring(v)
    return true, string.format("%s = %s", s.label or s.key, shown)
end

function H.device_rename(args)
    return H.config_set({ key = "webhook.deviceName", value = args.name })
end

function H.webhook_use_message(args)
    local Webhook = require("managers.webhook")
    Webhook.configure(Config.get() or {})
    local id, err = Webhook.useMessage(args.link)
    if not id then return false, tostring(err) end
    return true, "pesan status lama dipakai (id " .. id .. "), di-update di laporan berikutnya"
end

-- Screenshot of the whole cloud phone, uploaded to the bot (POST /api/upload/<id>);
-- the bot shows it in the user's ephemeral reply.
function H.screenshot(args, ctx, instances, cmd)
    if type(cmd) ~= "table" or not cmd.id then return false, "command id tidak ada" end
    local id = tostring(cmd.id)
    if not id:match("^[%w_%-]+$") then return false, "command id tidak valid" end
    local path = require("managers.webhook").captureScreen()
    if not path then return false, "screencap gagal (root?)" end
    local f = io.open(path, "rb")
    local size = f and f:seek("end") or 0
    if f then f:close() end
    local code = request("/api/upload/" .. id, nil, path, "image/png")
    if code < 200 or code >= 300 then return false, "upload screenshot gagal (HTTP " .. code .. ")" end
    return true, string.format("screenshot %d KB", math.floor(size / 1024 + 0.5)), { uploaded = true, bytes = size }
end

function H.webhook_test(args, ctx, instances)
    local Webhook = require("managers.webhook")
    Webhook.configure(Config.get() or {})
    if not Webhook.enabled() then return false, "URL webhook belum diisi" end
    local ok, res = pcall(Webhook.report, instances)
    if ok and res then return true, "laporan terkirim" end
    return false, "gagal kirim laporan (cek URL / internet)"
end

-- Scripts (Delta's Scripts folder, shared by every clone on this device). Content goes
-- to Scripts only; Autoexecute only gets a copy from Scripts (auto_add).
function H.script_add(args)
    local AutoExecute = require("managers.autoexecute")
    local content = args.content
    if (content == nil or content == "") and args.url and args.url ~= "" then
        local loader, err = AutoExecute.loaderFor(args.url)
        if not loader then return false, err end
        content = loader .. "\n"
    end
    if type(content) ~= "string" or content == "" then return false, "isi script (content) atau url wajib" end
    local n, replaced, autoUpdated = AutoExecute.scriptSave(args.name, content)
    if not n then return false, tostring(replaced) end
    return true, string.format("%s %s di Scripts (%d byte)%s", n, replaced and "diganti" or "ditambah", #content,
        autoUpdated and "; copy di Autoexecute ikut diperbarui" or "")
end

function H.script_remove(args)
    local n, stillAuto = require("managers.autoexecute").scriptRemove(args.name)
    if not n then return false, tostring(stillAuto) end
    return true, n .. " dihapus dari Scripts" .. (stillAuto and " (copy di Autoexecute masih ada; hapus dengan auto_remove)" or "")
end

function H.script_get(args)
    local content, n = require("managers.autoexecute").scriptRead(args.name)
    if not content then return false, tostring(n) end
    return true, string.format("%s (%d byte)", n, #content), { name = n, content = content }
end

function H.auto_add(args, ctx)
    local n, err = require("managers.autoexecute").autoAdd(args.name)
    if not n then return false, tostring(err) end
    if args.rejoin then ctx.requestRejoin({ "all" }) end
    return true, n .. " masuk Autoexecute" .. (args.rejoin and ", rejoin semua clone" or ", berlaku saat clone masuk game berikutnya")
end

function H.auto_remove(args, ctx)
    local n, err = require("managers.autoexecute").autoRemove(args.name)
    if not n then return false, tostring(err) end
    if args.rejoin then ctx.requestRejoin({ "all" }) end
    return true, n .. " dikeluarkan dari Autoexecute (masih ada di Scripts)" .. (args.rejoin and ", rejoin semua clone" or "")
end

Remote.handlers = H

-- Run one command table { id, type, args }. Returns ok, message, data.
function Remote.run(cmd, ctx, instances)
    if type(cmd) ~= "table" then return false, "command tidak valid" end
    local h = H[tostring(cmd.type or "")]
    if not h then return false, "command tidak dikenal: " .. tostring(cmd.type) end
    local args = type(cmd.args) == "table" and cmd.args or {}
    local ok, a, b, c = pcall(h, args, ctx or { requestRejoin = function() end }, instances, cmd)
    if not ok then return false, "error: " .. tostring(a) end
    return a, b, c
end

-- Sync -------------------------------------------------------------------------------
-- Read the bot URL from remote_url.txt on GitHub and store it when it differs.
-- Throttled to once per 10 minutes unless forced. Returns the URL found (or nil).
local function fetchRepoUrl(force)
    if not force and os.time() - lastFallback < 600 then return end
    lastFallback = os.time()
    local p = io.popen("curl -s -m 10 " .. shq(REMOTE_URL_FILE) .. " </dev/null 2>/dev/null")
    local text = p and p:read("*a") or ""
    if p then p:close() end
    local url = text:match("(https://[%w%.%-%:/_]+)")
    if not url then return end
    url = url:gsub("/+$", "")
    local r, conf = section()
    if url ~= tostring(r.url or ""):gsub("/+$", "") then
        r.url = url
        Config.save(conf)
        failures = 0
        Logger.info("Remote: URL bot pindah ke " .. url .. " (remote_url.txt)")
    end
    return url
end

local function hasUrl()
    local r = section()
    return type(r.url) == "string" and r.url:match("^https?://") ~= nil
end

-- One sync: send the snapshot, run the commands, ack each. Returns the HTTP code.
function Remote.sync(instances, ctx)
    local code, body = request("/api/sync", snapshot(instances))
    if code == 401 or code == 403 then
        authFails = authFails + 1
        warnOnce("auth", "bot belum kenal device ini (HTTP " .. code .. "): daftarkan HWID " .. deviceId()
            .. " lewat /hwid redeem di Discord (atau cek secret di Menu 8 -> 10)")
        return code
    end
    if code < 200 or code >= 300 then
        failures = failures + 1
        warnOnce("http" .. code, "sync gagal (HTTP " .. code .. ")")
        -- A URL typed in by the user (another bot) must not be swapped for this repo's one.
        if failures >= 5 and not section().urlManual then pcall(fetchRepoUrl) end
        return code
    end
    failures = 0
    authFails = 0
    warned = {}
    local data = JSON.decode(body)
    local cmds = type(data) == "table" and type(data.commands) == "table" and data.commands or {}
    local okW, Webhook = pcall(require, "managers.webhook")
    local device = okW and Webhook.deviceLabel and Webhook.deviceLabel() or "-"
    -- The user is active: answer follow-up commands quickly for a while.
    if #cmds > 0 then fastUntil = os.time() + FAST_WINDOW end
    for _, cmd in ipairs(cmds) do
        local ok, msg, extra = Remote.run(cmd, ctx, instances)
        Logger.info(string.format("Remote: %s %s -> %s %s", tostring(cmd.type), tostring(cmd.id),
            ok and "OK" or "GAGAL", (cmd.type == "cookie_inject" or cmd.type == "delta_key_input")
                and "(detail disembunyikan)" or tostring(msg)))
        request("/api/ack", {
            protocol = PROTOCOL,
            device = device,
            id = cmd.id,
            ok = ok and true or false,
            message = tostring(msg or ""),
            data = extra,
        })
    end
    return code
end

-- Called once per monitor cycle.
function Remote.tick(instances, ctx)
    -- No URL yet: take it from remote_url.txt.
    if not hasUrl() then
        local okF, url = pcall(fetchRepoUrl)
        if okF and url then warned.nourl = nil
        elseif not hasUrl() then warnOnce("nourl", "URL bot kosong dan remote_url.txt belum berisi URL") end
    end
    if not Remote.enabled() then return false end
    local now = os.time()
    -- Bot unreachable / asleep: back off (x2, x3 … up to x10) so a dead bot does not
    -- stall the monitor with curl timeouts every cycle.
    local base = (os.time() < fastUntil and failures == 0) and FAST_INTERVAL or interval()
    local wait = base * math.min(failures + authFails + 1, 10)
    if now - lastSync < wait then return false end
    lastSync = now
    Remote.sync(instances, ctx)
    return true
end

-- Menu "tes koneksi": authenticate without polling or acknowledging any commands.
-- An older bot returns 404; never fall back to sync (it would consume its queue).
function Remote.test()
    if not hasUrl() then pcall(fetchRepoUrl, true) end
    if not hasUrl() then
        return false, "URL bot kosong (isi di sini atau taruh URL di remote_url.txt repo)"
    end
    local code = request("/api/ping", { protocol = PROTOCOL })
    if code >= 200 and code < 300 then return true, "terhubung (HTTP " .. code .. ")" end
    if code == 401 or code == 403 then
        return false, "HWID " .. deviceId() .. " belum didaftarkan: ketik /hwid redeem hwid:" .. deviceId() .. " di Discord (HTTP " .. code .. ")"
    end
    if code == 0 then return false, "bot tidak bisa dihubungi (URL / internet)" end
    if code == 404 then return false, "bot belum mendukung tes koneksi ini; update bot lalu coba lagi" end
    return false, "bot membalas HTTP " .. code
end

return Remote
]=]

__ya_sources["managers.status"] = [[
local Logger = require("core.logger")
local APK = require("managers.apk")
local Auth = require("managers.auth")
local Username = require("managers.username")
local Shell = require("utils.shell")
local Heartbeat = require("managers.heartbeat")

local Status = {}

-- Per-instance runtime state.
-- instanceId -> {
--   status        = "offline"|"starting"|"ingame"|"stuck"|"freeze"|"nologin"|"recovery"
--   healthySince  = timestamp when the process was first seen running
--   stuckSince    = timestamp when stuck/freeze was first detected (5-min timeout base)
--   anrSeen       = last logcat sequence id that reported an ANR for this package
-- }
local states = {}
local lifecycle = {}
local recoveries = {}
function Status.noteRecovery(id)
    if id ~= nil then recoveries[id] = (recoveries[id] or 0) + 1 end
end
function Status.recoveryCount(id) return recoveries[id] or 0 end

-- Defaults / config gate for freeze detection.
local freezeTimeout = 300  -- seconds (RSS-low/proc-stub or ANR -> wait, then relaunch)
local gracePeriod = 30     -- seconds after healthy before judging ingame vs stuck
local anrEnabled = true

function Status.configure(conf)
    conf = conf or {}
    freezeTimeout = tonumber(conf.freezeTimeout) or 300
    gracePeriod = tonumber(conf.gracePeriod) or 30
    anrEnabled = conf.anrCheckEnabled ~= false -- default true
end

-- Current status string of an instance (for reports), or nil.
function Status.setLifecycle(id, value)
    lifecycle[id] = value
end

function Status.statusOf(id)
    return states[id] and states[id].status or nil
end

function Status.reset()
    states = {}
    lifecycle = {}
    recoveries = {}
end

-- Mark an instance as currently being recovered (so the monitor shows "recovery").
function Status.beginRecovery(id)
    local s = states[id] or {}
    s.status = "recovery"
    s.stuckSince = nil
    states[id] = s
end

function Status.endRecovery(id)
    local s = states[id]
    if s and s.status == "recovery" then
        s.status = nil
        -- A successful recovery means the app is genuinely running again; skip the
        -- "starting" grace period so it shows Running immediately on the next check.
        s.forceRunning = true
    end
end

-- Force-hold an instance in "starting" while it is being launched/loaded (used by the
-- Menu 5 sequential launch flow). Cleared with Status.endStarting when it is up.
function Status.beginStarting(id)
    local s = states[id] or {}
    s.startingOverride = true
    s.status = "starting"
    s.stuckSince = nil
    states[id] = s
end

function Status.endStarting(id)
    local s = states[id]
    if s then
        s.startingOverride = nil
    end
end

-- Mark an instance as currently being reset (force-stopped / relaunched / joined), so the
-- monitor shows "Resetting" until the operation finishes. Mirrors recovery handling.
function Status.beginResetting(id)
    local s = states[id] or {}
    s.status = "resetting"
    s.stuckSince = nil
    states[id] = s
end

function Status.endResetting(id)
    local s = states[id]
    if s and s.status == "resetting" then
        s.status = nil
    end
end

local classify

-- Update the status of a single instance based on its process state and ANR logs.
-- Returns the current status string for convenience. Every status change is written
-- to rejoin.log ([STATUS] lines) with the RSS and login state behind it.
function Status.check(instance)
    local before = states[instance.id] and states[instance.id].status
    local status = classify(instance)
    if status ~= before then
        local s = states[instance.id] or {}
        local rssMb = s.rssKb and s.rssKb >= 0 and math.floor(s.rssKb / 1024) or -1
        Logger.info(string.format("[STATUS] %s (%s): %s -> %s (rss=%dMB, login=%s)",
            tostring(instance.name or instance.id), tostring(instance.package),
            tostring(before or "-"), tostring(status), rssMb, tostring(s.lastLogin)))
    end
    return status
end

classify = function(instance)
    local id, pkg = instance.id, instance.package
    local s = states[id] or {}
    states[id] = s
    s.rssKb = pkg and APK.getRSSinKB(pkg) or -1 -- diagnostics only
    if lifecycle[id] then s.status = lifecycle[id]; return s.status end
    local ok, up = pcall(APK.isRunning, pkg)
    if not ok or up == nil then s.status = "needs_check"
    elseif not up then s.status = "offline"
    elseif Auth.isLoggedIn(instance) == false then s.status = "nologin"
    else
        local alive, why = Heartbeat.alive(instance)
        if alive == true then s.status = "ingame"
        elseif alive == false then s.status = tostring(why):find("^kicked") and "kicked" or "freeze"
        else s.status = Heartbeat.isEnabled() and "starting" or "running" end
    end
    return s.status
end

-- Whether this instance has been stuck/frozen for at least freezeTimeout seconds.
-- Returns true when it is time to relaunch.
function Status.isFreezeTimeout(id)
    local s = states[id]
    if not s then return false end
    if s.status ~= "freeze" then return false end
    if not s.stuckSince then return false end
    return (os.time() - s.stuckSince) >= freezeTimeout
end

-- ANSI colors
local C = {
    green  = "\27[32m",
    red    = "\27[31m",
    yellow = "\27[33m",
    cyan   = "\27[36m",
    blue   = "\27[34m",
    dim    = "\27[2m",
    reset  = "\27[0m",
}

-- Human label + color for a status (used by the monitor table).
local STATUS_UI = {
    queued = { "Antre", C.dim },
    stabilizing = { "Menunggu stabil", C.blue },
    wait_key = { "Menunggu key", C.yellow },
    wait_identity = { "Cek username", C.yellow },
    needs_check = { "Perlu dicek", C.red },
    cooldown = { "Jeda retry", C.yellow },
    running = { "Proses hidup", C.cyan },
    ingame   = { "Running",  C.green },
    stuck    = { "Stuck",    C.red },
    freeze   = { "Freeze",   C.yellow },
    recovery = { "Recovery", C.yellow },
    resetting= { "Resetting", C.yellow },
    starting = { "Starting", C.blue },
    offline  = { "Offline",  C.dim },
    nologin  = { "NoLogin",  C.dim },
    kicked   = { "Kicked",   C.red },
}

-- Best-effort memory + storage readout, cached to avoid shell cost every cycle.
local sysCache = { memAt = 0, memLine = nil, diskAt = 0, diskLine = nil }
local SYS_CACHE_TTL = 30

-- Read MemTotal/MemAvailable from /proc/meminfo (kB) via shell.
-- Returns a content line like "58% (860MB Free)" or nil on failure.
local function memoryLine()
    local now = os.time()
    if sysCache.memAt == 0 or (now - sysCache.memAt) >= SYS_CACHE_TTL then
        sysCache.memAt = now
        sysCache.memLine = nil
        local ok, out = Shell.exec("cat /proc/meminfo")
        if ok and out and out ~= "(dry-run)" then
            local total, avail
            for line in out:gmatch("[^\r\n]+") do
                if not total then
                    total = tonumber(line:match("MemTotal:%s*(%d+)"))
                end
                if not avail then
                    avail = tonumber(line:match("MemAvailable:%s*(%d+)"))
                end
            end
            if total and total > 0 then
                local used = avail and (total - avail) or 0
                local pct = math.floor(used / total * 100 + 0.5)
                local freeMb = avail and math.floor(avail / 1024) or 0
                sysCache.memLine = string.format("%d%% (%dMB Free)", pct, freeMb)
            end
        end
    end
    return sysCache.memLine
end

-- Read free space from `df` (best-effort). Picks the storage mount if present
-- (/sdcard, /emulated, or the root mount), else the first real block. Returns a
-- line like "300GB Free" or nil on failure.
local function storageLine()
    local now = os.time()
    if sysCache.diskAt == 0 or (now - sysCache.diskAt) >= SYS_CACHE_TTL then
        sysCache.diskAt = now
        sysCache.diskLine = nil
        local ok, out = Shell.exec("df -h 2>/dev/null")
        if ok and out and out ~= "(dry-run)" then
            local fallbackAvail
            for line in out:gmatch("[^\r\n]+") do
                -- df -h columns: Filesystem Size Used Avail Use% Mounted on
                local avail, mnt = line:match("%S+%s+%S+%s+%S+%s+(%S+)%s+%S+%%%s+(.+)")
                if avail then
                    local isWanted = mnt and (
                        mnt:find("/sdcard", 1, true) or
                        mnt:find("/emulated", 1, true) or
                        mnt == "/"
                    )
                    if isWanted then
                        sysCache.diskLine = avail .. " Free"
                        break
                    end
                    if not fallbackAvail then fallbackAvail = avail end
                end
            end
            if not sysCache.diskLine and fallbackAvail then
                sysCache.diskLine = fallbackAvail .. " Free"
            end
        end
    end
    return sysCache.diskLine
end

-- Height (in terminal rows) of the dashboard frame drawn by the last printSummary
-- call, plus the footer hint row. Used to reposition with cursor-up on the next
-- refresh instead of clearing the whole screen (avoids flicker).
local frameHeight = 0

-- Reset dashboard positioning state (called when a new monitor session starts).
function Status.resetDashboard()
    frameHeight = 0
end

-- Print a colorized status table. The first call draws the frame from the cursor
-- position and records its height; later calls move the cursor up and redraw over the
-- same rows (no full-screen clear), then clear any leftover below. Rows use CRLF so
-- the cursor returns to column 0 each line on Termux (LF alone drifts rows rightward).
-- Pad a plain string into a column cell of `width` wrapping spaces. `text` has no
-- ANSI codes so padding is based on visible characters; color is applied separately.
local function padCell(text, width)
    if #text > width - 2 then text = text:sub(1, width - 2) end
    local pad = width - 2 - #text
    local left = math.floor(pad / 2)
    return " " .. string.rep(" ", left) .. text .. string.rep(" ", pad - left) .. " "
end

local function blankCell(width)
    return string.rep(" ", width)
end

-- What the monitor is doing right now, shown in the "System" row:
-- nil = idle (monitoring), or { verb = "Checking" | "Launching", i, n }.
local progress = nil

function Status.setProgress(i, n, verb)
    if i and n then
        progress = { verb = verb or "Checking", i = i, n = n }
    else
        progress = nil
    end
end

-- "package (username)" squeezed into `width` columns: the username is shortened
-- with ".." first so the package (what identifies the clone) stays readable.
local function instanceLabel(pkg, uname, width, prefix)
    prefix = prefix or ""
    local room = width - 2 - #prefix
    if not uname or uname == "" then
        if #pkg > room then pkg = pkg:sub(1, room - 2) .. ".." end
        return prefix .. pkg
    end
    if #pkg + 3 + #uname <= room then
        return prefix .. pkg .. " (" .. uname .. ")"
    end
    local keep = room - #pkg - 5 -- " (" + ".." + ")"
    if keep >= 2 then
        return prefix .. pkg .. " (" .. uname:sub(1, keep) .. "..)"
    end
    if #pkg > room then pkg = pkg:sub(1, room - 2) .. ".." end
    return prefix .. pkg
end

-- Human-readable RSS for the dashboard: "1.2 GB" / "310 MB", or "-" when the clone has
-- no process / no reading yet. Uses the value cached by classify(), so the dashboard
-- costs zero extra shell calls.
local function rssText(rssKb)
    if not rssKb or rssKb < 0 then return "-" end
    if rssKb >= 1024 * 1024 then
        return string.format("%.1f GB", rssKb / (1024 * 1024))
    end
    if rssKb >= 1024 then
        return string.format("%d MB", math.floor(rssKb / 1024))
    end
    return string.format("%d kB", math.floor(rssKb))
end

function Status.printSummary(instances)
    local LCOL = 33   -- width of the left (Instance) column
    local RCOL = 23   -- width of the status column
    local RSSCOL = 14 -- width of the RSS column

    local top  = "╭" .. string.rep("─", LCOL) .. "┬" .. string.rep("─", RCOL)
        .. "┬" .. string.rep("─", RSSCOL) .. "╮"
    local mid  = "├" .. string.rep("─", LCOL) .. "┼" .. string.rep("─", RCOL)
        .. "┼" .. string.rep("─", RSSCOL) .. "┤"
    local bot  = "╰" .. string.rep("─", LCOL) .. "┴" .. string.rep("─", RCOL)
        .. "┴" .. string.rep("─", RSSCOL) .. "╯"

    -- One body row. `rightColor`, if given, colors the visible status text only so
    -- every row still aligns on the same column. `rss` is the rightmost cell.
    local function bodyRow(left, rightText, rightColor, rss)
        local lc = padCell(left, LCOL)
        local rc = padCell(rightText, RCOL)
        if rightColor then
            local l = math.floor((RCOL - 2 - #rightText) / 2)
            rc = " " .. string.rep(" ", l) .. rightColor .. rightText .. C.reset
                 .. string.rep(" ", (RCOL - 2 - #rightText) - l) .. " "
        end
        local rc2 = padCell(rss or "", RSSCOL)
        return "│" .. lc .. "│" .. rc .. "│" .. rc2 .. "│"
    end

    local function blankRow()
        return "│" .. blankCell(LCOL) .. "│" .. blankCell(RCOL) .. "│" .. blankCell(RSSCOL) .. "│"
    end

    local sb = {}
    table.insert(sb, top)
    table.insert(sb, bodyRow("Instance", "Status", nil, "RSS"))
    table.insert(sb, mid)

    -- System rows first, like a status header for the whole device.
    if progress then
        table.insert(sb, bodyRow("System", string.format("%s [%d/%d]", progress.verb, progress.i, progress.n), C.yellow))
    else
        table.insert(sb, bodyRow("System", "Monitoring", C.green))
    end
    table.insert(sb, bodyRow("Memory", memoryLine() or "--"))
    table.insert(sb, bodyRow("Storage", storageLine() or "--"))
    table.insert(sb, mid)

    local totalRssKb = 0
    if not instances or #instances == 0 then
        table.insert(sb, bodyRow("(no instances)", "Offline", C.dim))
    else
        for _, inst in ipairs(instances) do
            local id = inst.id or inst.name or "?"
            local pkg = inst.package or inst.name or tostring(id)
            local s = states[id]
            local status = s and s.status or "offline"
            local ui = STATUS_UI[status] or { status, C.dim }
            local label = ui[1] or "Unknown"
            if status == "ingame" then
                local extra = Heartbeat.summary(inst)
                if extra then label = label .. " " .. extra end
            end
            local uname = nil
            pcall(function() uname = Username.get(inst) end)
            local okW, WindowLayout = pcall(require, "managers.window_layout")
            local wv = okW and WindowLayout.lastVerify(inst.package) or nil
            local prefix = (wv and wv.ok == false) and "[win] " or ""
            local rowText = instanceLabel(pkg, uname and tostring(uname) or nil, LCOL, prefix)
            local rss = s and s.rssKb or -1
            if rss > 0 then totalRssKb = totalRssKb + rss end
            table.insert(sb, bodyRow(rowText, label, ui[2], rssText(rss)))
        end
    end
    table.insert(sb, bodyRow("App RAM (total)", totalRssKb > 0 and rssText(totalRssKb) or "--"))
    table.insert(sb, bot)

    -- Footer hint below the table.
    table.insert(sb, " ")
    table.insert(sb, C.dim .. "(tekan Ctrl+C untuk berhenti)" .. C.reset)

    -- Reposition on top of the previous frame if we already drew one, then redraw.
    if frameHeight > 0 then
        io.write("\27[" .. frameHeight .. "A")
    end
    io.write("\27[?25l")                                  -- hide cursor (smoother refresh)
    io.write(table.concat(sb, "\r\n") .. "\r\n")          -- CRLF so every row resets column
    io.write("\27[J")                                     -- clear any leftover below
    frameHeight = #sb                                     -- full frame incl. footer
    io.write("\27[?25h")                                  -- show cursor again
    io.flush()
end

return Status
]]

__ya_sources["managers.uninstall"] = [[
local File = require("utils.file")
local Logger = require("core.logger")
local Paths = require("core.paths")
local Boot = require("managers.boot")

-- Full uninstall for the single-file loader.
--
-- Removes everything the tool owns, and nothing else:
--   1. the Termux:Boot script (~/.termux/boot/start-rejoin.sh)
--   2. the whole data root (/sdcard/yanamin: config + data + all logs)
--   3. the engine/loader file itself — but only when it is the single-file
--      loader. When the running entry is main.lua (the repo checkout) the file
--      is left alone on purpose: deleting it would wreck the source tree.
--
-- Clone app data, AutoExecute scripts and anything else on the device are never
-- touched.

local Uninstall = {}

local function shellQuote(s)
    return "'" .. tostring(s or ""):gsub("'", "'\\''") .. "'"
end

-- The file this process is running from, if it is safe to delete.
function Uninstall.selfRemovable()
    local self = Boot.selfPath()
    if not self then return nil, "tidak tahu file yang sedang jalan" end
    local name = self:match("([^/\\]+)$")
    if name == "main.lua" then
        return nil, "file engine main.lua tidak dihapus (hapus manual bila perlu)"
    end
    if not File.exists(self) then
        return nil, "file " .. self .. " tidak ditemukan"
    end
    return self, name
end

-- Everything that would be deleted, for the confirmation screen.
function Uninstall.targets()
    local list = {}

    local bootScript = Boot.scriptPath()
    if File.exists(bootScript) then
        table.insert(list, { path = bootScript, what = "auto-boot (Termux:Boot)" })
    end

    local base = Paths.base()
    if File.exists(base .. "/config/config.lua") or File.exists(base .. "/data") then
        table.insert(list, { path = base, what = "data root (config + data + log)" })
    end

    local self, why = Uninstall.selfRemovable()
    if self then
        table.insert(list, { path = self, what = "file loader" })
    else
        table.insert(list, { path = nil, what = "file loader: TIDAK dihapus (" .. tostring(why) .. ")" })
    end

    return list
end

-- Do the actual removal. Returns a list of human-readable results.
function Uninstall.runAll()
    local results = {}

    -- 1) Termux:Boot script
    local okBoot, infoBoot = Boot.uninstall()
    if okBoot then
        table.insert(results, "Auto-boot dihapus: " .. tostring(infoBoot))
    else
        table.insert(results, "Auto-boot: " .. tostring(infoBoot))
    end

    -- 2) data root (config + data + logs)
    local base = Paths.base()
    os.execute("rm -rf " .. shellQuote(base))
    if File.exists(base) then
        table.insert(results, "GAGAL hapus data root: " .. base)
    else
        table.insert(results, "Data root dihapus: " .. base)
    end

    -- 3) the loader file itself
    local self = Uninstall.selfRemovable()
    if self then
        local removed = os.remove(self)
        if removed then
            table.insert(results, "File loader dihapus: " .. self)
        else
            table.insert(results, "GAGAL hapus file loader: " .. self)
        end
    else
        table.insert(results, "File loader tidak dihapus (hapus manual bila perlu)")
    end

    Logger.info("Uninstall: " .. table.concat(results, " | "))
    return results
end

return Uninstall]]

__ya_sources["managers.username"] = [=[
local Logger = require("core.logger")
local File = require("utils.file")
local Shell = require("utils.shell")
local Auth = require("managers.auth")
local Paths = require("core.paths")

local Username = {}

local cache = {}
local TTL_OK   = 600  -- seconds before re-resolving a successful result
local TTL_FAIL = 60   -- seconds before retrying after a failure / nil
local LOG_PATH = Paths.data("username_scan.log")

local function trim(s)  return (s or ""):match("^%s*(.-)%s*$") end

local function logLine(str)
    if not str or str == "" then return end
    local f = io.open(LOG_PATH, "a")
    if f then f:write(str .. "\n"); f:close() end
end

-- Extract the .ROBLOSECURITY token from the clone's data dir (root required).
-- The token value is `_|WARNING:-DO-NOT-SHARE!<random>`, so we grab from "WARNING:" on.
local function extractToken(base)
    local cmd = "grep -a -r -o -E 'WARNING:-DO-NOT-SHARE![A-Za-z0-9_=:.-]{10,}' '" .. base .. "' 2>/dev/null | head -1"
    local ok, _, raw = pcall(function() return Shell.exec(cmd) end)
    if not ok or not raw or raw == "" or raw == "(dry-run)" then return nil end
    return raw:match("(WARNING%-DO%-NOT%-SHARE%![A-Za-z0-9_=:%.:%-]+)")
end

-- Resolve the username from the Roblox public authenticated-user API.
local function resolveViaApi(token)
    local cmd = "curl -s --max-time 3 -H 'Cookie: .ROBLOSECURITY=" .. token .. "' https://users.roblox.com/v1/users/authenticated"
    local ok, _, out = pcall(function() return Shell.exec(cmd) end)
    if not ok or not out or out == "" or out == "(dry-run)" then return nil end
    return out:match('"name"%s*:%s*"([^"]*)"') or out:match('"displayName"%s*:%s*"([^"]*)"')
end

-- Fallback: scan known light dirs for username/account keys.
local function resolveLocal(base)
    local q = "[\"']"
    local cmd = "grep -a -r -i -E '(userName|username|displayName|accountName|playerName)[[:space:]]*[:=][[:space:]]*"
        .. q .. "?[A-Za-z0-9_]{3,32}" .. q .. "?' --include='*.xml' --include='*.json' --include='*.txt' --include='*.log' '"
        .. base .. "/shared_prefs' '" .. base .. "/files' 2>/dev/null | head -1"
    local ok, _, out = pcall(function() return Shell.exec(cmd) end)
    if not ok or not out or out == "" or out == "(dry-run)" then return nil end
    local _, val = out:match('(username|userName|displayName|accountName|playerName)%s*[:=]%s*["\']?([A-Za-z0-9_]{3,32})')
    return val
end

-- Reset the username cache and (re)create the evidence log.
function Username.reset()
    cache = {}
    local f = io.open(LOG_PATH, "w")
    if f then
        f:write("-- username scan evidence log " .. os.date("%Y-%m-%d %H:%M:%S") .. "\n")
        f:close()
    end
end

-- Resolve the Roblox username for a single instance. Returns a string or nil.
function Username.get(instance)
    if not instance then return nil end
    local pkg = instance.package
    if not pkg then return nil end

    local cached = cache[pkg]
    if cached then
        if os.time() - cached.at < (cached.username and TTL_OK or TTL_FAIL) then
            return cached.username
        end
    end

    -- Manual override via a file whose first line is the username.
    if instance.usernamePath and instance.usernamePath ~= "" then
        local content = File.read(instance.usernamePath)
        local u = content and trim(content:match("^[^\n]+"))
        if u and #u > 0 then
            cache[pkg] = { username = u, at = os.time() }
            return u
        end
    end

    local username = nil
    local base = "/data/data/" .. pkg
    local ev = string.format("[%s] pkg=%s", os.date("%H:%M:%S"), pkg)

    -- Reuse the name from Auth's Roblox check so the token is not sent twice.
    local fromAuth = Auth.remoteName(pkg)
    if fromAuth then
        ev = ev .. " auth=" .. fromAuth
        username = fromAuth
    end

    local token = not username and extractToken(base) or nil
    ev = ev .. " token=" .. tostring(token and #token or 0)
    if token then
        local apiUser = resolveViaApi(token)
        ev = ev .. " api=" .. tostring(apiUser)
        username = apiUser
    end

    if not username then
        local localUser = resolveLocal(base)
        ev = ev .. " local=" .. tostring(localUser)
        username = localUser
    end

    logLine(ev)
    cache[pkg] = { username = username, at = os.time() }
    return username
end

-- Warm the cache for all instances (non-blocking per individual error).
function Username.prefetch(instances)
    for _, inst in ipairs(instances or {}) do
        pcall(function() Username.get(inst) end)
    end
end

return Username]=]

__ya_sources["managers.webhook"] = [[
local Paths = require("core.paths")
local Logger = require("core.logger")
local Shell = require("utils.shell")

-- Status reports to a Discord webhook.
--
-- Every `interval` seconds the monitor calls Webhook.tick(): one status message
-- (device, RAM / CPU / temperature, online count, uptime / memory / CPU per clone,
-- optional screenshot) is posted once and then EDITED in place, so the channel holds
-- a single live status. If that message was deleted, a new one is posted. Events
-- (engine start, kick, failed recovery) are sent as separate small messages.
--
-- Config:
--   webhook = {
--       url = "",          -- Discord webhook URL; "" = feature off (nothing runs)
--       interval = 300,    -- seconds between status updates
--       screenshot = true, -- attach a screenshot of the cloud phone
--       events = true,     -- separate messages for engine start / kick / failures
--       hideNames = true,  -- show account names as spoilers
--   }
--
-- curl runs as the Termux user (not through su), so the webhook URL never appears in
-- a root command line, and it is never written to the log.

local Webhook = {}

local conf = {}
local lastReport = 0
local firstReportAt = nil
local warned = {}
local eventLast = {}
local cpuPrev = nil      -- { total, idle }
local procPrev = {}      -- pkg -> { proc, total }
-- Id of the status message we keep editing. It lives in the DATA ROOT, like every other
-- file this tool owns. It used to be the relative "data/webhook_msg.txt", which landed in
-- a different folder depending on how the engine was started (repo folder when launched
-- from the menu, data root when launched by the boot script, the download folder for the
-- single-file loader). When that folder did not exist the write failed silently, the id
-- was never stored and every report posted a NEW message instead of editing the old one.
local STATE_FILE = Paths.data("webhook_msg.txt")
local STATE_FILE_LEGACY = "data/webhook_msg.txt"
local PIDS_FILE = Paths.data("clone_pids.txt")
local pidSeen = nil
local TMP = (os.getenv("PREFIX") or "/data/data/com.termux/files/usr") .. "/tmp"
local SHOT = TMP .. "/rejoin_ss.png"
local PAYLOAD = TMP .. "/rejoin_webhook.json"
-- Linux proc stat starttime uses USER_HZ. Android devices are usually 100, but
-- query the running environment so elapsed process time stays correct on variants.
local HZ = nil


-- Accept any real Discord webhook URL. The token is base64url and often contains "_",
-- which the previous pattern ([%w%.%-]) rejected -- silently disabling the whole feature
-- with no log line at all.
local URL_OK = "^https://[%w%.%-%_]+/api/webhooks/%S+$"

local function warnOnce(key, msg)
    if warned[key] then return end
    warned[key] = true
    Logger.warn("Webhook: " .. msg)
end

function Webhook.configure(c)
    local w = type(c) == "table" and type(c.webhook) == "table" and c.webhook or {}
    conf = {
        url = type(w.url) == "string" and w.url:gsub("%s+", "") or "",
        interval = math.max(60, math.floor(tonumber(w.interval) or 300)),
        screenshot = w.screenshot ~= false,
        events = w.events ~= false,
        hideNames = w.hideNames ~= false,
        deviceName = type(w.deviceName) == "string" and w.deviceName:gsub("^%s+", ""):gsub("%s+$", "") or "",
    }
    if not conf.url:match(URL_OK) then
        -- A non-empty URL we refuse is almost always a paste we don't understand, and
        -- before this the whole feature just went quiet. Say so in the log.
        if conf.url ~= "" then
            Logger.warn("Webhook: URL tidak valid, webhook dimatikan")
        end
        conf.url = ""
    end
    lastReport = 0
    firstReportAt = os.time() + 30
end

function Webhook.enabled()
    return conf.url ~= nil and conf.url ~= ""
end

-- JSON string escaping.
local function js(s)
    s = tostring(s or "")
    s = s:gsub('[%c"\\]', function(ch)
        if ch == '"' then return '\\"' end
        if ch == "\\" then return "\\\\" end
        if ch == "\n" then return "\\n" end
        if ch == "\r" then return "" end
        if ch == "\t" then return "\\t" end
        return string.format("\\u%04x", ch:byte())
    end)
    return '"' .. s .. '"'
end
Webhook._js = js

local function shQuote(v)
    return "'" .. tostring(v):gsub("'", "'\\''") .. "'"
end

-- Run curl as the Termux user. Returns http code (number or nil) and body.
--
-- The binary is resolved explicitly: this runs through io.popen (NOT su), so it uses the
-- Termux PATH, and a bare "curl" silently does nothing when curl is not installed or the
-- prefix differs. Same candidate list as managers/auth.lua.
local curlBin = nil -- nil = not probed yet, false = none available

local function resolveCurl()
    if curlBin ~= nil then return curlBin end
    for _, c in ipairs({
        "/data/data/com.termux/files/usr/bin/curl",
        "/system/bin/curl",
    }) do
        local f = io.popen("[ -x '" .. c .. "' ] && echo AE_YES || echo AE_NO 2>/dev/null")
        local out = f and f:read("*l") or ""
        if f then f:close() end
        if out and out:find("AE_YES", 1, true) then
            curlBin = c
            Logger.info("Webhook: pakai curl " .. c)
            return curlBin
        end
    end
    curlBin = "curl" -- last resort: whatever PATH has
    return curlBin
end

local function curl(args)
    local cmd = resolveCurl() .. " -s --max-time 25 -w '\\n%{http_code}' " .. args .. " </dev/null 2>/dev/null"
    local f = io.popen(cmd)
    if not f then return nil, "" end
    local out = f:read("*a") or ""
    f:close()
    local body, code = out:match("^(.-)\n?(%d%d%d)%s*$")
    return tonumber(code), body or out
end

local function writeFile(path, content)
    local f = io.open(path, "w")
    if not f then return false end
    f:write(content)
    f:close()
    return true
end

local function readFile(path)
    local f = io.open(path, "r")
    if not f then return nil end
    local s = f:read("*a")
    f:close()
    return s
end

local function root(cmd)
    local ok, out = Shell.exec(cmd)
    if not ok or not out or out == "(dry-run)" then return nil end
    return out
end

local function clockTicks()
    if HZ then return HZ end
    local out = root("getconf CLK_TCK 2>/dev/null")
    HZ = tonumber(out and out:match("(%d+)") or "") or 100
    if HZ <= 0 then HZ = 100 end
    return HZ
end

local function parseElapsed(raw)
    raw = tostring(raw or ""):match("^%s*(.-)%s*$")
    local seconds = tonumber(raw)
    if seconds then return seconds end
    local days, hours, minutes, secs = raw:match("^(%d+)%-(%d+):(%d+):(%d+)$")
    if days then return tonumber(days) * 86400 + tonumber(hours) * 3600 + tonumber(minutes) * 60 + tonumber(secs) end
    hours, minutes, secs = raw:match("^(%d+):(%d+):(%d+)$")
    if hours then return tonumber(hours) * 3600 + tonumber(minutes) * 60 + tonumber(secs) end
    minutes, secs = raw:match("^(%d+):(%d+)$")
    if minutes then return tonumber(minutes) * 60 + tonumber(secs) end
    return nil
end

local function processElapsed(pid)
    local value = parseElapsed(root("ps -o ELAPSED= -p " .. pid))
    if not value then value = parseElapsed(root("ps -o etime= -p " .. pid)) end
    if not value then value = parseElapsed(root("ps -o etimes= -p " .. pid)) end
    return value and value > 0 and value or nil
end

-- System numbers ------------------------------------------------------------------
local function cpuTotals()
    local stat = root("cat /proc/stat")
    if not stat then return nil end
    local line = stat:match("^cpu%s+([^\n]+)")
    if not line then return nil end
    local nums = {}
    for n in line:gmatch("%d+") do nums[#nums + 1] = tonumber(n) end
    local total = 0
    for _, n in ipairs(nums) do total = total + n end
    local idle = (nums[4] or 0) + (nums[5] or 0)
    local cores = 0
    for _ in stat:gmatch("\ncpu%d+ ") do cores = cores + 1 end
    return total, idle, math.max(cores, 1)
end

local modelCache = nil
local function model()
    if not modelCache then
        modelCache = (root("getprop ro.product.model") or ""):gsub("%s+$", "")
        if modelCache == "" then modelCache = "-" end
    end
    return modelCache
end

-- Label shown in the report title and Device line. Empty labels fall back to the
-- Android model so existing configurations remain readable without a label.
function Webhook.deviceLabel()
    if conf.deviceName and conf.deviceName ~= "" then return conf.deviceName end
    return model()
end

local function systemStats()
    local s = {}
    s.device = Webhook.deviceLabel()

    local mem = root("cat /proc/meminfo") or ""
    local total = tonumber(mem:match("MemTotal:%s*(%d+)"))
    local avail = tonumber(mem:match("MemAvailable:%s*(%d+)"))
    if total and avail and total > 0 then
        s.ram = string.format("%dMB free (%d%%)", math.floor(avail / 1024), math.floor(avail * 100 / total))
    else
        s.ram = "-"
    end

    local t, idle, cores = cpuTotals()
    s.cores = cores or 1
    s.cpuTotal = t
    if t and cpuPrev and t > cpuPrev.total then
        local dt, di = t - cpuPrev.total, idle - cpuPrev.idle
        s.cpu = string.format("%d%%", math.floor((dt - di) * 100 / dt + 0.5))
    else
        s.cpu = "-"
    end
    if t then cpuPrev = { total = t, idle = idle } end

    local temps = root("cat /sys/class/thermal/thermal_zone*/temp 2>/dev/null") or ""
    local best
    for n in temps:gmatch("%-?%d+") do
        local v = tonumber(n)
        if v and v > 1000 then v = v / 1000 end
        if v and v > 0 and v < 150 and (not best or v > best) then best = v end
    end
    s.temp = best and string.format("%.1f°C", best) or "-"

    s.uptime = tonumber((root("cat /proc/uptime") or ""):match("^(%d+%.?%d*)"))
    return s
end

-- Uptime as "8h 31m" / "3d 4h", seconds for a process younger than a minute ("42dtk") and
-- "-" when it cannot be read. The old version floored to minutes, so any clone that had
-- been (re)started in the last 60s showed a misleading "0m" -- which is exactly what a
-- relaunch loop looks like from Discord.
local function fmtDuration(sec)
    if not sec or sec <= 0 then return "-" end
    sec = math.max(1, math.floor(sec))
    if sec < 60 then return string.format("%ddtk", sec) end
    local d, h, m = math.floor(sec / 86400), math.floor(sec % 86400 / 3600), math.floor(sec % 3600 / 60)
    if d > 0 then return string.format("%dd %dh", d, h) end
    if h > 0 then return string.format("%dh %dm", h, m) end
    return string.format("%dm", m)
end

-- Runtime fallback: when /proc gives nonsense (Redfinger runs Android in a container:
-- /proc/uptime counts from the cloud phone's boot, starttime from the host's), count
-- from the moment the pid was first seen, or from this engine's launch of the clone.
-- Saved in data/clone_pids.txt so an engine restart keeps counting.
local function loadPids()
    if pidSeen then return end
    pidSeen = {}
    for line in (readFile(PIDS_FILE) or ""):gmatch("[^\n]+") do
        local pkg, pid, since = line:match("^(%S+)%s+(%d+)%s+(%d+)$")
        if pkg then pidSeen[pkg] = { pid = pid, since = tonumber(since) } end
    end
end

local function savePids()
    local lines = {}
    for pkg, e in pairs(pidSeen) do lines[#lines + 1] = pkg .. " " .. e.pid .. " " .. e.since end
    table.sort(lines)
    writeFile(PIDS_FILE, table.concat(lines, "\n") .. "\n")
end

local function seenSince(pkg, pid)
    loadPids()
    local e = pidSeen[pkg]
    if e and e.pid == pid then return e.since end
    local since = os.time()
    local okH, Heartbeat = pcall(require, "managers.heartbeat")
    local launched = okH and Heartbeat.launchedAt and Heartbeat.launchedAt({ package = pkg })
    if launched and launched <= since and since - launched < 600 then since = launched end
    pidSeen[pkg] = { pid = pid, since = since }
    savePids()
    return since
end

-- Uptime and CPU of one clone's main process, from /proc/<pid>/stat.
local function procStats(pkg, sys)
    if type(pkg) ~= "string" or not pkg:match("^[%w_%.]+$") then return nil end
    local pid = (root("pidof " .. pkg) or ""):match("(%d+)")
    if not pid then return nil end
    local r = { uptime = processElapsed(pid) }
    local stat = root("cat /proc/" .. pid .. "/stat")
    if not stat then return r end
    local rest = stat:match("%)%s+(.*)$")
    if not rest then return r end
    local f = {}
    for v in rest:gmatch("%S+") do f[#f + 1] = v end
    -- after ") ": state is field 3, utime 14, stime 15, starttime 22 (1-based in /proc docs)
    local utime, stime, start = tonumber(f[12]), tonumber(f[13]), tonumber(f[20])
    -- Prefer Android's elapsed-time probe; fall back to proc time, then the
    -- persisted first-seen PID time on containers with incompatible clocks.
    if not r.uptime and start and sys.uptime then
        local elapsed = sys.uptime - start / clockTicks()
        if elapsed >= 0 and elapsed <= sys.uptime + 60 then r.uptime = elapsed end
    end
    if not r.uptime then r.uptime = math.max(0, os.time() - seenSince(pkg, pid))
    end
    if utime and stime then
        local proc = utime + stime
        local prev = procPrev[pkg]
        if prev and sys.cpuTotal and sys.cpuTotal > prev.total and proc >= prev.proc then
            local share = (proc - prev.proc) / ((sys.cpuTotal - prev.total) / sys.cores)
            r.cpu = string.format("%.1f%%", share * 100)
        end
        procPrev[pkg] = { proc = proc, total = sys.cpuTotal or 0 }
    end
    return r
end

-- Report body ---------------------------------------------------------------------
local ICON = {
    queued = "⏳", stabilizing = "🟡", wait_key = "🔑",
    wait_identity = "❔", needs_check = "⚠️", cooldown = "⏳", running = "🟡",
    ingame = "🟢", starting = "🟡", recovery = "🟡", resetting = "🟡",
    nologin = "⚪", kicked = "🔴", freeze = "🔴", stuck = "🔴", offline = "🔴",
}

local function buildReport(instances, sys, withImage)
    local okS, Status = pcall(require, "managers.status")
    local okU, Username = pcall(require, "managers.username")
    local okH, Heartbeat = pcall(require, "managers.heartbeat")
    local okA, APK = pcall(require, "managers.apk")

    local online, offline, nologin = 0, 0, 0
    local rows = {}
    for _, inst in ipairs(instances or {}) do
        local status = okS and Status.statusOf and Status.statusOf(inst.id) or "offline"
        status = status or "offline"
        if status == "ingame" then online = online + 1
        elseif status == "nologin" then nologin = nologin + 1
        else offline = offline + 1 end

        local name = okU and Username.get(inst) or nil
        if not name or tostring(name) == "" then name = inst.name or inst.package end
        name = tostring(name)
        if conf.hideNames then name = "||" .. name .. "||" end

        local p = procStats(inst.package, sys) or {}
        local memMb
        local hb = okH and Heartbeat.read and Heartbeat.read(inst) or nil
        if hb and hb.fresh and hb.mem and hb.mem > 0 then
            memMb = hb.mem
        elseif okA then
            local kb = APK.getRSSinKB(inst.package)
            if kb and kb > 0 then memMb = math.floor(kb / 1024) end
        end
        -- Restart counter for this run: makes a relaunch loop obvious in the channel
        -- (a clone that keeps restarting shows a growing ♻️ instead of a quiet "0m").
        local restarts = (okS and Status.recoveryCount and Status.recoveryCount(inst.id)) or 0
        rows[#rows + 1] = string.format("%s %s%s\n└ ⏱️ %s | 💾 %s | ⚡ %s%s",
            ICON[status] or "⚪", name,
            restarts > 0 and string.format(" ♻️%d", restarts) or "",
            p.uptime and fmtDuration(p.uptime) or "-",
            memMb and (memMb .. " MB") or "-",
            p.cpu or "-",
            restarts > 0 and string.format(" | ♻️ %dx restart", restarts) or "")
    end

    local now = os.time()
    local lines = {
        string.format("Last Updated: <t:%d:f> (<t:%d:R>)", now, now),
        "",
        "📱 **Device** - " .. sys.device,
        "",
        "🖥️ **System Stats**",
        "💾 RAM: " .. sys.ram,
        "⚙️ CPU: " .. sys.cpu,
        "🌡️ Temp: " .. sys.temp,
        "",
        "**Status Overview**",
        "🟢 Online: " .. online,
        "🔴 Offline: " .. offline,
    }
    if nologin > 0 then lines[#lines + 1] = "⚪ Belum login: " .. nologin end
    lines[#lines + 1] = "🤖 Total: " .. #(instances or {})
    lines[#lines + 1] = ""
    lines[#lines + 1] = "**Application Details**"
    local desc = table.concat(lines, "\n")
    for i, r in ipairs(rows) do
        if #desc + #r + 40 > 4000 then
            desc = desc .. string.format("\n… +%d clone lagi", #rows - i + 1)
            break
        end
        desc = desc .. "\n" .. r
    end

    local color = 5763719 -- green
    if online == 0 then color = 15548997 elseif offline > 0 then color = 16705372 end
    local embed = '{"title":' .. js("📊 Rejoin Status Update - " .. Webhook.deviceLabel())
        .. ',"description":' .. js(desc)
        .. ',"color":' .. color
        .. ',"timestamp":' .. js(os.date("!%Y-%m-%dT%H:%M:%SZ", now))
    if withImage then embed = embed .. ',"image":{"url":"attachment://rejoin_ss.png"}' end
    embed = embed .. "}"
    local payload = '{"embeds":[' .. embed .. ']'
    if withImage then
        payload = payload .. ',"attachments":[{"id":0,"filename":"rejoin_ss.png"}]'
    else
        payload = payload .. ',"attachments":[]'
    end
    return payload .. "}"
end
Webhook._buildReport = buildReport

local function screenshot()
    os.execute("mkdir -p " .. shQuote(TMP))
    local out = root("screencap -p " .. shQuote(SHOT) .. " && chmod 644 " .. shQuote(SHOT) .. " && echo SS_OK")
    if not out or not out:find("SS_OK", 1, true) then return false end
    local f = io.open(SHOT, "rb")
    if not f then return false end
    local size = f:seek("end")
    f:close()
    return size and size > 0
end

-- Take a screenshot of the cloud phone now (also used by the bot's /screenshot).
-- Returns the PNG path, or nil.
function Webhook.captureScreen()
    if screenshot() then return SHOT end
    return nil
end

-- Message id of the status message we keep editing.
--
-- Falls back to the old relative location once, so an install that already stored the
-- id there keeps editing its existing message instead of posting a new one.
local function msgId()
    local s = readFile(STATE_FILE)
    if not s and STATE_FILE_LEGACY ~= STATE_FILE then
        s = readFile(STATE_FILE_LEGACY)
        if s then
            local id = s:match("(%d+)")
            if id then
                writeFile(STATE_FILE, id .. "\n")
                os.remove(STATE_FILE_LEGACY)
                Logger.info("Webhook: id pesan dipindah ke data root: " .. STATE_FILE)
            end
            return id
        end
    end
    return s and s:match("(%d+)")
end

function Webhook.messageId() return msgId() end

-- Keep editing an existing status message (e.g. the one an old / replaced device left
-- behind) instead of posting a new one. Takes a message link
-- (https://discord.com/channels/<guild>/<channel>/<message>) or a bare message id.
function Webhook.useMessage(input)
    local id
    for digits in tostring(input or ""):gmatch("%d+") do
        if #digits >= 15 and #digits <= 22 then id = digits end
    end
    if not id then return nil, "link / ID pesan tidak valid" end
    writeFile(STATE_FILE, id .. "\n")
    Logger.info("Webhook: pakai pesan status yang sudah ada")
    return id
end

-- The message's own "id": the "id" key of the top-level JSON object. Discord's key
-- order is not fixed and nested objects (author, attachments, embeds) have ids too,
-- so walk the JSON tracking depth instead of matching neighbours.
local function parseId(body)
    if type(body) ~= "string" then return nil end
    local depth, i, n = 0, 1, #body
    while i <= n do
        local c = body:sub(i, i)
        if c == '"' then
            local j = i + 1
            while j <= n do
                local cj = body:sub(j, j)
                if cj == "\\" then j = j + 2
                elseif cj == '"' then break
                else j = j + 1 end
            end
            if depth == 1 and body:sub(i + 1, j - 1) == "id" then
                local v = body:match('^%s*:%s*"(%d+)"', j + 1)
                if v then return v end
            end
            i = j + 1
        elseif c == "{" or c == "[" then
            depth = depth + 1
            i = i + 1
        elseif c == "}" or c == "]" then
            depth = depth - 1
            i = i + 1
        else
            i = i + 1
        end
    end
    return nil
end
Webhook._parseId = parseId

local function send(payload, withImage, method, url)
    if not writeFile(PAYLOAD, payload) then
        os.execute("mkdir -p " .. shQuote(TMP))
        if not writeFile(PAYLOAD, payload) then return nil, "" end
    end
    local args = "-X " .. method .. " "
    if withImage then
        args = args .. "-F " .. shQuote("payload_json=<" .. PAYLOAD)
            .. " -F " .. shQuote("files[0]=@" .. SHOT .. ";filename=rejoin_ss.png;type=image/png")
    else
        args = args .. "-H 'Content-Type: application/json' --data-binary " .. shQuote("@" .. PAYLOAD)
    end
    return curl(args .. " " .. shQuote(url))
end

-- Post or edit the status message now.
-- CPU numbers need two samples. Before the very first report, take one and wait a
-- moment, so the first report already shows CPU instead of "-".
local function primeCpu(instances)
    local t, idle, cores = cpuTotals()
    if not t then return end
    cpuPrev = { total = t, idle = idle }
    local sys = { cpuTotal = t, cores = cores }
    for _, inst in ipairs(instances or {}) do
        pcall(procStats, inst.package, sys)
    end
    os.execute("sleep 2")
end

function Webhook.report(instances)
    if not Webhook.enabled() then return false end
    if not cpuPrev then primeCpu(instances) end
    local sys = systemStats()
    local withImage = conf.screenshot and screenshot() or false
    local payload = buildReport(instances, sys, withImage)

    local id = msgId()
    if id then
        local code = send(payload, withImage, "PATCH", conf.url .. "/messages/" .. id)
        if code and code >= 200 and code < 300 then return true end
        -- Any failed edit (401/403 from another webhook token, 400 from a stale payload,
        -- 404 when the message was deleted) invalidates the stored id. Keeping it made
        -- the webhook fail the very same way forever, with no new message ever posted.
        warnOnce("edit" .. tostring(code), "update pesan gagal (HTTP " .. tostring(code or "?") .. "), buat pesan baru")
        os.remove(STATE_FILE)
        os.remove(STATE_FILE_LEGACY)
    end
    local code, body = send(payload, withImage, "POST", conf.url .. "?wait=true")
    if not code or code < 200 or code >= 300 then
        warnOnce("post" .. tostring(code), "kirim laporan gagal (HTTP " .. tostring(code or "?") .. ")")
        return false
    end
    local newId = parseId(body)
    if newId then
        writeFile(STATE_FILE, newId .. "\n")
        Logger.info("Webhook: pesan status dibuat")
    else
        warnOnce("noid", "id pesan tidak terbaca; laporan berikutnya jadi pesan baru")
    end
    return true
end

-- Called once per monitor cycle; reports when the interval has passed.
function Webhook.tick(instances)
    if not Webhook.enabled() then return false end
    local now = os.time()
    if firstReportAt and now < firstReportAt then return false end
    if lastReport > 0 and now - lastReport < conf.interval then return false end
    lastReport = now
    local ok, res = pcall(Webhook.report, instances)
    if not ok then warnOnce("err", "error: " .. tostring(res)) end
    return ok and res
end

-- Separate event message, e.g. Delta asking for a key (rate-limited per key: at most
-- one per 60s).
function Webhook.event(key, title, text, color)
    if not Webhook.enabled() or not conf.events then return false end
    local now = os.time()
    if eventLast[key] and now - eventLast[key] < 60 then return false end
    eventLast[key] = now
    local payload = '{"embeds":[{"title":' .. js(title .. " — " .. Webhook.deviceLabel()) .. ',"description":' .. js(text or "")
        .. ',"color":' .. tostring(color or 16705372)
        .. ',"timestamp":' .. js(os.date("!%Y-%m-%dT%H:%M:%SZ", now)) .. '}]}'
    local ok, code = pcall(send, payload, false, "POST", conf.url)
    if not ok or not code or code < 200 or code >= 300 then
        warnOnce("event" .. tostring(code), "kirim event gagal (HTTP " .. tostring(code or "?") .. ")")
        return false
    end
    return true
end

return Webhook
]]

__ya_sources["managers.window_layout"] = [=[
local Logger = require("core.logger")
local Shell = require("utils.shell")
local Config = require("core.config")

-- Arranges the clones' floating windows in a grid.
--
-- The App Cloner floating window keeps its bounds in
--   /data/data/<pkg>/shared_prefs/<pkg>_preferences.xml
-- as app_cloner_current_window_{left,top,right,bottom} (pixels). We rewrite those
-- four values ONLY while the clone is force-stopped (right before it is launched), so
-- the window opens where we want it and the running app never fights our write.
--
-- Config (all optional):
--   windowLayout = {
--       enabled = true,    -- on in the shipped config; installer turns it on
--       columns = 0,       -- 0 = automatic (2 columns for 2-4 clones, 3 for 5-9, ...)
--       gap = 0,           -- pixels between windows
--       offsetTop = 0,     -- pixels kept free at the top of the screen
--       overlap = 80,      -- pixels every row except the last reaches into the row
--                          -- below it, so a small window shows the whole Roblox
--                          -- sidebar (up to "More"). With overlap the rows are filled
--                          -- bottom-up: windows launched later open on top, so the
--                          -- taller upper row covers the edge of the row below.
--                          -- 0 = plain grid, filled top-down.
--       screenWidth = 0,   -- 0 = detect from the current display
--       screenHeight = 0,
--       orientation = "landscape", -- grid in landscape even if the display reads
--                                  -- portrait (e.g. right after boot); "auto" = as read
--   }
--   Per instance: window = { left = 0, top = 0, right = 640, bottom = 360 } overrides
--   the grid for that clone.
--
-- Best-effort: any failure is logged and the launch continues as normal.
--
-- Validation: after every write the four values are read back, and while a clone runs
-- WindowLayout.verify() compares the bounds the app reports in its prefs with the grid.
-- A window found out of place is only reported; it is put back on the clone's next
-- launch (recovery / relaunch / boot), never by restarting a running game.

local WindowLayout = {}

local KEYS = { "left", "top", "right", "bottom" }
local KEY_PREFIX = "app_cloner_current_window_"

local screenCache = nil      -- first detected size is held for the whole process
local topInsetCache = nil    -- first detected inset is held for the whole process
local DEFAULT_OVERLAP = 80
local TOLERANCE = 10          -- pixels the app may adjust a window by
local lastVerify = {}         -- pkg -> { ok, at, actual, target }

local function layoutConf()
    local ok, conf = pcall(Config.get)
    conf = ok and type(conf) == "table" and conf or {}
    local wl = type(conf.windowLayout) == "table" and conf.windowLayout or {}
    return wl, conf
end

function WindowLayout.isEnabled()
    local wl = layoutConf()
    return wl.enabled == true
end

local function validPackage(pkg)
    return type(pkg) == "string" and pkg:match("^[%a_][%w_%.]*$") ~= nil
end

local function shQuote(v)
    return "'" .. tostring(v):gsub("'", "'\\''") .. "'"
end

-- Display size for the grid. Keep the first detected size for this process so Android
-- reporting transient dimensions during rotation/window transitions cannot move later
-- clone slots. Set screenWidth/screenHeight to pin dimensions across restarts.
local function screenSize(wl)
    local w, h = tonumber(wl.screenWidth), tonumber(wl.screenHeight)
    if w and h and w > 0 and h > 0 then return w, h end
    if screenCache then return screenCache[1], screenCache[2] end
    local a, b
    local ok, out = Shell.exec("dumpsys window displays")
    if ok and out then
        local cw, ch = out:match("cur=(%d+)x(%d+)")
        a, b = tonumber(cw), tonumber(ch)
    end
    if not a then
        ok, out = Shell.exec("wm size")
        local pw, ph = (out or ""):match("(%d+)x(%d+)")
        a, b = tonumber(pw), tonumber(ph)
    end
    if not a or not b then return nil end
    if wl.orientation ~= "auto" then
        a, b = math.max(a, b), math.min(a, b)
    end
    screenCache = { a, b }
    return a, b
end

-- Find the top system-bar/cutout area so a grid that uses offsetTop=0 still
-- starts below Android's notification bar. Prefer the actual StatusBar window
-- frame; fall back to stable insets, then 24dp at the device density.
local function systemTopInset()
    if topInsetCache then return topInsetCache end

    local inset = 0
    local ok, out = Shell.exec("dumpsys window windows")
    if ok and out and out ~= "(dry-run)" then
        local start = out:find("Window #%d+[^\r\n]-StatusBar")
        if start then
            local nextWindow = out:find("\nWindow #", start + 1, true)
            local block = out:sub(start, nextWindow or (start + 1800))
            for line in block:gmatch("[^\r\n]+") do
                local l, t, r, b = line:match("[Ff]rame=%[(-?%d+),%s*(-?%d+)%]%[(-?%d+),%s*(-?%d+)%]")
                l, t, r, b = tonumber(l), tonumber(t), tonumber(r), tonumber(b)
                if l and t == 0 and r and b and b > 0 and (r - l) >= b then
                    inset = math.max(inset, b)
                end
            end
        end
    end

    if inset == 0 then
        ok, out = Shell.exec("dumpsys window displays")
        if ok and out and out ~= "(dry-run)" then
            local stable = tonumber(out:match("mStableInsets=Rect%(%-?%d+,%s*(%-?%d+)%s*%-%s*%-?%d+,%s*%-?%d+%)"))
            local cutout = tonumber(out:match("DisplayCutout%{insets=Rect%(%-?%d+,%s*(%-?%d+)%s*%-%s*%-?%d+,%s*%-?%d+%)"))
            inset = math.max(stable or 0, cutout or 0)
        end
    end

    if inset == 0 then
        ok, out = Shell.exec("wm density")
        local density = ok and tonumber((out or ""):match("density:%s*(%d+)")) or nil
        inset = density and math.floor(24 * density / 160 + 0.5) or 24
    end

    inset = math.max(0, math.floor(inset)) + 2 -- small safety margin for app-cloner rounding
    topInsetCache = inset
    return topInsetCache
end
local function prefsFile(pkg)
    return "/data/data/" .. pkg .. "/shared_prefs/" .. pkg .. "_preferences.xml"
end

-- The four window values currently stored in the clone's prefs, or nil.
local function readBounds(pkg)
    local ok, out = Shell.exec("cat " .. shQuote(prefsFile(pkg)) .. " 2>/dev/null")
    if not ok or not out or out == "" or out == "(dry-run)" then return nil end
    local b = {}
    for _, k in ipairs(KEYS) do
        local v = out:match('<int name="' .. KEY_PREFIX .. k .. '" value="(%-?%d+)"')
        b[k] = tonumber(v)
        if not b[k] then return nil end
    end
    return b
end
WindowLayout.readBounds = readBounds

local function sameBounds(a, b)
    if not a or not b then return false end
    for _, k in ipairs(KEYS) do
        if math.abs((a[k] or 0) - (b[k] or 0)) > TOLERANCE then return false end
    end
    return true
end

local function fmt(b)
    if not b then return "?" end
    return string.format("%d,%d,%d,%d", b.left, b.top, b.right, b.bottom)
end
WindowLayout.formatBounds = fmt

-- `am force-stop` returns before every process of the package is gone, and a dying
-- app can still flush its old window bounds. Wait until it is really stopped.
local function waitStopped(pkg)
    local okA, APK = pcall(require, "managers.apk")
    if not okA then return true end
    local okT, Timer = pcall(require, "utils.timer")
    for attempt = 1, 4 do
        local okR, running = pcall(APK.isRunning, pkg)
        if okR and not running then return true end
        if attempt == 3 then pcall(APK.forceStop, pkg) end
        if okT then Timer.sleep(1) end
    end
    local okR, running = pcall(APK.isRunning, pkg)
    return okR and not running
end

-- Bounds for the clone at 1-based position `index` out of `count`.
function WindowLayout.boundsFor(instance, index, count)
    local wl = layoutConf()
    local o = type(instance) == "table" and instance.window or nil
    if type(o) == "table" then
        local b = {}
        for _, k in ipairs(KEYS) do
            b[k] = tonumber(o[k])
            if not b[k] then return nil, "window." .. k .. " missing" end
        end
        return b
    end

    local sw, sh = screenSize(wl)
    if not sw then return nil, "screen size unknown" end
    count = math.max(1, count or 1)
    local cols = math.floor(tonumber(wl.columns) or 0)
    if cols < 1 then cols = math.ceil(math.sqrt(count)) end
    local rows = math.ceil(count / cols)
    local gap = math.max(0, math.floor(tonumber(wl.gap) or 0))
    -- offsetTop remains a user-requested margin, but zero can no longer place
    -- windows under Android's status bar.
    local requestedTop = math.max(0, math.floor(tonumber(wl.offsetTop) or 0))
    local fixedInset = tonumber(wl.topInset)
    local safeInset = fixedInset and fixedInset > 0 and math.floor(fixedInset) or systemTopInset()
    local top0 = math.max(requestedTop, safeInset)

    local cellW = math.floor((sw - gap * (cols - 1)) / cols)
    local cellH = math.floor((sh - top0 - gap * (rows - 1)) / rows)
    if cellW < 50 or cellH < 50 then return nil, "grid too small" end

    local overlap = math.max(0, math.floor(tonumber(wl.overlap) or DEFAULT_OVERLAP))
    if rows < 2 then overlap = 0 end
    overlap = math.min(overlap, math.floor(cellH / 2))

    local i = index - 1
    local col, row = i % cols, math.floor(i / cols)
    if overlap > 0 then row = rows - 1 - row end
    local left = col * (cellW + gap)
    local top = top0 + row * (cellH + gap)
    local bottom = top + cellH
    if row < rows - 1 then bottom = bottom + overlap end
    return { left = left, top = top, right = left + cellW, bottom = bottom }
end

-- Write the bounds into the clone's prefs. Call only while the clone is stopped.
function WindowLayout.apply(instance, index, count)
    if not WindowLayout.isEnabled() then return false, "disabled" end
    local pkg = instance and instance.package
    if not validPackage(pkg) then return false, "invalid_package" end

    local b, err = WindowLayout.boundsFor(instance, index, count)
    if not b then
        Logger.warn("WindowLayout[" .. pkg .. "]: " .. tostring(err))
        return false, err
    end
    if not waitStopped(pkg) then
        Logger.warn("WindowLayout[" .. pkg .. "]: app masih jalan, posisi tidak ditulis")
        return false, "still running"
    end

    -- Drop any existing entries for the four keys, then add fresh ones before </map>.
    -- The result is written back with `cat >` so the file keeps its inode, owner,
    -- permissions and SELinux label (the app must still be able to read/write it).
    local sedArgs, entries = {}, {}
    for _, k in ipairs(KEYS) do
        local name = KEY_PREFIX .. k
        sedArgs[#sedArgs + 1] = "-e " .. shQuote("s#<int name=\"" .. name .. "\" value=\"[^\"]*\" */>##g")
        entries[#entries + 1] = string.format('<int name="%s" value="%d" />', name, b[k])
    end
    sedArgs[#sedArgs + 1] = "-e " .. shQuote("s#</map>#" .. table.concat(entries) .. "</map>#")
    sedArgs[#sedArgs + 1] = "-e " .. shQuote("/^[[:space:]]*$/d")

    -- Android loads <file>.bak instead of the file when a previous write was cut off,
    -- so a leftover backup gets the same edit.
    --
    -- A clone that was never opened has no prefs file yet (common on a fresh device):
    -- create an empty one with the same owner, mode and SELinux label as the app's data
    -- directory, so the app can read and write it like its own, then edit it as usual.
    local file = prefsFile(pkg)
    local tmp = "/data/local/tmp/rejoin_window_" .. pkg .. ".xml"
    local script = table.concat({
        "f=" .. shQuote(file) .. "; t=" .. shQuote(tmp),
        "d=" .. shQuote("/data/data/" .. pkg) .. '; sp="$d/shared_prefs"',
        'if [ ! -f "$f" ]; then',
        '  [ -d "$d" ] || exit 3',
        '  own=$(stat -c "%u:%g" "$d") || exit 6',
        '  ctx=$(ls -Zd "$d" 2>/dev/null | awk \'{print $1}\')',
        '  if [ ! -d "$sp" ]; then mkdir "$sp" && chown "$own" "$sp" && chmod 771 "$sp" || exit 6; fi',
        '  printf "%s\\n%s\\n%s\\n" "<?xml version=\'1.0\' encoding=\'utf-8\' standalone=\'yes\' ?>" "<map>" "</map>" > "$f" || exit 6',
        '  chown "$own" "$f" && chmod 660 "$f" || exit 6',
        '  case "$ctx" in *:*) chcon "$ctx" "$sp" "$f" 2>/dev/null ;; esac',
        '  echo CREATED',
        'fi',
        "edit() {",
        "  sed " .. table.concat(sedArgs, " ") .. ' "$1" > "$t" || return 4',
        '  grep -q "' .. KEY_PREFIX .. 'left" "$t" || { rm -f "$t"; return 5; }',
        '  cat "$t" > "$1"; rc=$?; rm -f "$t"; return $rc',
        "}",
        'edit "$f" || exit $?',
        'if [ -f "$f.bak" ]; then edit "$f.bak" || exit $?; fi',
        "exit 0",
    }, "\n")
    -- Shell.exec prefixes `timeout`; run the compound script as one command.
    local ok, out, code = Shell.exec("sh -c " .. shQuote(script))
    if not ok then
        local reason = code == 3 and "app data folder not found (clone not installed?)"
            or code == 6 and "could not create prefs file"
            or ("write failed (code " .. tostring(code) .. ") " .. tostring(out or ""))
        Logger.warn("WindowLayout[" .. pkg .. "]: " .. reason)
        return false, reason
    end
    if out and out:find("CREATED", 1, true) then
        Logger.info("WindowLayout[" .. pkg .. "]: file setting jendela dibuat (clone belum pernah dibuka)")
    end
    local stored = readBounds(pkg)
    if not sameBounds(stored, b) then
        Logger.warn(string.format("[WINDOW] %s: tulis %s tapi terbaca %s", pkg, fmt(b), fmt(stored)))
        return false, "read-back mismatch"
    end
    Logger.info(string.format("WindowLayout[%s]: window #%d/%d -> left=%d top=%d right=%d bottom=%d",
        pkg, index or 1, count or 1, b.left, b.top, b.right, b.bottom))
    lastVerify[pkg] = nil
    return true
end

-- Compare the bounds the running app keeps in its prefs with this clone's grid slot.
-- Returns true | false, actual, target | nil (feature off, or nothing to compare yet).
function WindowLayout.verify(instance)
    if not WindowLayout.isEnabled() then return nil end
    local pkg = instance and instance.package
    if not validPackage(pkg) then return nil end
    local index, count = WindowLayout.slotOf(instance)
    local target = WindowLayout.boundsFor(instance, index, count)
    local actual = readBounds(pkg)
    if not target or not actual then return nil end
    local ok = sameBounds(actual, target)
    lastVerify[pkg] = { ok = ok, at = os.time(), actual = actual, target = target }
    if ok then return true end
    return false, actual, target
end

-- Last verify() result for the dashboard (no I/O).
function WindowLayout.lastVerify(pkg)
    return lastVerify[pkg]
end

-- Position of `instance` in the configured list (by package), and the list size.
function WindowLayout.slotOf(instance)
    local _, conf = layoutConf()
    local list = type(conf.instances) == "table" and conf.instances or {}
    local count, index = 0, nil
    for _, inst in ipairs(list) do
        count = count + 1
        if type(inst) == "table" and inst.package == (instance and instance.package) then
            index = index or count
        end
    end
    return index or 1, math.max(count, 1)
end

-- Convenience for callers: apply for this instance at its configured slot. Never throws.
function WindowLayout.applyForInstance(instance)
    if not WindowLayout.isEnabled() then return false end
    local okCall, ok = pcall(function()
        local index, count = WindowLayout.slotOf(instance)
        return WindowLayout.apply(instance, index, count)
    end)
    if not okCall then
        Logger.warn("WindowLayout: error " .. tostring(ok))
        return false
    end
    return ok
end

return WindowLayout
]=]

__ya_sources["scripts.rejoin_heartbeat"] = [=[
-- REJOIN_HEARTBEAT v3: account identity + per-launch session, loading is explicit.
-- Installed automatically by rejoin into the executor's autoexecute folder.
-- Edits here are overwritten: change the settings in rejoin (Settings > 13) instead.
--
-- Every few seconds it writes this account's in-game status to
--   <workspace>/rejoin/hb_<username>.txt
-- so rejoin knows the clone is really in a game, and reacts at once to a kick or
-- disconnect. The optional saver mode lowers CPU/GPU/memory use.

local CFG = --[[REJOIN_CFG]]{
    interval = 10,
    folder = "rejoin",
    saver = false,
    disable3d = true,
    fpsCap = 15,
    lowGraphics = true,
    mute = true,
}--[[/REJOIN_CFG]]

local env = (getgenv and getgenv()) or _G
if env.__rejoin_heartbeat then return end
env.__rejoin_heartbeat = true

local function safe(f, ...)
    local ok, r = pcall(f, ...)
    if ok then return r end
    return nil
end

if not game:IsLoaded() then game.Loaded:Wait() end

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local GuiService = game:GetService("GuiService")
local Stats = game:GetService("Stats")

local lp = Players.LocalPlayer
while not lp do
    task.wait(1)
    lp = Players.LocalPlayer
end

-- Saver mode ---------------------------------------------------------------
if CFG.saver then
    if CFG.disable3d then
        safe(function() RunService:Set3dRenderingEnabled(false) end)
    end
    if CFG.fpsCap and CFG.fpsCap > 0 and setfpscap then
        safe(setfpscap, CFG.fpsCap)
    end
    if CFG.lowGraphics then
        safe(function() settings().Rendering.QualityLevel = Enum.QualityLevel.Level01 end)
        safe(function()
            UserSettings():GetService("UserGameSettings").SavedQualityLevel = Enum.SavedQualitySetting.QualityLevel1
        end)
    end
    if CFG.mute then
        safe(function() UserSettings():GetService("UserGameSettings").MasterVolume = 0 end)
    end
end

-- Kick / disconnect detection ------------------------------------------------
local state, reason = "ingame", ""

local function checkError()
    local msg = safe(function() return GuiService:GetErrorMessage() end)
    if msg and msg ~= "" then
        state = "kicked"
        reason = msg
    end
end

safe(function() GuiService.ErrorMessageChanged:Connect(checkError) end)
checkError()
task.spawn(function()
    safe(function()
        local prompt = game:GetService("CoreGui"):WaitForChild("RobloxPromptGui", 30)
        local overlay = prompt and prompt:WaitForChild("promptOverlay", 30)
        if overlay then
            overlay.ChildAdded:Connect(function(child)
                if child.Name == "ErrorPrompt" then
                    state = "kicked"
                    task.wait(1)
                    checkError()
                end
            end)
        end
    end)
end)

-- Heartbeat file -------------------------------------------------------------
local frames = 0
RunService.Heartbeat:Connect(function() frames = frames + 1 end)

if makefolder and isfolder and not safe(isfolder, CFG.folder) then
    safe(makefolder, CFG.folder)
end
local path = CFG.folder .. "/hb_" .. string.lower(lp.Name) .. ".txt"
local request = {}
if readfile then
    local text = safe(readfile, CFG.folder .. "/start_" .. string.lower(lp.Name) .. ".txt") or ""
    for line in text:gmatch("[^\r\n]+") do
        local k, v = line:match("^(%w+)=(.*)$")
        if k then request[k] = v end
    end
end
-- Bind once. A script from an old app session must never adopt a later launch token.
local session = request.name == lp.Name:lower() and request.session or nil
if not (session and session:match("^[%w_%-]+$")) then
    session = "manual_" .. tostring(os.time()) .. "_" .. tostring(math.random(100000, 999999))
    request.package = ""
end
local sequence = 0
state = state == "kicked" and "kicked" or "loading"

local last = os.clock()
local function write()
    sequence = sequence + 1
    local now = os.clock()
    local fps = math.floor(frames / math.max(now - last, 0.001) + 0.5)
    frames, last = 0, now
    local ping = safe(function() return lp:GetNetworkPing() end) or 0
    local mem = safe(function() return Stats:GetTotalMemoryUsageMb() end) or 0
    local lines = {
        "name=" .. lp.Name,
        "userid=" .. tostring(lp.UserId),
        "placeid=" .. tostring(game.PlaceId),
        "jobid=" .. tostring(game.JobId),
        "session=" .. session,
        "package=" .. tostring(request.package or ""),
        "seq=" .. tostring(sequence),
        "time=" .. tostring(os.time()),
        "state=" .. state,
        "reason=" .. (tostring(reason):gsub("[\r\n=]", " ")),
        "fps=" .. tostring(fps),
        "ping=" .. tostring(math.floor(ping * 1000)),
        "mem=" .. tostring(math.floor(mem)),
    }
    if writefile then safe(writefile, path, table.concat(lines, "\n")) end
end

-- Publish loading/kick progress while waiting. No timeout is allowed to claim ingame.
task.spawn(function()
    while env.__rejoin_heartbeat do
        write()
        task.wait(CFG.interval)
    end
end)
local ContentProvider = game:GetService("ContentProvider")
local idle = 0
while env.__rejoin_heartbeat and state ~= "kicked" do
    local ch = lp.Character
    local spawned = ch ~= nil and ch:FindFirstChild("HumanoidRootPart") ~= nil
    local q = safe(function() return ContentProvider.RequestQueueSize end)
    idle = (spawned and type(q) == "number" and q == 0) and idle + 1 or 0
    if idle >= 5 then state = "ingame"; break end
    task.wait(1)
end
]=]

__ya_sources["utils.android"] = [[
local Logger = require("core.logger")
local Shell = require("utils.shell")

local Android = {}

local function quote(value)
    return "'" .. tostring(value):gsub("'", "'\\''") .. "'"
end

function Android.forceStop(packageName)
    local ok, APK = pcall(require, "managers.apk")
    if not ok then return false, "apk_manager_unavailable" end
    return APK.forceStop(packageName)
end

function Android.launch(packageName)
    Logger.info("Android: launching " .. tostring(packageName))
    -- am start MAIN/LAUNCHER targeting the package explicitly first: it starts the
    -- package's own launcher task and does not depend on `cmd package resolve-activity`
    -- (often unavailable in a Termux non-adb/non-root shell). monkey is the fallback.
    local cmd = string.format("am start -a android.intent.action.MAIN -c android.intent.category.LAUNCHER -p %s", packageName)
    local ok, out = Shell.exec(cmd)
    if ok and out then
        local failed = false
        for _, h in ipairs({ "Error", "Failure", "Exception", "does not exist", "Activity not started" }) do
            if out:find(h, 1, true) then failed = true break end
        end
        if not failed then
            Logger.info("Android: am start accepted for " .. tostring(packageName))
            return true
        end
    end

    cmd = string.format("monkey -p %s -c android.intent.category.LAUNCHER 1", packageName)
    ok, out = Shell.exec(cmd)
    if ok and out and out:find("Events injected", 1, true) then
        Logger.info("Android: monkey launch injected events for " .. tostring(packageName))
        return true
    end
    cmd = string.format("cmd package resolve-activity --brief %s", packageName)
    local rok, rout = Shell.exec(cmd)
    local component = nil
    if rok and rout then
        for line in rout:gmatch("[^\r\n]+") do
            local comp = line:match("(%S+%/%S+)")
            if comp then component = comp break end
        end
    end
    if component then
        Logger.info("Android: fallback resolved component: " .. tostring(component))
        Shell.exec(string.format("am start -n %s", component))
    end
    return false
end

-- Open a URL. When packageName is provided, the VIEW intent is delivered to that
-- clone package (-p <pkg>). On-device probing showed this per-clone form
--     am start -a VIEW -d 'roblox://placeId=<id>' -p <clone>
-- both auto-joins the map AND uses the right clone/account, whereas the untargeted
-- form only reaches a single default handler and -n <pkg>/...ActivityProtocolLaunch
-- only showed the game page.
--
-- A failed targeted launch must not open the default clone/account.
function Android.openURL(url, packageName)
    Logger.info("Android: opening URL " .. tostring(url) .. " (pkg=" .. tostring(packageName) .. ")")

    local function accepted(ok, out)
        if not ok or not out then return false end
        for _, hint in ipairs({ "Error", "Failure", "Exception", "Activity not started" }) do
            if out:find(hint, 1, true) then return false end
        end
        return true
    end

    -- 1) Targeted clone package.
    if packageName and packageName ~= "" then
        local ok, out = Shell.exec(string.format("am start -a android.intent.action.VIEW -d %s -p %s", quote(url), quote(packageName)))
        if accepted(ok, out) then
            Logger.info("Android: openURL via targeted package (" .. tostring(packageName) .. ")")
            return true, out
        end
        Logger.warn("Android: targeted openURL failed for " .. tostring(packageName) .. ": " .. tostring(out))
        return false, out
    end

    -- 2) Untargeted.
    local ok, out = Shell.exec(string.format("am start -a android.intent.action.VIEW -d %s", quote(url)))
    return accepted(ok, out), out
end

return Android
]]

__ya_sources["utils.file"] = [[
local lfs_ok, lfs = pcall(require, "lfs")
local File = {}

local function ensureDirForPath(path)
    if not path then return end
    local dir = path:match("^(.*)[/\\]")
    if not dir or dir == "" then return end
    -- Try lfs.mkdir if available
    if lfs_ok and lfs and lfs.mkdir then
        -- create nested dirs
        local cur = ""
        for part in dir:gmatch("[^/\\]+") do
            cur = (cur == "") and part or (cur .. "/" .. part)
            if lfs.attributes(cur) == nil then
                pcall(lfs.mkdir, cur)
            end
        end
        return
    end
    -- Fallback to shell mkdir -p (Android/Termux/Linux)
    pcall(function() os.execute("mkdir -p '" .. dir .. "'") end)
end

function File.exists(path)
    if not path then return false end
    local f = io.open(path, "r")
    if f then f:close(); return true end
    return false
end

function File.read(path)
    local f = io.open(path, "r")
    if not f then return nil, "not_found" end
    local content = f:read("*a")
    f:close()
    return content
end

function File.write(path, content)
    ensureDirForPath(path)
    local f = io.open(path, "w")
    if not f then return false, "open_failed" end
    f:write(content)
    f:close()
    return true
end

function File.copy(src, dest)
    if not src or not dest then return false, "invalid_args" end
    local content, err = File.read(src)
    if not content then return false, err end
    ensureDirForPath(dest)
    return File.write(dest, content)
end

-- List file names (optionally filtered by extension) inside a directory.
-- Returns a table of names (sorted), or nil on failure. Uses lfs when available,
-- falling back to a shell `ls` (works on Termux/Android).
function File.listDir(path, ext)
    if not path or path == "" then return nil, "no_dir" end
    local names = {}
    if lfs_ok and lfs and lfs.dir then
        local ok, it, state = pcall(lfs.dir, path)
        if ok and it then
            for name in it, state do
                if name ~= "." and name ~= ".." then
                    if not ext or name:sub(-#ext - 1) == "." .. ext then
                        table.insert(names, name)
                    end
                end
            end
            table.sort(names)
            return names
        end
        return nil, "lfs_dir_failed"
    end
    -- Fallback: shell ls with the extension filter.
    local okc, out = pcall(function()
        local cmd = string.format("ls -1 '%s' 2>/dev/null", path)
        if ext then cmd = string.format("ls -1 '%s'/*.%s 2>/dev/null", path, ext) end
        local f = io.popen(cmd)
        if not f then return "" end
        local s = f:read("*a") or ""
        f:close()
        return s
    end)
    if not okc then return nil, "ls_failed" end
    for line in (out or ""):gmatch("[^\r\n]+") do
        if line ~= "" then
            local base = line:match("([^/\\]+)$")
            if base then table.insert(names, base) end
        end
    end
    table.sort(names)
    return names
end

return File
]]

__ya_sources["utils.json"] = [[
-- JSON helper: prefer cjson if available, else a small pure-Lua encoder/decoder
-- (enough for the remote bot protocol: objects, arrays, strings, numbers, booleans).
local ok, cjson = pcall(require, "cjson")
local JSON = {}

-- Mark a table as a JSON array (so an empty table encodes as [] instead of {}).
local ARRAY = setmetatable({}, { __mode = "k" })
function JSON.array(t)
    t = t or {}
    ARRAY[t] = true
    return t
end

if ok and cjson then
    function JSON.encode(t) return cjson.encode(t) end
    function JSON.decode(s)
        local okD, v = pcall(cjson.decode, s)
        if okD then return v end
        return nil, tostring(v)
    end
    return JSON
end

local ESC = { ['"'] = '\\"', ['\\'] = '\\\\', ['\b'] = '\\b', ['\f'] = '\\f',
              ['\n'] = '\\n', ['\r'] = '\\r', ['\t'] = '\\t' }

local function encodeString(s)
    return '"' .. s:gsub('[%c"\\]', function(c)
        return ESC[c] or string.format("\\u%04x", c:byte())
    end) .. '"'
end

local function isArray(t)
    if ARRAY[t] then return true end
    local n = 0
    for k in pairs(t) do
        if type(k) ~= "number" or k < 1 or k % 1 ~= 0 then return false end
        n = n + 1
    end
    return n > 0 and n == #t
end

local encode
encode = function(v, seen)
    local tp = type(v)
    if tp == "nil" then return "null" end
    if tp == "boolean" then return tostring(v) end
    if tp == "number" then
        if v ~= v or v == math.huge or v == -math.huge then return "null" end
        if v % 1 == 0 and v >= -2^53 and v <= 2^53 then return string.format("%d", v) end
        return string.format("%.14g", v)
    end
    if tp == "string" then return encodeString(v) end
    if tp == "table" then
        seen = seen or {}
        if seen[v] then error("JSON.encode: circular table") end
        seen[v] = true
        local parts = {}
        if isArray(v) then
            for i = 1, #v do parts[#parts + 1] = encode(v[i], seen) end
            seen[v] = nil
            return "[" .. table.concat(parts, ",") .. "]"
        end
        local keys = {}
        for k in pairs(v) do keys[#keys + 1] = tostring(k) end
        table.sort(keys)
        for _, k in ipairs(keys) do
            local val = v[k]
            if val == nil then val = v[tonumber(k)] end
            if type(val) ~= "function" then
                parts[#parts + 1] = encodeString(k) .. ":" .. encode(val, seen)
            end
        end
        seen[v] = nil
        return "{" .. table.concat(parts, ",") .. "}"
    end
    return "null"
end

function JSON.encode(v) return encode(v) end

-- Decoder ------------------------------------------------------------------------
local function decodeError(s, i, msg)
    error(string.format("JSON.decode: %s at %d", msg, i), 0)
end

local function skip(s, i)
    return s:find("[^ \t\r\n]", i) or #s + 1
end

local decodeValue

local function decodeString(s, i)
    local out, j = {}, i + 1
    while true do
        local c = s:sub(j, j)
        if c == "" then decodeError(s, j, "unterminated string") end
        if c == '"' then return table.concat(out), j + 1 end
        if c == "\\" then
            local e = s:sub(j + 1, j + 1)
            local map = { ['"'] = '"', ['\\'] = '\\', ['/'] = '/', b = '\b', f = '\f', n = '\n', r = '\r', t = '\t' }
            if map[e] then
                out[#out + 1] = map[e]
                j = j + 2
            elseif e == "u" then
                local hex = s:sub(j + 2, j + 5)
                local cp = tonumber(hex, 16)
                if not cp then decodeError(s, j, "bad \\u escape") end
                j = j + 6
                -- surrogate pair
                if cp >= 0xD800 and cp <= 0xDBFF and s:sub(j, j + 1) == "\\u" then
                    local lo = tonumber(s:sub(j + 2, j + 5), 16)
                    if lo and lo >= 0xDC00 and lo <= 0xDFFF then
                        cp = 0x10000 + (cp - 0xD800) * 0x400 + (lo - 0xDC00)
                        j = j + 6
                    end
                end
                out[#out + 1] = utf8.char(cp)
            else
                decodeError(s, j, "bad escape")
            end
        else
            local k = s:find('["\\]', j) or #s + 1
            out[#out + 1] = s:sub(j, k - 1)
            j = k
        end
    end
end

decodeValue = function(s, i)
    i = skip(s, i)
    local c = s:sub(i, i)
    if c == "{" then
        local obj = {}
        i = skip(s, i + 1)
        if s:sub(i, i) == "}" then return obj, i + 1 end
        while true do
            if s:sub(i, i) ~= '"' then decodeError(s, i, "expected key") end
            local key
            key, i = decodeString(s, i)
            i = skip(s, i)
            if s:sub(i, i) ~= ":" then decodeError(s, i, "expected ':'") end
            local val
            val, i = decodeValue(s, i + 1)
            obj[key] = val
            i = skip(s, i)
            local d = s:sub(i, i)
            if d == "}" then return obj, i + 1 end
            if d ~= "," then decodeError(s, i, "expected ',' or '}'") end
            i = skip(s, i + 1)
        end
    elseif c == "[" then
        local arr = JSON.array({})
        i = skip(s, i + 1)
        if s:sub(i, i) == "]" then return arr, i + 1 end
        while true do
            local val
            val, i = decodeValue(s, i)
            arr[#arr + 1] = val
            i = skip(s, i)
            local d = s:sub(i, i)
            if d == "]" then return arr, i + 1 end
            if d ~= "," then decodeError(s, i, "expected ',' or ']'") end
            i = i + 1
        end
    elseif c == '"' then
        return decodeString(s, i)
    elseif s:sub(i, i + 3) == "true" then
        return true, i + 4
    elseif s:sub(i, i + 4) == "false" then
        return false, i + 5
    elseif s:sub(i, i + 3) == "null" then
        return nil, i + 4
    else
        local num = s:match("^-?%d+%.?%d*[eE]?[-+]?%d*", i)
        if not num or num == "" then decodeError(s, i, "unexpected character") end
        return tonumber(num), i + #num
    end
end

-- Returns the value, or nil plus an error message.
function JSON.decode(s)
    if type(s) ~= "string" then return nil, "not a string" end
    local okD, v, i = pcall(decodeValue, s, 1)
    if not okD then return nil, tostring(v) end
    if skip(s, i) <= #s then return nil, "trailing data" end
    return v
end

return JSON
]]

__ya_sources["utils.probe_log"] = [[
-- probe_log.lua
-- Automatic per-cycle launch/monitor diagnostics written to `launch.log`.
--
-- Whenever the app is launched via Menu 1 (Launch All + Monitor), the monitor loop
-- records one line per instance per cycle so that, after a bug (e.g. a clone staying
-- "running" after a force-close), we can just read launch.log instead of running
-- manual diagnostic tools by hand. Lines are written and flushed immediately (open
-- + append + close each time) so nothing is lost if the process is killed.

local APK = require("managers.apk")
local Shell = require("utils.shell")
local Paths = require("core.paths")

local ProbeLog = {}

local path = Paths.resolve("launch.log")
local enabled = true

function ProbeLog.configure(conf)
    conf = conf or {}
    enabled = conf.launchLogEnabled ~= false
    if conf.launchLogPath and conf.launchLogPath ~= "" then
        path = Paths.resolve(conf.launchLogPath)
    end
end

-- (Re)create the log with a header. Called at monitor start so each session has a
-- fresh, bounded file.
function ProbeLog.init()
    if not enabled then return end
    local f = io.open(path, "w")
    if not f then return end
    f:write("-- rejoin auto-probe log " .. os.date("%Y-%m-%d %H:%M:%S") .. "\n")
    f:close()
end

-- Append a single line (plain text), flushing immediately.
function ProbeLog.line(str)
    if not enabled then return end
    if not str or str == "" then return end
    local f = io.open(path, "a")
    if not f then return end
    f:write(str .. "\n")
    f:close()
end

local function trim(s)
    return (s or ""):gsub("%s+$", "")
end

-- Record one line per configured instance: who, current status, process evidence and
-- the ACTIVE decision (RSS vs threshold). This is the evidence we need the next time a
-- close-1 bug is reproduced.
function ProbeLog.scan(instances, statuses)
    if not enabled then return end
    instances = instances or {}
    local thrMb = 50
    local okCfg, cfg = pcall(function() return require("core.config").get() end)
    if okCfg and cfg and tonumber(cfg.minRss) and tonumber(cfg.minRss) > 0 then
        thrMb = tonumber(cfg.minRss)
    end
    for i, inst in ipairs(instances) do
        local pkg = inst.package
        if pkg and pkg ~= "" then
            local okRow, errRow = pcall(function()
                local name = tostring(inst.name or (inst.id or i))
                local st = statuses and statuses[(inst.id or i)]

                local okRun, running = pcall(function() return APK.isRunning(pkg) end)
                local okAct, active = pcall(function() return APK.isActive(pkg) end)
                local pidOut = ""
                local okPid, _, pidRes = pcall(function() return Shell.exec("pidof " .. pkg) end)
                if okPid and pidRes and pidRes ~= "" and pidRes ~= "(dry-run)" then
                    pidOut = trim(pidRes)
                end
                local rss = APK.getRSSinKB(pkg)
                if rss and rss < 0 then rss = "?" end

                ProbeLog.line(string.format(
                    "[%s] %s | pkg=%s | status=%s | running=%s | isActive=%s | pid=%s | rss=%s KB | thr=%d MB",
                    os.date("%H:%M:%S"),
                    name,
                    pkg,
                    tostring(st or "?"),
                    tostring(okRun and running or "?"),
                    tostring(okAct and active or "?"),
                    (pidOut ~= "" and pidOut) or "-",
                    tostring(rss),
                    thrMb
                ))
            end)
            if not okRow then
                ProbeLog.line(string.format("[%s] scan_error [%s] %s",
                    os.date("%H:%M:%S"), tostring(inst.id or i), tostring(errRow)))
            end
        end
    end
end

return ProbeLog]]

__ya_sources["utils.shell"] = [[
local Logger = require("core.logger")
local Runtime = require("core.runtime")

local Shell = {}

-- Per-command timeout (seconds). `io.popen` blocks forever with no timeout, so a hung
-- su/dumpsys call would freeze the whole tool (Termux would stop accepting input).
-- The timeout is applied with toybox/coreutils `timeout`, falling back to no-wait if
-- it's unavailable. Overridable via config.shellTimeout.
local function cmdTimeout()
    local conf = nil
    local ok = pcall(function() conf = require("core.config").get() end)
    if ok and conf and tonumber(conf.shellTimeout) and tonumber(conf.shellTimeout) > 0 then
        return tonumber(conf.shellTimeout)
    end
    return 10
end

-- Whether a `timeout` tool is available (cached). If missing we run without one so a
-- command still executes on restricted shells where `timeout` isn't installed.
local timeoutCheckDone = false
local timeoutAvailable = false
local function hasTimeoutTool()
    if not timeoutCheckDone then
        timeoutCheckDone = true
        local f = io.popen("command -v timeout 2>/dev/null")
        if f then
            local out = f:read("*l") or ""
            f:close()
            timeoutAvailable = (out ~= "")
        end
    end
    return timeoutAvailable
end

-- Apply a timeout to a command. Runs `timeout <secs> <cmd>` when the tool exists.
local function applyTimeout(cmd)
    if hasTimeoutTool() then
        return "timeout " .. cmdTimeout() .. " " .. cmd
    end
    return cmd
end

-- Whether commands should run with root (`su -c '...'`). Reads `useRoot` from the
-- project config; defaults to true because the supported setup is a rooted device
-- (Magisk). On a non-root device set `useRoot = false` in config/config.lua.
local function rootEnabled()
    local ok, conf = pcall(function() return require("core.config").get() end)
    if ok and conf and conf.useRoot ~= nil then
        return conf.useRoot == true
    end
    return true
end

-- Fail early when root was disabled or su did not grant uid 0.
function Shell.rootAvailable()
    if not rootEnabled() then return false, "useRoot=false" end
    local ok, out = Shell.exec("id -u")
    if ok and out and out:match("^%s*0%s*$") then return true end
    return false, out or "su_failed"
end

-- Wrap a shell command in `su -c '...'` so ps/pidof/pgrep/am/logcat run as root. A
-- rooted device running Termux as a NORMAL user cannot see other apps' processes
-- (Android 11+), which previously made every process probe return empty and broke
-- per-instance health/Launch All detection. Running as root fixes that.
local function runWithRoot(cmd)
    if not rootEnabled() then
        return cmd
    end
    local inner = cmd:gsub("'", "'\\''")
    return "su -c '" .. inner .. "'"
end

-- Execute a command and return (ok, output). Uses io.popen to capture stdout.
-- If runtime dry-run is enabled, log the command and return a simulated success output.
function Shell.exec(cmd)
    if not cmd then return false, "no_cmd" end
    if Runtime.isDryRun() then
        Logger.debug("[dry-run] Shell.exec")
        -- Simulate outputs for common probes
        if cmd:match("^pidof %S+") then
            -- simulate process not running by default (empty output)
            return true, ""
        end
        return true, "(dry-run)"
    end

    local full = runWithRoot(applyTimeout(cmd))
    -- Commands may contain session cookies or SQL values. Never write them to logs.
    Logger.debug("Shell.exec")
    -- stdin from /dev/null: when Magisk `su` sees a terminal on stdin it switches the
    -- terminal to raw mode while the command runs, and Ctrl+C then reaches su as a
    -- plain byte instead of stopping the engine. No command here reads stdin.
    -- Grouped so the redirects cover every part of a compound command.
    local f = io.popen("{ " .. full .. "\n} 2>&1 </dev/null")
    if not f then return false, "popen_failed" end
    local out = f:read("*a") or ""
    local ok, _, code = f:close()
    -- Preserve the exit status so callers can distinguish empty output from failure.
    return ok == true, (out:gsub("\n+$", "")), code
end

return Shell
]]

__ya_sources["utils.timer"] = [[
local Logger = require("core.logger")
local Timer = {}

function Timer.sleep(seconds)
    seconds = tonumber(seconds) or 1
    -- Prefer luasocket if available (native, and does not block signal delivery).
    local ok, socket = pcall(require, "socket")
    if ok and socket and socket.sleep then
        socket.sleep(seconds)
        return true
    end

    -- Fallback to os.execute sleep (Termux/Linux). With a lua-posix SIGINT handler
    -- installed, `system()` only delays the signal by at most the current chunk
    -- (<=0.25s in sleepInterruptible), so Ctrl+C still stops the monitor quickly.
    -- NOTE: do NOT use a busy-wait (os.clock) here — it pins a core at 100% CPU the
    -- whole time and makes the device hot/unresponsive (and does NOT fix Ctrl+C,
    -- which needs the lua-posix handler, not just non-blocked signals).
    os.execute("sleep " .. tostring(seconds))
    return true
end

-- Sleep in small steps so a SIGINT handler (that flips isStopped to true) can break
-- out quickly instead of waiting out the full interval. isStopped is a function
-- returning true to abort early.
function Timer.sleepInterruptible(seconds, isStopped)
    seconds = tonumber(seconds) or 1
    local step = 0.25
    local elapsed = 0
    while elapsed < seconds do
        if isStopped and isStopped() then
            return false
        end
        local chunk = math.min(step, seconds - elapsed)
        Timer.sleep(chunk)
        elapsed = elapsed + chunk
    end
    return not (isStopped and isStopped())
end

return Timer
]]

_G.__YA_SUPERVISOR = [[
#!/data/data/com.termux/files/usr/bin/sh
# Rejoin single-file terminal supervisor (embedded in yanamin.lua).
#
# Derived from run.sh: the monitor loop spends nearly all its time inside
# os.execute/io.popen, and POSIX blocks SIGINT there. This shell wrapper owns the
# terminal so Ctrl+C stops the engine, and restarts it when the cookie-paste
# flow exits 75.
#
# The working directory is preserved. core.paths resolves config and data under
# /sdcard/yanamin (or YANAMIN_HOME), independent of the loader location.

TARGET=__TARGET__

# Interpreter may be named lua, lua5.3, lua5.4 or luajit depending on which
# package the device installed, so never assume the bare name "lua".
LUA_BIN=$(command -v lua5.3 2>/dev/null || command -v lua 2>/dev/null || command -v lua5.4 2>/dev/null || command -v luajit 2>/dev/null || echo lua)

exec 3<&0
TTY_STATE=
if [ -t 3 ]; then
    stty sane <&3 2>/dev/null
    stty echo icanon opost onlcr <&3 2>/dev/null
    TTY_STATE=$(stty -g <&3 2>/dev/null) || TTY_STATE=
fi
PID=
restore_tty() {
    if [ -n "$TTY_STATE" ]; then
        stty "$TTY_STATE" <&3 2>/dev/null || stty sane <&3 2>/dev/null
    elif [ -t 3 ]; then
        stty sane <&3 2>/dev/null
    fi
    if [ -t 3 ]; then stty echo icanon opost onlcr <&3 2>/dev/null; fi
}
stop_child() {
    if [ -n "$PID" ]; then
        kill -TERM "$PID" 2>/dev/null
        wait "$PID" 2>/dev/null
    fi
    restore_tty
    exit "$1"
}
trap 'stop_child 130' INT
trap 'stop_child 143' TERM
while :; do
    # Explicit stdin redirection keeps the background Lua off /dev/null;
    # fd 3 holds the original terminal even without /dev/tty.
    REJOIN_WRAPPER=1 "$LUA_BIN" "$TARGET" "$@" <&3 &
    PID=$!
    wait "$PID"
    STATUS=$?
    PID=
    restore_tty
    if [ "$STATUS" -ne 75 ]; then exit "$STATUS"; fi
    # Cookie input used a long paste. Redraw a fresh menu in a new Lua process.
    if [ -t 3 ]; then printf '\033[2J\033[H'; fi
done
]]

local __ya_real_require = require
local __ya_loaded = {}

local function __ya_source(name)
    return __ya_sources[name]
end

local function __ya_require(name)
    local cached = __ya_loaded[name]
    if cached ~= nil then return cached end
    local src = __ya_sources[name]
    if src == nil then
        -- Optional C modules (lfs, socket, posix.signal) stay external so the
        -- pcall fallbacks in utils/ keep working.
        return __ya_real_require(name)
    end
    local chunk, err
    if load then
        chunk, err = load(src, "@" .. name, "t", _G)
    else
        chunk, err = loadstring(src, "@" .. name)
        if chunk then setfenv(chunk, _G) end
    end
    if not chunk then
        error("yanamin bundle: cannot compile module " .. tostring(name) .. ": " .. tostring(err), 0)
    end
    local ok, mod = pcall(chunk)
    if not ok then
        error("yanamin bundle: module " .. tostring(name) .. " failed: " .. tostring(mod), 0)
    end
    __ya_loaded[name] = mod
    return mod
end

_G.require = __ya_require
_G.__ya_require = __ya_require
_G.__ya_source = __ya_source

-- Entry point (main.lua)
-- Keep `lua main.lua` as the single entrypoint. The shell supervisor owns the
-- terminal while Lua runs, so Ctrl+C works even during os.execute/io.popen.
-- REJOIN_WRAPPER prevents the supervisor's child from launching another one.
if os.getenv("REJOIN_WRAPPER") ~= "1" then
    local function shellQuote(value)
        return "'" .. tostring(value):gsub("'", "'\\''") .. "'"
    end
    local command
    if type(__YA_SUPERVISOR) == "string" then
        local Paths = require("core.paths")
        local supervisor = Paths.data("yanamin_wrapper.sh")
        local target = (arg and arg[0]) or "yanamin.lua"
        if not target:match("^[/\\]") then target = (os.getenv("PWD") or ".") .. "/" .. target end
        local content = __YA_SUPERVISOR:gsub("__TARGET__", function() return shellQuote(target) end)
        local saved, err = require("utils.file").write(supervisor, content)
        if not saved then error("Cannot write terminal supervisor: " .. tostring(err)) end
        command = "sh " .. shellQuote(supervisor)
    else
        local scriptDir = (arg and arg[0] and arg[0]:match("^(.*[/\\])")) or ""
        command = "sh " .. shellQuote(scriptDir .. "run.sh")
    end
    for i = 1, #(arg or {}) do
        command = command .. " " .. shellQuote(arg[i])
    end
    local ok, _, code = os.execute(command)
    if type(ok) == "number" then
        -- Lua 5.1 returns the wait status as a number; newer Lua returns a
        -- boolean plus the exit code.
        os.exit(ok > 255 and math.floor(ok / 256) or ok)
    end
    os.exit(ok and 0 or (code or 1))
end

-- Recover terminal mode left by a previous interrupted cookie paste before any
-- logs or menu text. A redirected/headless stdin makes stty fail harmlessly.
local ttyReady = os.execute("stty sane 2>/dev/null")
if ttyReady == true or ttyReady == 0 then
    os.execute("stty echo icanon opost onlcr 2>/dev/null")
    io.write("\r\27[2J\27[H")
    io.flush()
end

local Logger = require("core.logger")
local State = require("core.state")

Logger.info(State.get())

State.set("MENU")

Logger.info(State.get())

-- Parse simple CLI flags
local args = arg or {}
local headless = false
local skipWizard = false
local startMonitorFlag = false
local autoLaunchFlag = false
local configSource = nil
local dryRun = false
local doctorFlag = false
local installHeartbeatFlag = false
local enableWindowLayoutFlag = false
local migratePresetsFlag = false
for i = 1, #args do
    local a = args[i]
    if a == "--headless" or a == "--no-interactive" then headless = true end
    if a == "--no-wizard" then skipWizard = true end
    if a == "--start-monitor" then startMonitorFlag = true end
    if a == "--auto-launch" then autoLaunchFlag = true end
    if a == "--dry-run" then dryRun = true end
    if a == "--doctor" then doctorFlag = true end
    if a == "--install-heartbeat" then installHeartbeatFlag = true end
    if a == "--enable-window-layout" then enableWindowLayoutFlag = true end
    if a == "--migrate-presets" then migratePresetsFlag = true end
    if a == "--hwid" then
        print(require("managers.remote").deviceId())
        os.exit(0)
    end
    if a == "--config" then
        local nextArg = args[i+1]
        if nextArg and nextArg:sub(1,2) ~= "--" then
            configSource = nextArg
        end
    end
end

-- Set runtime dry-run early
local Runtime = require("core.runtime")
if dryRun then
    Runtime.setDryRun(true)
    Logger.info("Runtime: dry-run mode enabled")
end

-- Everything the tool owns lives in one folder; tell the user where it is.
require("core.paths").announce()

-- Ensure configuration exists (setup will copy template -> config if needed)
local Setup = require("core.setup")
local ok, created_or_err = Setup.ensureConfig(configSource)
if not ok then
    Logger.error("Failed to ensure config: " .. tostring(created_or_err))
    os.exit(1)
end
local Config = require("core.config")

-- Initialize logger path from loaded config
local conf = Config.get() or {}
if conf.logPath then
    Logger.setLogPath(require("core.paths").resolve(conf.logPath))
end

-- Root is required for package/process discovery and recovery. Stop before the wizard
-- or menu if su is disabled or does not grant uid 0.
if not dryRun then
    local Shell = require("utils.shell")
    local rootOk, rootErr = Shell.rootAvailable()
    if not rootOk then
        local msg = "Root tidak aktif atau izin su ditolak. Aktifkan akses root dan pastikan useRoot = true di config/config.lua, lalu jalankan ulang."
        Logger.error(msg .. " (" .. tostring(rootErr) .. ")")
        print("\n[FATAL] " .. msg)
        os.exit(1)
    end
end

if ok and created_or_err == true and not skipWizard and not headless then
    local Wizard = require("core.setup_wizard")
    local wok, werr = Wizard.run()
    if not wok then
        Logger.warn("Setup wizard did not complete: " .. tostring(werr))
        Logger.info("You can edit config/config.lua manually or re-run the wizard later.")
    end
end
local data = conf

local InstanceManager = require("managers.instance")
InstanceManager.load(Config.get())

-- Warn about instances whose package is not installed on this device (e.g. a leftover
-- placeholder from the config template). Warning only — nothing is blocked.
local missing = InstanceManager.missingPackages()
if #missing > 0 then
    print("")
    print("[WARN] Package instance ini TIDAK terpasang di device:")
    for _, m in ipairs(missing) do
        print(string.format("  - id=%s  %s  (%s)", tostring(m.id), tostring(m.name), tostring(m.package)))
    end
    print("      Buang lewat menu Instances Manager > 4) Delete, atau edit config.")
    print("")
end

-- One-shot: environment doctor -- run on EACH device, diff outputs to find the
-- dependency/fingerprint difference causing "inject [OK] tapi app ga login" on one
-- device but not the other. Exits after printing.
if doctorFlag then
    local Doctor = require("managers.doctor")
    local report = Doctor.run()
    print("\n===== DOCTOR REPORT (jalankan di KEDUA device, diff outputnya) =====")
    print(report)
    print("====================================================================")
    os.exit(0)
end

if migratePresetsFlag then
    local c = Config.get() or {}
    local msg = InstanceManager.migrateToPresets(c)
    if not msg then
        print("OK: preset tidak perlu dipindah")
        os.exit(0)
    end
    local saved, err = Config.save(c)
    print(saved and ("OK: " .. msg) or ("GAGAL: " .. tostring(err)))
    os.exit(saved and 0 or 1)
end

-- One-shot (installer): switch the floating window grid on in the user's config.
if enableWindowLayoutFlag then
    local c = Config.get() or {}
    c.windowLayout = type(c.windowLayout) == "table" and c.windowLayout or {}
    if c.windowLayout.enabled == true then
        print("OK: auto atur jendela sudah nyala")
        os.exit(0)
    end
    c.windowLayout.enabled = true
    local saved, err = Config.save(c)
    print(saved and "OK: auto atur jendela dinyalakan" or ("GAGAL: " .. tostring(err)))
    os.exit(saved and 0 or 1)
end

-- One-shot: (re)install the in-game heartbeat script into the Delta autoexecute folder.
if installHeartbeatFlag then
    local Heartbeat = require("managers.heartbeat")
    local hbOk, hbMsg = Heartbeat.install()
    print((hbOk and "OK: " or "GAGAL: ") .. tostring(hbMsg))
    os.exit(hbOk and 0 or 1)
end

-- Headless mode: optionally start monitor immediately
if headless and startMonitorFlag then
    Logger.info("Headless mode: starting monitor")
    local Monitor = require("managers.monitor")
    -- --auto-launch behaves like Menu 1: launch all clones (Starting -> Running) with
    -- optimizer applied, then monitor. Without it, only the monitor runs (no launch).
    local opts = autoLaunchFlag and { autoLaunch = true } or nil
    Monitor.start(Config.get(), opts)
    os.exit(0)
end

-- Interactive menu loop
local function prompt(msg)
    io.write(msg)
    io.flush()
    local line = io.read()
    -- Ctrl+C / EOF while in the menu returns nil; treat it as a clean hard stop.
    if line == nil then
        print("\nInterrupted by Ctrl+C; exiting.")
        os.exit(0)
    end
    return line
end

while true do
    print('\nMain Menu:\n  1) Launch All + Monitor\n  2) Instances Manager\n  3) Settings\n  4) AutoExecute Manager\n  5) Inject Cookie\n  6) Auto-boot (Termux:Boot)\n  7) Uninstall yanamin\n  8) Discord Webhook\n  9) Jendela & Mode Hemat\n 10) Exit\n 11) Preset Game\n 12) Antrean & Heartbeat\n 13) Start Monitor (tanpa launch)\n 14) Input Key Delta\n  (tekan Ctrl+C untuk berhenti)\n')
    local choice = prompt("Choose: ") or ""
    choice = choice:match("^%s*(.-)%s*$")
    if choice == "1" then
        local list = InstanceManager.getAll()
        if #list == 0 then
            print("No instances configured.")
        else
            -- Launch clones one at a time (Starting -> Running) inside the live monitor
            -- dashboard; the monitor then watches/recovers them.
            local Monitor = require("managers.monitor")
            Monitor.start(Config.get(), { autoLaunch = true })
            if Monitor.interrupted() then
                print("Monitor stopped by Ctrl+C; exiting.")
                os.exit(0)
            end
            break
        end
    elseif choice == "2" then
        local InstancesCLI = require("core.instances_cli")
        InstancesCLI.run()
    elseif choice == "3" then
        local SettingsCLI = require("core.settings_cli")
        SettingsCLI.run()
    elseif choice == "4" then
        local AutoExecuteCLI = require("core.autoexecute_cli")
        AutoExecuteCLI.run()
    elseif choice == "5" then
        local InjectCookieCLI = require("core.inject_cookie_cli")
        InjectCookieCLI.run()
    elseif choice == "6" then
        local BootCLI = require("core.boot_cli")
        BootCLI.run()
    elseif choice == "7" then
        local UninstallCLI = require("core.uninstall_cli")
        UninstallCLI.run()
    elseif choice == "8" then
        require("core.webhook_cli").run()
    elseif choice == "9" then
        require("core.display_cli").run()
    elseif choice == "11" then
        require("core.preset_cli").run()
    elseif choice == "12" then
        require("core.launch_cli").run()
    elseif choice == "13" then
        require("managers.monitor").start(Config.get())
    elseif choice == "14" then
        require("core.delta_key_cli").run()
    elseif choice == "10" or choice == "0" then
        print("Exiting main")
        break
    else
        print("Unknown choice")
    end
end
